window.UE_V5_DATA={"questions":[{"id":"Q5-ASM-001","topic":"Asma","mode":"decorar","style":"Raciocínio rápido","question":"Na passagem de plantão de um asmático ainda dispneico, qual tendência gasométrica sugere fadiga dos músculos respiratórios?","options":["PaCO₂ que deixa de estar reduzida e passa a subir","Alcalose respiratória com PaCO₂ cada vez menor","PaO₂ normal após broncodilatador","Bicarbonato sérico isoladamente normal"],"answer":0,"explanation":"Com obstrução crítica, a hiperventilação pode falhar e a PaCO₂ aumentar, exigindo avaliação urgente.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Gasometria","difficulty":"difícil"},{"id":"Q5-ASM-002","topic":"Asma","mode":"decorar","style":"Aplicação clínica","question":"Em paciente com crise asmática e urticária, hipotensão e edema de lábios após alimento, qual prioridade farmacológica muda?","options":["Antibiótico para pneumonia","Somente prednisona oral","Sulfato de magnésio antes de avaliar anafilaxia","Adrenalina intramuscular imediata"],"answer":3,"explanation":"O diagnóstico concomitante de anafilaxia torna a adrenalina IM prioritária.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Conduta imediata","difficulty":"média"},{"id":"Q5-ASM-003","topic":"Asma","mode":"decorar","style":"Pegadinha","question":"Após vários ciclos de broncodilatador na crise asmática, o paciente parece menos sibilante, mas está sonolento e com pouca entrada de ar. O achado representa:","options":["Resolução segura do broncoespasmo","Efeito esperado da prednisona","Ameaça à vida por ventilação criticamente reduzida","Critério isolado de alta"],"answer":2,"explanation":"A queda do ruído respiratório com piora do sensório indica perigo, não melhora.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Sinais de gravidade","difficulty":"média"},{"id":"Q5-ASM-004","topic":"Asma","mode":"decorar","style":"Comparação","question":"Na crise asmática moderada, qual objetivo justifica administrar corticoide sistêmico cedo, mesmo que o SABA alivie rapidamente?","options":["Dilatar o brônquio em segundos","Reduzir inflamação persistente e risco de recaída","Substituir oxigênio se houver hipoxemia","Tratar infecção bacteriana oculta de rotina"],"answer":1,"explanation":"SABA trata broncoconstrição; corticoide sistêmico combate a inflamação que mantém a exacerbação.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Fármacos","difficulty":"difícil"},{"id":"Q5-ASM-005","topic":"Asma","mode":"decorar","style":"Tratamento","question":"Qual situação torna mais defensável solicitar radiografia de tórax durante exacerbação asmática?","options":["Febre focal, ausculta assimétrica ou suspeita de complicação","Melhora imediata após quatro jatos e ausculta normal","Crise leve típica sem febre","Somente para confirmar diagnóstico de asma já conhecido"],"answer":0,"explanation":"O exame não é rotineiro, mas ajuda quando há pneumonia, pneumotórax ou quadro atípico.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Exames","difficulty":"média"},{"id":"Q5-ASM-006","topic":"Asma","mode":"decorar","style":"Avaliação crítica","question":"A ausência de melhora após tratamento inicial de crise asmática grave deve levar a considerar qual adjuvante de forma seletiva?","options":["Aminofilina por rotina","Antibiótico amplo sem foco","Sedação para reduzir ansiedade","Magnésio intravenoso"],"answer":3,"explanation":"Magnésio IV pode ser considerado em exacerbação grave refratária ao manejo inicial.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Escalonamento","difficulty":"média"},{"id":"Q5-ASM-007","topic":"Asma","mode":"decorar","style":"Cálculo e valores","question":"Qual é a diferença essencial entre estridor predominante e sibilância expiratória difusa?","options":["Estridor caracteriza broncoconstrição periférica","Sibilância expiratória é típica de corpo estranho laríngeo","Estridor sugere obstrução de vias aéreas superiores","Ambos excluem risco de obstrução crítica"],"answer":2,"explanation":"Estridor aponta principalmente para via aérea superior e requer avaliação dirigida.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Diferencial","difficulty":"difícil"},{"id":"Q5-ASM-008","topic":"Asma","mode":"decorar","style":"Diferenciais","question":"Depois de alta por exacerbação, qual alteração da prescrição reduz risco de novas crises melhor do que SABA isolado?","options":["Manter apenas SABA quando houver dispneia","Garantir tratamento controlador contendo corticoide inalatório","Prescrever antibiótico mensal profilático","Suspender todos os medicamentos após melhora"],"answer":1,"explanation":"O tratamento com corticoide inalatório é essencial para prevenir novas exacerbações.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Alta","difficulty":"média"},{"id":"Q5-ASM-009","topic":"Asma","mode":"decorar","style":"Raciocínio rápido","question":"Que conduta com oxigênio é inadequada em adulto asmático com SpO₂ 97% estável sem hipoxemia?","options":["Administrar O₂ de alto fluxo indiscriminadamente","Monitorar saturação durante reavaliação","Tratar broncoespasmo conforme gravidade","Reavaliar se surgir fadiga"],"answer":0,"explanation":"Oxigênio deve ser titulado quando necessário, evitando hiperóxia por rotina.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Oxigenação","difficulty":"média"},{"id":"Q5-ASM-010","topic":"Asma","mode":"decorar","style":"Aplicação clínica","question":"Na primeira hora de uma exacerbação, qual padrão de uso do salbutamol é mais compatível com necessidade de doses repetidas?","options":["Uma dose isolada seguida de alta sem reavaliação","Uso oral de salbutamol para todas as crises","Infusão venosa de salbutamol como primeira escolha","Aplicações inalatórias fracionadas com reavaliação frequente"],"answer":3,"explanation":"SABA inalatório pode ser repetido em intervalos curtos na fase inicial com avaliação de resposta.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Dose e via","difficulty":"difícil"},{"id":"Q5-ASM-011","topic":"Asma","mode":"decorar","style":"Pegadinha","question":"Se um paciente não consegue usar o aerossol por coordenação deficiente, mas está consciente e cooperativo, qual recurso melhora a entrega?","options":["Cápsula de antibiótico","Nebulização de água destilada isolada","Espaçador com orientação de técnica","Suspender broncodilatador"],"answer":2,"explanation":"O espaçador facilita a deposição do fármaco inalado.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Dispositivo","difficulty":"média"},{"id":"Q5-ASM-012","topic":"Asma","mode":"decorar","style":"Comparação","question":"Um residente propõe iniciar um macrolídeo em toda crise asmática não complicada. Qual argumento contesta a conduta?","options":["Toda crise é bacteriana","Antibióticos não são rotineiros sem indicação de infecção bacteriana","Antibióticos melhoram a reversibilidade bronquial em minutos","Macrolídeos substituem corticoide sistêmico"],"answer":1,"explanation":"Crise asmática não equivale a pneumonia bacteriana.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Uso racional","difficulty":"média"},{"id":"Q5-ASM-013","topic":"Asma","mode":"decorar","style":"Tratamento","question":"Sobre o pico de fluxo expiratório antes e após tratamento, qual interpretação é apropriada?","options":["É medida objetiva auxiliar, sempre interpretada com clínica e esforço","Valor isolado dispensa avaliação da consciência","Substitui avaliação da saturação","Sua melhora descarta toda causa de dispneia"],"answer":0,"explanation":"PFE ajuda a estimar obstrução e resposta, mas não é critério único de decisão.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"PFE","difficulty":"difícil"},{"id":"Q5-ASM-014","topic":"Asma","mode":"decorar","style":"Avaliação crítica","question":"Qual situação é contraindicação prática a deixar VNI atrasar outras medidas em crise asmática ameaçadora à vida?","options":["Paciente alerta que responde ao tratamento","Pico de fluxo subindo com boa fala","Saturação normal com ventilação adequada","Progressão de rebaixamento com exaustão respiratória"],"answer":3,"explanation":"Uma tentativa de VNI não deve atrasar proteção de via aérea em falência iminente.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Via aérea","difficulty":"média"},{"id":"Q5-ASM-015","topic":"Asma","mode":"decorar","style":"Cálculo e valores","question":"Qual achado na fala indica maior gravidade numa exacerbação?","options":["Conversar em frases completas","Relatar dispneia discreta ao caminhar","Conseguir pronunciar apenas palavras isoladas","Falar sem esforço após broncodilatador"],"answer":2,"explanation":"Fala limitada a palavras sugere exacerbação grave e trabalho respiratório elevado.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Gravidade","difficulty":"média"},{"id":"Q5-ASM-016","topic":"Asma","mode":"decorar","style":"Diferenciais","question":"Após 60 minutos de tratamento, paciente melhora mas continua com PFE baixo e uso de musculatura acessória. Qual decisão é mais segura?","options":["Alta apenas porque a saturação ultrapassou 92%","Continuar terapia e observação, avaliando internação","Suspender broncodilatador e acompanhamento","Ignorar tendência do PFE"],"answer":1,"explanation":"Resposta parcial requer reavaliação clínica e funcional, não alta automática.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Reavaliação","difficulty":"difícil"},{"id":"Q5-ASM-017","topic":"Asma","mode":"decorar","style":"Raciocínio rápido","question":"Em criança com sibilância, qual fator aumenta o risco de erro ao aplicar o esquema de adultos?","options":["Dose de corticoide sistêmico deve considerar peso e limite máximo","Saturação deixa de ter importância","Crianças nunca precisam de corticoide","PFE é obrigatório antes de oxigênio em risco grave"],"answer":0,"explanation":"Pediatria exige ajuste de dose por peso e acompanhamento da gravidade.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Pediatria","difficulty":"média"},{"id":"Q5-ASM-018","topic":"Asma","mode":"decorar","style":"Aplicação clínica","question":"Qual associação farmacológica é útil em crise grave porque atua em receptores diferentes das vias aéreas?","options":["Dois antibióticos de largo espectro","Diurético e vasoconstritor nasal","Mucolítico oral e anti-histamínico","Beta-2 agonista e anticolinérgico inalatório"],"answer":3,"explanation":"SABA e ipratrópio têm mecanismos complementares e podem reduzir internações em crises importantes.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Terapia combinada","difficulty":"média"},{"id":"Q5-ASM-019","topic":"Asma","mode":"decorar","style":"Pegadinha","question":"Diante de crise asmática com aumento progressivo de PaCO₂ e exaustão, que mudança do equilíbrio ácido-base pode surgir?","options":["Alcalose metabólica obrigatória","Acidose tubular renal isolada","Acidose respiratória","Alcalose metabólica por perda de cloro como regra"],"answer":2,"explanation":"Retenção de CO₂ por ventilação alveolar inadequada provoca acidose respiratória.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Gasometria","difficulty":"difícil"},{"id":"Q5-ASM-020","topic":"Asma","mode":"decorar","style":"Comparação","question":"Por que sedativo para um asmático exausto no pronto-socorro é especialmente arriscado?","options":["Aumenta diretamente o efeito broncodilatador do SABA","Pode deprimir o drive respiratório e mascarar deterioração","Previne hipercapnia de forma comprovada","Reduz necessidade de monitorização"],"answer":1,"explanation":"Sedação indiscriminada pode precipitar falência ventilatória.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Segurança","difficulty":"média"},{"id":"Q5-ASM-021","topic":"Asma","mode":"decorar","style":"Tratamento","question":"Qual informação de alta é indispensável além da prescrição do controlador em asma?","options":["Revisão da técnica inalatória e plano de ação","Orientação de interromper o tratamento se não houver tosse","Proibição permanente de atividade física para todos","Dispensar seguimento após crise"],"answer":0,"explanation":"Técnica, adesão, plano de ação e retorno precoce reduzem recorrência.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Alta","difficulty":"média"},{"id":"Q5-ASM-022","topic":"Asma","mode":"decorar","style":"Avaliação crítica","question":"Paciente apresenta asma e dispneia súbita com dor pleurítica unilateral e ausência localizada de murmúrio. Qual diagnóstico alternativo buscar?","options":["Broncoespasmo isolado confirmado","Anemia ferropriva sem exame","Rinite crônica como única causa","Pneumotórax"],"answer":3,"explanation":"Sintomas focais e dor pleurítica exigem investigar pneumotórax, mesmo com história de asma.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Diagnóstico diferencial","difficulty":"difícil"},{"id":"Q5-ASM-023","topic":"Asma","mode":"decorar","style":"Cálculo e valores","question":"Qual achado fortalece asma como mecanismo variável e não obstrução fixa isolada?","options":["Dispneia progressiva invariável há anos com tabagismo pesado","Espirometria pós-BD sempre fixa sem variabilidade","História de episódios flutuantes e reversibilidade documentada","Ausência de sintomas noturnos em todas as épocas"],"answer":2,"explanation":"Variabilidade clínica/funcional apoia asma, sem excluir sobreposição em alguns pacientes.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Diagnóstico","difficulty":"média"},{"id":"Q5-ASM-024","topic":"Asma","mode":"decorar","style":"Diferenciais","question":"Em exacerbação grave, qual intervenção deve ocorrer enquanto são coletados exames complementares?","options":["Aguardar tomografia para liberar SABA","Broncodilatação e suporte de oxigenação conforme necessidade","Esperar hemograma antes de avaliar esforço","Postergar todas as intervenções por 2 horas"],"answer":1,"explanation":"Tratamento não deve ser retardado por exames em um quadro agudo grave.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Priorização","difficulty":"média"},{"id":"Q5-ASM-025","topic":"Asma","mode":"decorar","style":"Raciocínio rápido","question":"Após crise, por que aumentar só o SABA de resgate sem rever controle é uma estratégia insuficiente?","options":["O broncodilatador isolado não trata a inflamação de base","SABA atua como imunossupressor prolongado","SABA previne remodelamento em monoterapia","A resposta imediata elimina risco futuro"],"answer":0,"explanation":"Recorrência pode indicar falta de controle anti-inflamatório e técnica/adaptação inadequadas.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Controle","difficulty":"difícil"},{"id":"Q5-ASM-026","topic":"Asma","mode":"decorar","style":"Aplicação clínica","question":"Qual combinação sugere resposta muito favorável ao tratamento inicial antes de pensar em alta?","options":["Tórax silencioso e sonolência","Dessaturação progressiva com fala difícil","PA estável apesar de piora ventilatória","Sinais vitais estáveis, redução do trabalho respiratório e melhora sustentada da função pulmonar"],"answer":3,"explanation":"Alta exige melhora clínica sustentada e plano de seguimento, não um dado isolado.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Critérios de alta","difficulty":"média"},{"id":"Q5-ASM-027","topic":"Asma","mode":"decorar","style":"Pegadinha","question":"Na ausculta de uma crise intensa, a presença de sibilos muito discretos pode ser enganosa porque:","options":["Broncoespasmo não produz sibilos em nenhuma situação","Sibilos leves sempre significam crise leve","O fluxo de ar pode estar extremamente baixo e produzir pouco ruído","Ausência de sibilo dispensa exame respiratório"],"answer":2,"explanation":"A quantidade de sibilância não é indicador linear de gravidade.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Armadilha","difficulty":"média"},{"id":"Q5-ASM-028","topic":"Asma","mode":"decorar","style":"Comparação","question":"Uma pessoa com asma controlada usa broncodilatador de alívio diariamente há semanas. Que hipótese deve orientar a consulta?","options":["Controle excelente pela frequência de uso","Controle inadequado e necessidade de rever adesão, técnica e tratamento controlador","Cura espontânea da inflamação","Ausência de risco de exacerbação"],"answer":1,"explanation":"Uso frequente de medicação de alívio indica revisão do controle.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Controle","difficulty":"difícil"},{"id":"Q5-ASM-029","topic":"Asma","mode":"decorar","style":"Tratamento","question":"Que medida é mais apropriada diante de exacerbação associada a suspeita de pneumonia focal?","options":["Tratar a crise e avaliar infecção bacteriana conforme achados","Abandonar o tratamento da broncoconstrição","Considerar antibiótico para todo asmático sem avaliar sinais","Suspender oxigênio apesar de hipoxemia"],"answer":0,"explanation":"A pneumonia pode coexistir, exigindo abordagem específica e tratamento da exacerbação.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Comorbidades","difficulty":"média"},{"id":"Q5-ASM-030","topic":"Asma","mode":"decorar","style":"Avaliação crítica","question":"Em paciente que apresenta broncoespasmo após exercício, mas também hipotensão e urticária, o maior risco de ancoragem diagnóstica é:","options":["Não solicitar espirometria no primeiro minuto","Priorizar saturação em paciente instável","Reconhecer doença concomitante","Confundir anafilaxia com crise asmática isolada"],"answer":3,"explanation":"Manifestação sistêmica deve acender alerta para anafilaxia.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Diferencial","difficulty":"média"},{"id":"Q5-ASM-031","topic":"Asma","mode":"decorar","style":"Cálculo e valores","question":"Qual resultado apoia variabilidade do fluxo expiratório numa espirometria diagnóstica de adulto com suspeita de asma?","options":["Queda de VEF₁ de 1% sem melhora","VEF₁/CVF invariável alto em toda avaliação","Aumento de VEF₁ >12% e >200 mL após broncodilatador","Saturação normal como única confirmação"],"answer":2,"explanation":"Reversibilidade significativa do VEF₁ em adulto apoia variabilidade do fluxo compatível com asma.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Espirometria","difficulty":"difícil"},{"id":"Q5-ASM-032","topic":"Asma","mode":"decorar","style":"Diferenciais","question":"Que dado da história sinaliza risco alto de exacerbação fatal mesmo com sintomas atuais moderados?","options":["Rinite leve sem crise","Intubação prévia por asma","Boa adesão ao tratamento controlador","Ausência de uso de SABA"],"answer":1,"explanation":"História de intubação por asma aumenta risco futuro e exige atenção.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Risco","difficulty":"média"},{"id":"Q5-ASM-033","topic":"Asma","mode":"decorar","style":"Raciocínio rápido","question":"Qual resposta cardiovascular pode ser esperada após SABA inalatório repetido sem indicar por si só alergia ao medicamento?","options":["Taquicardia e tremor","Bradicardia sustentada como regra","Bloqueio AV total habitual","Hipotensão anafilática obrigatória"],"answer":0,"explanation":"Taquicardia e tremor são efeitos simpaticomiméticos conhecidos.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Efeito adverso","difficulty":"média"},{"id":"Q5-ASM-034","topic":"Asma","mode":"decorar","style":"Aplicação clínica","question":"Por que um paciente pode ficar mais dispneico apesar de melhora da obstrução após muito SABA?","options":["SABA é incapaz de causar qualquer alteração metabólica","Toda dispneia residual é pneumonia","Redução de PFE é sempre falsa","Acidose láctica relacionada a doses altas pode contribuir, exigindo reavaliação"],"answer":3,"explanation":"Beta-2 agonistas em doses elevadas podem elevar lactato; interpretar clinicamente.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Lactato e SABA","difficulty":"difícil"},{"id":"Q5-ASM-035","topic":"Asma","mode":"decorar","style":"Pegadinha","question":"Numa crise asmática leve que responde de modo completo e imediato, qual atitude é preferível ao uso rotineiro de esteroide intravenoso?","options":["Dar metilprednisolona IV em dose elevada para todos","Prescrever sedativo oral","Individualizar necessidade de corticoide sistêmico conforme gravidade e risco","Usar antibiótico sem infecção"],"answer":2,"explanation":"Corticoide sistêmico não é obrigatório em toda crise leve resolvida rapidamente.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Escolha de via","difficulty":"média"},{"id":"Q5-ASM-036","topic":"Asma","mode":"decorar","style":"Comparação","question":"Na avaliação de crise asmática, qual parâmetro deve ser considerado junto ao PFE para evitar subestimar gravidade?","options":["Somente idade cronológica","Estado mental e esforço respiratório","Apenas eosinófilos periféricos","Exclusivamente peso do paciente"],"answer":1,"explanation":"A gravidade é avaliada clinicamente, não apenas pelo número do PFE.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Integração","difficulty":"média"},{"id":"Q5-ASM-037","topic":"Asma","mode":"decorar","style":"Tratamento","question":"Qual sintoma fora das crises favorece asma mal controlada e deve ser investigado na alta?","options":["Despertares noturnos por tosse ou chiado","Ausência de qualquer limitação","Nenhum uso de resgate","PFE estável com tratamento adequado"],"answer":0,"explanation":"Sintomas noturnos e uso frequente de alívio ajudam a avaliar controle.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Controle","difficulty":"difícil"},{"id":"Q5-ASM-038","topic":"Asma","mode":"decorar","style":"Avaliação crítica","question":"Se o médico não encontra sibilos, mas o paciente tem esforço extremo, confusão e hipoxemia, que interpretação não pode ser feita?","options":["Reavaliar via aérea e ventilação","Considerar obstrução crítica silenciosa","Buscar ajuda experiente","Excluir crise asmática grave apenas pela ausculta"],"answer":3,"explanation":"O silêncio auscultatório pode ser marcador de ventilação perigosamente limitada.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Armadilha","difficulty":"média"},{"id":"C5-ASM-001","topic":"Asma","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 24 anos com asma desde a infância, usando apenas salbutamol, chega após três dias de resfriado. FR 34, FC 132, SpO₂ 89% em ar ambiente; fala palavras isoladas e utiliza músculos acessórios. Recebe O₂ titulado, salbutamol repetido, ipratrópio e prednisolona. Após 45 minutos continua com SpO₂ 90% e PFE 32% do previsto. Qual decisão considera corretamente o risco atual?","options":["Dar alta porque o tratamento inicial já foi completo","Manter terapia intensiva na emergência, discutir internação/UTI e adjuvante como magnésio IV","Retirar broncodilatador para evitar taquicardia","Prescrever apenas macrolídeo oral e retorno em uma semana"],"answer":1,"explanation":"Resposta ruim com obstrução intensa após manejo inicial indica crise grave e necessidade de escalonamento e vigilância.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Refratariedade","difficulty":"avançada","classic_intro":"Caso clássico de Asma: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-ASM-002","topic":"Asma","mode":"casos","style":"Caso clínico avançado","question":"Homem de 38 anos chega com dispneia, urticária generalizada e edema labial 15 minutos depois de comer camarão. Há sibilância difusa, estridor discreto, PA 78/40, FC 125 e SpO₂ 91%. Sua esposa diz que ele tem asma e pede apenas nebulização. Qual escolha muda o desfecho mais imediatamente?","options":["Aplicar adrenalina intramuscular e iniciar suporte para anafilaxia, sem deixar de tratar broncoespasmo","Administrar apenas SABA nebulizado porque a causa é asmática","Dar prednisona oral e observar resposta por 60 minutos","Solicitar radiografia de tórax antes de medicação"],"answer":0,"explanation":"Envolvimento de pele, via aérea e hipotensão após exposição identifica anafilaxia; adrenalina IM é prioritária.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Anafilaxia","difficulty":"avançada","classic_intro":"Caso clássico de Asma: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-ASM-003","topic":"Asma","mode":"casos","style":"Caso clínico avançado","question":"Paciente asmático de 57 anos com dor torácica pleurítica súbita e dispneia intensa chega com SpO₂ 87% e MV muito reduzido à direita, mas sibilos à esquerda. Há tratamento recente com beta-2 agonista sem benefício. A PA é 100/60 e FC 118. Qual erro de ancoragem deve ser evitado?","options":["Avaliar diagnóstico pleural com exame e imagem apropriada","Fornecer oxigênio conforme necessidade","Monitorar instabilidade e esforço","Tratar todo o quadro como broncoespasmo, sem avaliar pneumotórax"],"answer":3,"explanation":"Dor pleurítica focal e assimetria importante sugerem complicação pleural, mesmo em asmático conhecido.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Diferencial","difficulty":"avançada"},{"id":"C5-ASM-004","topic":"Asma","mode":"casos","style":"Caso clínico avançado","question":"Adolescente de 16 anos com exacerbação por rinovírus apresenta dispneia e PFE inicial de 43%. Após três doses de SABA, o PFE sobe para 63%, a SpO₂ chega a 96%, mas ele segue ofegante ao andar e mora a três horas do serviço. Qual plano de decisão é mais seguro?","options":["Liberar imediatamente apenas pelo PFE >60%","Suspender corticoide porque houve melhora parcial","Individualizar observação/alta considerando resposta clínica sustentada, risco, acesso ao serviço e plano controlador","Considerar melhora da saturação como critério único"],"answer":2,"explanation":"Critérios de alta incluem estabilidade sustentada, fatores de risco e capacidade de retorno, não só um número.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Critérios de alta","difficulty":"avançada"},{"id":"C5-ASM-005","topic":"Asma","mode":"casos","style":"Caso clínico avançado","question":"Homem de 46 anos, asmático, chega agitado e taquipneico. Gasometria inicial: pH 7,49; PaCO₂ 29 mmHg. Após 90 minutos, apesar de vários broncodilatadores, ele está sonolento; pH 7,31, PaCO₂ 51, PaO₂ 58. Como interpretar a mudança?","options":["Melhora porque a PaCO₂ voltou ao valor normal","Falência ventilatória iminente por fadiga e retenção crescente de CO₂","Acidose metabólica exclusiva sem repercussão respiratória","Hiperventilação compensatória mais eficaz"],"answer":1,"explanation":"A virada de hipocapnia para hipercapnia em paciente exausto é sinal grave de deterioração ventilatória.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Gasometria","difficulty":"avançada","classic_intro":"Caso clássico de Asma: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-ASM-006","topic":"Asma","mode":"casos","style":"Caso clínico avançado","question":"Paciente de 31 anos com crise moderada melhora após SABA. Antes da alta, relata usar mais de um frasco de resgate por mês e não utilizar corticoide inalatório, embora tenha despertares noturnos duas vezes por semana. Que decisão evita novo retorno à urgência?","options":["Iniciar ou otimizar controlador contendo corticoide inalatório, revisar técnica e agendar seguimento precoce","Manter apenas o SABA porque aliviou hoje","Trocar broncodilatador por antibiótico profilático","Suspender todo tratamento de manutenção por 30 dias"],"answer":0,"explanation":"Alta segura inclui tratamento controlador, revisão de uso e plano de acompanhamento.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Alta","difficulty":"avançada"},{"id":"C5-ASM-007","topic":"Asma","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 63 anos com história de asma e insuficiência cardíaca apresenta ortopneia, edema de membros inferiores, B3, crepitações bibasais e sibilos. SpO₂ 88% e PA 170/100. Seu sobrinho chama o quadro de 'mais uma asma'. Qual abordagem inicial é mais adequada?","options":["Prescrever salbutamol como único tratamento","Ignorar congestão pelo achado de sibilos","Dar alta após anti-histamínico","Investigar e tratar congestão pulmonar/insuficiência cardíaca, além de avaliar broncoespasmo concomitante"],"answer":3,"explanation":"Sibilância pode ocorrer em edema pulmonar; a clínica de congestão exige diagnóstico alternativo/comórbido.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Diferencial","difficulty":"avançada"},{"id":"C5-ASM-008","topic":"Asma","mode":"casos","style":"Caso clínico avançado","question":"Paciente de 29 anos com asma, em uso de salbutamol repetido, fica menos dispneico, mas apresenta tremores e FC de 142 bpm. SpO₂ 96% e ausculta melhora. O potássio é 3,0 mEq/L. Qual conduta demonstra interpretação adequada?","options":["Atribuir a hipocalemia exclusivamente à infecção bacteriana","Administrar ainda mais SABA sem reavaliação","Reavaliar doses, eletrólitos, ECG e necessidade de reposição de potássio, mantendo atenção à obstrução","Desconsiderar hipocalemia porque a SpO₂ normalizou"],"answer":2,"explanation":"Beta-2 agonistas podem causar taquicardia e hipocalemia; é preciso equilibrar benefício e efeitos adversos.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Efeito adverso","difficulty":"avançada"},{"id":"C5-ASM-009","topic":"Asma","mode":"casos","style":"Caso clínico avançado","question":"Criança de 8 anos com asma tem FR 38, retrações e SpO₂ 90%; após broncodilatador inalatório melhora pouco. A mãe informa peso de 25 kg, ausência de terapia de controle e uso frequente do resgate. Qual princípio torna a escolha de corticoide mais segura?","options":["Aplicar dose adulta fixa máxima em qualquer criança","Calcular a dose sistêmica pelo peso pediátrico com teto recomendado e observar resposta","Evitar corticoide sistêmico por idade, mesmo em crise importante","Prescrever somente xaropes antitussígenos"],"answer":1,"explanation":"Tratamento pediátrico deve respeitar peso, dose máxima e gravidade da crise.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Pediatria","difficulty":"avançada"},{"id":"C5-ASM-010","topic":"Asma","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 42 anos chega com exacerbação leve, fala frases completas, SpO₂ 97% e PFE 78%. Melhora rapidamente com SABA e não apresenta febre ou sinais focais. Um residente solicita tomografia, gasometria e antibiótico de rotina. Qual plano é mais adequado?","options":["Dispensar exames e antibiótico de rotina, reavaliar resposta, técnica e controle da asma","Investigar pneumonia bacteriana por TC obrigatória","Iniciar antibiótico apesar da ausência de indícios","Internar obrigatoriamente em UTI"],"answer":0,"explanation":"Exames e antibióticos não são mandatórios em exacerbação típica que responde bem.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Exames","difficulty":"avançada"},{"id":"C5-ASM-011","topic":"Asma","mode":"casos","style":"Caso clínico avançado","question":"Homem de 48 anos com asma grave recebeu O₂ controlado, SABA, ipratrópio, corticoide e magnésio. Permanece com frequência respiratória de 36, movimento paradoxal, confusão e PaCO₂ crescente. Equipe sugere 'mais uma nebulização' antes de qualquer providência. Qual prioridade real?","options":["Esperar mais duas horas por efeito máximo do antibiótico","Administrar sedativo sem estratégia de via aérea","Suspender monitorização enquanto aguarda radiografia","Acionar equipe experiente para manejo avançado de via aérea e suporte ventilatório imediato"],"answer":3,"explanation":"Exaustão, alteração de consciência e falência ventilatória exigem suporte avançado sem demora.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"IOT","difficulty":"avançada","classic_intro":"Caso clássico de Asma: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-ASM-012","topic":"Asma","mode":"casos","style":"Caso clínico avançado","question":"Durante atendimento de crise asmática, homem de 50 anos tem roncos inspiratórios audíveis no pescoço, alteração recente de voz após cirurgia cervical e quase nenhum sibilo pulmonar. Saturação 94%, mas a dispneia é desproporcional à ausculta. Qual hipótese muda a avaliação?","options":["Crise asmática leve confirmada por qualquer ruído","DPOC confirmada sem espirometria","Obstrução de via aérea superior, exigindo investigação e preparo para proteção de via aérea","Congestão pulmonar obrigatória"],"answer":2,"explanation":"Estridor e mudança de voz favorecem obstrução alta, não broncoespasmo difuso.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Via aérea alta","difficulty":"avançada"},{"id":"Q5-DPO-001","topic":"DPOC","mode":"decorar","style":"Raciocínio rápido","question":"Uma pessoa com DPOC grave e SpO₂ 84% chega ao pronto atendimento; por que não se deve evitar oxigênio completamente?","options":["Toda oxigenoterapia provoca parada respiratória","A meta é manter saturação abaixo de 85%","Broncodilatador substitui oxigênio em hipoxemia","Hipoxemia é perigosa e precisa ser corrigida com alvo controlado"],"answer":3,"explanation":"O alvo usual de 88–92% equilibra correção de hipoxemia e risco de hipercapnia.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Oxigenação","difficulty":"difícil"},{"id":"Q5-DPO-002","topic":"DPOC","mode":"decorar","style":"Aplicação clínica","question":"Após iniciar O₂ controlado em DPOC exacerbada, qual exame pode revelar deterioração ventilatória apesar da melhora da saturação?","options":["Somente hemograma","Urocultura","Gasometria arterial com PaCO₂ e pH","Dosagem de troponina isolada"],"answer":2,"explanation":"SpO₂ não permite inferir PaCO₂ nem acidose; gasometria é útil em casos graves.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Gasometria","difficulty":"média"},{"id":"Q5-DPO-003","topic":"DPOC","mode":"decorar","style":"Pegadinha","question":"Na exacerbação, paciente mantém pH 7,29 e PaCO₂ 62 mmHg, mas está acordado e protege via aérea. Qual suporte costuma ser preferido inicialmente?","options":["Intubação obrigatória em todo pH abaixo de 7,30","Ventilação não invasiva monitorizada","Apenas aumentar oxigênio ao máximo","Alta com tratamento oral isolado"],"answer":1,"explanation":"VNI reduz necessidade de intubação em exacerbação hipercápnica selecionada.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"VNI","difficulty":"média"},{"id":"Q5-DPO-004","topic":"DPOC","mode":"decorar","style":"Comparação","question":"Qual sinal aponta falha potencial de VNI e necessidade de reavaliar intubação?","options":["Piora da consciência e incapacidade de proteger via aérea","Menor frequência respiratória com troca gasosa melhor","Maior conforto e pH melhorando","Cooperação e boa vedação da máscara"],"answer":0,"explanation":"Deterioração neurológica e falência de proteção de via aérea são sinais de alarme.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Escalonamento","difficulty":"difícil"},{"id":"Q5-DPO-005","topic":"DPOC","mode":"decorar","style":"Tratamento","question":"Com obstrução persistente espirométrica, qual medida é usada para classificar limitação do fluxo nos estágios GOLD 1–4?","options":["Somente escore de tosse","Presença de sibilo isolada","Número de cigarros do dia","VEF₁ percentual do previsto após broncodilatador"],"answer":3,"explanation":"GOLD 1–4 usa VEF₁ previsto pós-BD após confirmação de DPOC.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"GOLD","difficulty":"média"},{"id":"Q5-DPO-006","topic":"DPOC","mode":"decorar","style":"Avaliação crítica","question":"Um paciente tem VEF₁ de 42% do previsto após broncodilatador. Como classificar a limitação ao fluxo?","options":["GOLD 1","GOLD 2","GOLD 3","GOLD 4"],"answer":2,"explanation":"VEF₁ entre 30 e 49% caracteriza limitação grave (GOLD 3).","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"GOLD","difficulty":"média"},{"id":"Q5-DPO-007","topic":"DPOC","mode":"decorar","style":"Cálculo e valores","question":"Se VEF₁ pós-BD for 83% do previsto, mas relação VEF₁/CVF confirmar obstrução, a gravidade espirométrica é:","options":["GOLD 2","GOLD 1","GOLD 3","GOLD 4"],"answer":1,"explanation":"VEF₁ ≥80% do previsto é GOLD 1, desde que haja obstrução persistente.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"GOLD","difficulty":"difícil"},{"id":"Q5-DPO-008","topic":"DPOC","mode":"decorar","style":"Diferenciais","question":"Em exacerbação com aumento de dispneia e escarro francamente purulento, qual decisão costuma ser razoável?","options":["Considerar antibiótico conforme critérios e contexto","Antibiótico é proibido na ausência de febre","Intubação é obrigatória por purulência","Manter apenas antitussígeno"],"answer":0,"explanation":"Purulência com piora de sintomas apoia infecção bacteriana e indicação de antibiótico.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Antibioticoterapia","difficulty":"média"},{"id":"Q5-DPO-009","topic":"DPOC","mode":"decorar","style":"Raciocínio rápido","question":"Qual efeito adverso deve ser monitorado após doses repetidas de beta-2 agonista?","options":["Hipercalemia marcante como regra","Bradicardia profunda obrigatória","Sedação prolongada","Taquicardia e hipocalemia"],"answer":3,"explanation":"Beta-2 agonistas podem causar tremor, taquicardia e queda de potássio.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Segurança","difficulty":"média"},{"id":"Q5-DPO-010","topic":"DPOC","mode":"decorar","style":"Aplicação clínica","question":"Por que a espirometria em DPOC deve ser interpretada após broncodilatador?","options":["Excluir toda variabilidade possível das vias aéreas","Determinar a saturação durante exercício","Confirmar a persistência da limitação ao fluxo","Diagnosticar pneumonia concomitante"],"answer":2,"explanation":"O critério VEF₁/CVF pós-BD abaixo de 0,70 apoia obstrução persistente no contexto clínico correto.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Diagnóstico","difficulty":"difícil"},{"id":"Q5-DPO-011","topic":"DPOC","mode":"decorar","style":"Pegadinha","question":"Qual fator obriga a investigar tromboembolismo pulmonar durante suspeita de exacerbação da DPOC?","options":["Tosse habitual sem mudança","Dispneia desproporcional, dor pleurítica súbita ou sinais tromboembólicos","Melhora rápida com SABA","Purulência sem outros dados"],"answer":1,"explanation":"TEP pode simular ou precipitar piora, especialmente com sintomas atípicos e instabilidade.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Diferencial","difficulty":"média"},{"id":"Q5-DPO-012","topic":"DPOC","mode":"decorar","style":"Comparação","question":"Como classificar a presença de uma exacerbação moderada no último ano no agrupamento ABE do GOLD 2027?","options":["Grupo E, independentemente do escore de sintomas","Grupo A obrigatoriamente","Grupo B quando não há sibilos","GOLD 4 automaticamente"],"answer":0,"explanation":"Uma exacerbação moderada ou grave no último ano já pode definir E no esquema atual.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"GOLD ABE","difficulty":"média"},{"id":"Q5-DPO-013","topic":"DPOC","mode":"decorar","style":"Tratamento","question":"Qual diferença básica separa estágio GOLD 3 de grupo E?","options":["Ambos são determinados apenas pela frequência respiratória","O estágio 3 reflete o número de internações","O grupo E exige VEF₁ abaixo de 30%","GOLD 3 quantifica limitação espirométrica; E reflete histórico de exacerbações"],"answer":3,"explanation":"Estágios GOLD e agrupamento ABE descrevem dimensões diferentes.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Classificação","difficulty":"difícil"},{"id":"Q5-DPO-014","topic":"DPOC","mode":"decorar","style":"Avaliação crítica","question":"Após melhora clínica da exacerbação, qual intervenção não farmacológica deve entrar no plano?","options":["Suspensão de todas as atividades físicas permanentemente","Evitar vacinação respiratória","Cessação do tabagismo, vacinação e reabilitação quando indicada","Manter exposição à fumaça sem orientação"],"answer":2,"explanation":"A prevenção de recorrência inclui cessação de exposição, vacinação, técnica e reabilitação.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Alta","difficulty":"média"},{"id":"Q5-DPO-015","topic":"DPOC","mode":"decorar","style":"Cálculo e valores","question":"Paciente com DPOC apresenta edema periférico, turgência jugular e hiperfonese de P2. Que complicação crônica considerar?","options":["Pneumoperitônio","Hipertensão pulmonar com cor pulmonale","Asma infantil isolada","Insuficiência adrenal como causa única"],"answer":1,"explanation":"Hipoxemia crônica pode favorecer hipertensão pulmonar e sobrecarga direita.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Complicações","difficulty":"média"},{"id":"Q5-DPO-016","topic":"DPOC","mode":"decorar","style":"Diferenciais","question":"Qual combinação descreve a tríade de Anthonisen sem acrescentar outros sinais?","options":["Piora da dispneia, aumento do volume e da purulência do escarro","Febre, dor torácica e bradicardia","Hipoglicemia, dispneia e cefaleia","Leucocitose, edema e confusão"],"answer":0,"explanation":"A tríade orienta indicação de antibiótico na exacerbação.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Anthonisen","difficulty":"difícil"},{"id":"Q5-DPO-017","topic":"DPOC","mode":"decorar","style":"Raciocínio rápido","question":"Um exacerbad​o com pH 7,44, PaCO₂ 49 e bicarbonato alto, sem esforço, precisa de VNI automaticamente por PaCO₂ >45?","options":["Sim; todo PaCO₂ >45 exige VNI imediata","Sim; hipercapnia crônica é sempre emergência","Não; gasometria nunca importa","Não; interpretar acidose, sintomas, compensação e contexto"],"answer":3,"explanation":"Hipercapnia compensada sem acidose aguda não equivale automaticamente a indicação de VNI.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Gasometria","difficulty":"média"},{"id":"Q5-DPO-018","topic":"DPOC","mode":"decorar","style":"Aplicação clínica","question":"Qual duração costuma ser suficiente de corticoide sistêmico numa exacerbação típica de DPOC?","options":["Quatorze dias obrigatoriamente","Trinta dias sem redução","Cinco dias","Dose única para todos os casos"],"answer":2,"explanation":"Cursos curtos, frequentemente cinco dias, reduzem riscos de efeitos adversos.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Corticoide","difficulty":"média"},{"id":"Q5-DPO-019","topic":"DPOC","mode":"decorar","style":"Pegadinha","question":"Qual papel dos broncodilatadores de longa ação durante exacerbação grave?","options":["Dispensam tratamento agudo mesmo com insuficiência respiratória","Não substituem os de curta ação na abordagem inicial","São sempre contraindicados após estabilização","Agem mais rápido que SABA para todos"],"answer":1,"explanation":"A exacerbação demanda broncodilatação rápida; manutenção é reavaliada após estabilização.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Tratamento","difficulty":"difícil"},{"id":"Q5-DPO-020","topic":"DPOC","mode":"decorar","style":"Comparação","question":"Paciente com DPOC e secreção abundante usa nebulização com O₂ em alto fluxo e fica sonolento. Que risco deve ser investigado?","options":["Piora da retenção de CO₂ e acidose respiratória","Eliminação completa da hipercapnia","Cura do processo infeccioso","Hiperventilação protetora comprovada"],"answer":0,"explanation":"Oxigenoterapia excessiva em alguns pacientes pode agravar hipercapnia; avaliar gasometria.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Segurança","difficulty":"média"},{"id":"Q5-DPO-021","topic":"DPOC","mode":"decorar","style":"Tratamento","question":"Qual achado no RX favorece enfisema pulmonar?","options":["Cardiomegalia isolada obrigatória","Consolidação lobar sempre presente","Derrame pleural como definição","Hiperinsuflação com diafragmas achatados"],"answer":3,"explanation":"Hiperinsuflação e retificação diafragmática podem ocorrer no enfisema.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Imagem","difficulty":"média"},{"id":"Q5-DPO-022","topic":"DPOC","mode":"decorar","style":"Avaliação crítica","question":"Quando infecção viral desencadeia exacerbação sem critérios clínicos bacterianos, qual conduta evita uso inadequado de antimicrobianos?","options":["Prescrever dois antibióticos empiricamente por rotina","Usar antibiótico para toda dispneia","Tratar exacerbação e reservar antibiótico para indicações específicas","Aguardar piora sem broncodilatador"],"answer":2,"explanation":"Nem toda exacerbação da DPOC exige antibiótico.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Uso racional","difficulty":"difícil"},{"id":"Q5-DPO-023","topic":"DPOC","mode":"decorar","style":"Cálculo e valores","question":"Qual alteração gasométrica define acidose respiratória aguda em exacerbação hipercápnica?","options":["PaO₂ normal com pH elevado","PaCO₂ elevada com pH reduzido","Bicarbonato alto isolado com pH normal","Leucocitose com pH normal"],"answer":1,"explanation":"O pH permite distinguir compensação de acidose respiratória aguda.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Gasometria","difficulty":"média"},{"id":"Q5-DPO-024","topic":"DPOC","mode":"decorar","style":"Diferenciais","question":"Por que agitação seguida de sonolência em paciente DPOC pode mudar a prioridade?","options":["Sugere falência ventilatória ou hipoxemia e exige avaliação imediata","Confirma melhora ventilatória","Autoriza alta pela redução da ansiedade","É sinal inespecífico que nunca altera conduta"],"answer":0,"explanation":"Estado mental integra avaliação de gravidade e proteção da via aérea.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Gravidade","difficulty":"média"},{"id":"Q5-DPO-025","topic":"DPOC","mode":"decorar","style":"Raciocínio rápido","question":"Qual estratégia de tratamento inalatório pode ser usada durante exacerbação com coordenação ruim?","options":["Suspender todos os broncodilatadores","Apenas comprimido mucolítico","Uso exclusivo de corticosteroide nasal","Dispositivo de nebulização apropriado ou espaçador com assistência"],"answer":3,"explanation":"A entrega correta do broncodilatador deve ser adaptada às capacidades do paciente.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Dispositivo","difficulty":"difícil"},{"id":"Q5-DPO-026","topic":"DPOC","mode":"decorar","style":"Aplicação clínica","question":"O paciente está estabilizado após crise e relata usar LAMA diariamente de modo irregular. Qual medida deve constar da alta?","options":["Retirar todos os broncodilatadores sem reavaliação","Prescrever oxigênio permanente só pelo relato","Revisar adesão, técnica inalatória e terapia de manutenção","Dispensar retorno clínico"],"answer":2,"explanation":"Revisão da terapia de manutenção e técnica reduz erros e novas exacerbações.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Alta","difficulty":"média"},{"id":"Q5-DPO-027","topic":"DPOC","mode":"decorar","style":"Pegadinha","question":"Qual parâmetro pode sinalizar necessidade de intubação se o paciente não consegue usar VNI com segurança?","options":["PA normal após hidratação","Incapacidade de proteger via aérea e deterioração clínica","Melhora do pH","Fala em frases completas e boa cooperação"],"answer":1,"explanation":"Falha ou contraindicação de VNI obriga considerar ventilação invasiva conforme quadro.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"VNI","difficulty":"média"},{"id":"Q5-DPO-028","topic":"DPOC","mode":"decorar","style":"Comparação","question":"Como distinguir exacerbação de DPOC de edema agudo cardiogênico quando há dispneia e estertores?","options":["Investigar sinais de congestão, história cardíaca e exames dirigidos","Assumir que todo tabagista tem apenas DPOC","Dispensar avaliação cardiovascular por apresentar sibilo","Usar purulência como critério exclusivo de insuficiência cardíaca"],"answer":0,"explanation":"Outras causas de dispneia podem coexistir e demandam tratamento próprio.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Diferencial","difficulty":"difícil"},{"id":"Q5-DPO-029","topic":"DPOC","mode":"decorar","style":"Tratamento","question":"Qual alvo de saturação costuma ser usado na exacerbação mesmo quando o paciente está muito ansioso e hipoxêmico?","options":["100% sempre, sem monitorização","Menor que 80% para evitar hipercapnia","Não administrar oxigênio em nenhuma situação","88–92% com avaliação clínica e gasométrica"],"answer":3,"explanation":"A oxigenoterapia é controlada e reajustada pela situação clínica.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Oxigenação","difficulty":"média"},{"id":"Q5-DPO-030","topic":"DPOC","mode":"decorar","style":"Avaliação crítica","question":"Paciente com DPOC no ambulatório, grande carga tabágica e dispneia progressiva apresenta relação VEF₁/CVF de 0,75 após BD. Qual conclusão é correta?","options":["DPOC confirmada porque a relação excede 0,70","GOLD 4 confirmado pela história","O critério espirométrico fixo para DPOC não está preenchido","Dispensa investigação de outras causas de dispneia"],"answer":2,"explanation":"A confirmação exige limitação persistente pós-BD, tipicamente relação inferior a 0,70.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Diagnóstico","difficulty":"média"},{"id":"Q5-DPO-031","topic":"DPOC","mode":"decorar","style":"Cálculo e valores","question":"Qual achado fisiopatológico explica aumento do trabalho expiratório no enfisema?","options":["Maior elasticidade pulmonar impede aprisionamento","Perda de retração elástica favorece colapso expiratório","Obstrução exclusivamente laríngea","Excesso de surfactante obrigatório"],"answer":1,"explanation":"Destruição alveolar altera a mecânica e favorece aprisionamento aéreo.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Fisiopatologia","difficulty":"difícil"},{"id":"Q5-DPO-032","topic":"DPOC","mode":"decorar","style":"Diferenciais","question":"Quando há acidose respiratória na DPOC, a piora da hipercapnia deve levar a avaliar que função?","options":["Ventilação alveolar, fadiga e necessidade de suporte","Somente excreção renal de sódio","Apenas consumo de glicose","Integridade da pele"],"answer":0,"explanation":"PaCO₂ crescente reflete insuficiência de ventilação alveolar relativa à produção de CO₂.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Ventilação","difficulty":"média"},{"id":"Q5-DPO-033","topic":"DPOC","mode":"decorar","style":"Raciocínio rápido","question":"Qual alternativa descreve melhor o grupo B no ABE com sintomas importantes sem exacerbações qualificadoras no último ano?","options":["Obrigatoriamente VEF₁ <30%","Qualquer pessoa com duas internações recentes","Apenas quem não relata dispneia","Sintomático, mas sem evento que o coloque em E"],"answer":3,"explanation":"B reflete sintomas mais importantes sem a história de exacerbações definidora de E.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"ABE","difficulty":"média"},{"id":"Q5-DPO-034","topic":"DPOC","mode":"decorar","style":"Aplicação clínica","question":"Um paciente que nunca fumou mas trabalhou décadas em ambiente com fumaça de biomassa pode desenvolver DPOC?","options":["Não, tabagismo ativo é requisito diagnóstico absoluto","Só se houver pneumonia no último mês","Sim, exposição crônica a partículas nocivas também é fator de risco","Apenas se for menor de 30 anos"],"answer":2,"explanation":"Tabaco é importante, mas biomassa e outros agentes também podem contribuir.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Risco","difficulty":"difícil"},{"id":"Q5-DPO-035","topic":"DPOC","mode":"decorar","style":"Pegadinha","question":"Por que a gasometria deve ser repetida após início da VNI em acidose hipercápnica?","options":["Porque a saturação não pode ser aferida","Para monitorar tendência do pH/PaCO₂ e verificar resposta","Para confirmar o tabagismo","Somente para dosar hemoglobina"],"answer":1,"explanation":"Melhora do pH e ventilação ajuda a avaliar eficácia da VNI.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Monitorização","difficulty":"média"},{"id":"Q5-DPO-036","topic":"DPOC","mode":"decorar","style":"Comparação","question":"Qual achado sugere considerar deficiência de alfa-1 antitripsina como causa de DPOC?","options":["Enfisema precoce em não tabagista ou com história familiar relevante","DPOC exclusiva de idoso tabagista","Pneumonia lobar isolada","Asma típica com espirometria normal"],"answer":0,"explanation":"A deficiência de alfa-1 antitripsina é fator genético que deve ser lembrado em fenótipos característicos.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Etiologia","difficulty":"média"},{"id":"Q5-DPO-037","topic":"DPOC","mode":"decorar","style":"Tratamento","question":"Qual é a diferença entre purulência e volume de escarro na tríade de Anthonisen?","options":["São critérios idênticos","Ambos referem-se somente a febre","Volume reflete pH da gasometria","Purulência é mudança de aspecto/cor, volume é quantidade produzida"],"answer":3,"explanation":"Os critérios são distintos e ajudam na decisão de antibioticoterapia.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Anthonisen","difficulty":"difícil"},{"id":"Q5-DPO-038","topic":"DPOC","mode":"decorar","style":"Avaliação crítica","question":"Um paciente com DPOC e muita ansiedade insiste em saturar 100%. Qual explicação educativa é correta?","options":["A saturação alvo é 70%","A meta 100% acelera a excreção de CO₂","O alvo controlado reduz risco de agravar hipercapnia, mantendo oxigenação adequada","Oxigênio deve ser evitado sempre"],"answer":2,"explanation":"Metas controladas são mais seguras em pacientes com risco de retenção de CO₂.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Educação","difficulty":"média"},{"id":"C5-DPO-001","topic":"DPOC","mode":"casos","style":"Caso clínico avançado","question":"Homem de 72 anos com DPOC, hipertensão pulmonar e uso domiciliar de O₂ chega sonolento após receber máscara não titulada no transporte. SpO₂ 100%, pH 7,19, PaCO₂ 85 e HCO₃⁻ 31; FR 10, tosse ineficaz. Qual avaliação guia melhor a próxima intervenção?","options":["Considerar falência ventilatória e proteção de via aérea; titulação de O₂ e suporte ventilatório conforme capacidade de VNI","Manter O₂ máximo porque a saturação está boa","Dar alta porque a hipoxemia foi corrigida","Prescrever apenas antibiótico oral"],"answer":0,"explanation":"Hipercapnia acidótica com rebaixamento e tosse ineficaz pode impedir VNI segura e requer abordagem ventilatória urgente.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Falência ventilatória","difficulty":"avançada","classic_intro":"Caso clássico de DPOC: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-DPO-002","topic":"DPOC","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 67 anos, ex-tabagista, chega com piora de dispneia, volume do escarro e cor amarelo-esverdeada há 48 h. FR 31, SpO₂ 86%, pH 7,30, PaCO₂ 61 e RX sem infiltrado. Está desperta e coopera. Qual conjunto terapêutico é mais apropriado?","options":["Oxigênio a 100% e alta após saturação normalizar","Apenas corticosteroide inalatório isolado","Ventilação invasiva obrigatória antes de testar VNI em qualquer caso","Oxigênio controlado, broncodilatadores de curta ação, corticoide, antibiótico indicado e VNI"],"answer":3,"explanation":"Há exacerbção com critérios de antibiótico e acidose hipercápnica favorável a VNI se viável.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Tratamento combinado","difficulty":"avançada","classic_intro":"Caso clássico de DPOC: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-DPO-003","topic":"DPOC","mode":"casos","style":"Caso clínico avançado","question":"Homem de 60 anos com DPOC moderada e dispneia súbita intensa após viagem longa apresenta dor pleurítica, FC 128 e saturação 89%. Não houve mudança do escarro e o RX não mostra consolidação. Uma perna está edemaciada. Que hipótese alternativa merece prioridade diagnóstica?","options":["Exacerbação bacteriana comprovada","Crise asmática infantil","Tromboembolismo pulmonar","Pneumonia lobar bacteriana obrigatória"],"answer":2,"explanation":"A combinação de dor pleurítica súbita e sinais de trombose sugere TEP associado ou simulando exacerbação.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"TEP","difficulty":"avançada","classic_intro":"Caso clássico de DPOC: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-DPO-004","topic":"DPOC","mode":"casos","style":"Caso clínico avançado","question":"Idosa com DPOC e insuficiência cardíaca chega com edema, ortopneia, crepitações e gasometria pH 7,38/PaCO₂ 49; SpO₂ 91%, sem mudança do escarro. Qual erro de tratamento deve ser evitado?","options":["Investigar insuficiência cardíaca","Atribuir toda dispneia à DPOC e prescrever antibiótico de rotina sem avaliar congestão","Avaliar perfil de troca gasosa","Revisar terapias de manutenção"],"answer":1,"explanation":"A origem da dispneia pode ser cardiovascular, exigindo diferenciação antes de intensificar antibiótico.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Diferencial","difficulty":"avançada"},{"id":"C5-DPO-005","topic":"DPOC","mode":"casos","style":"Caso clínico avançado","question":"Paciente de 64 anos com DPOC em uso irregular de LAMA chega com piora de tosse e dispneia; SpO₂ 88%, pH 7,39, PaCO₂ 53, HCO₃⁻ 31. Está orientado, confortável após SABA, FR 20. Um interno sugere VNI obrigatória porque PaCO₂ >45. Qual interpretação é mais adequada?","options":["Hipercapnia pode ser cronicamente compensada; indicação de VNI depende de acidose e contexto clínico","Toda hipercapnia isolada obriga VNI","A gasometria mostra acidose metabólica grave","O paciente deve ser intubado por PaCO₂ 53"],"answer":0,"explanation":"Na ausência de acidose aguda e desconforto significativo, não se indica VNI apenas pelo número de CO₂.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Interpretação gasométrica","difficulty":"avançada"},{"id":"C5-DPO-006","topic":"DPOC","mode":"casos","style":"Caso clínico avançado","question":"Paciente de 58 anos com DPOC e bronquiectasias é internado pela terceira vez em seis meses; apresenta escarro purulento, colonização prévia por Pseudomonas e antibióticos recentes. Qual fator deve influenciar a escolha inicial do antimicrobiano?","options":["Apenas preferência pessoal pelo antibiótico mais barato","Ausência de febre exclui bactérias resistentes","Colocar sempre antifúngico profilático","Histórico microbiológico e risco de bactéria resistente, com ajuste a culturas e protocolos"],"answer":3,"explanation":"Fatores de risco de resistência e culturas prévias orientam escolha empírica individualizada.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Resistência","difficulty":"avançada"},{"id":"C5-DPO-007","topic":"DPOC","mode":"casos","style":"Caso clínico avançado","question":"Homem de 74 anos com DPOC e ex-tabagismo tem mMRC 3, nenhuma exacerbação no último ano e relação VEF₁/CVF 0,58 após BD. O VEF₁ é 64% do previsto. Qual dupla de classificações está correta pelo esquema ABE/1–4?","options":["Grupo E e GOLD 4","Grupo A e GOLD 3","Grupo B e GOLD 2","Grupo E e GOLD 1"],"answer":2,"explanation":"Muitos sintomas sem exacerbação elegível indicam grupo B; VEF₁ 50–79% indica GOLD 2.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Classificação GOLD","difficulty":"avançada"},{"id":"C5-DPO-008","topic":"DPOC","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 68 anos com DPOC tem VEF₁ 85% do previsto, mMRC 1 e uma exacerbação moderada tratada com corticoide há oito meses. Qual é a principal pegadinha da classificação atual?","options":["Grupo A é obrigatório porque VEF₁ >80%","Apesar de função quase preservada, a exacerbação pode colocá-la no grupo E","GOLD 4 é obrigatório por uma exacerbação","Não se pode classificar sem TC de tórax"],"answer":1,"explanation":"GOLD 1–4 descreve obstrução; ABE atual incorpora histórico de exacerbação independentemente do VEF₁.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"ABE","difficulty":"avançada"},{"id":"C5-DPO-009","topic":"DPOC","mode":"casos","style":"Caso clínico avançado","question":"Paciente de 70 anos com DPOC exacerba e apresenta pH 7,27, PaCO₂ 70, FR 35, uso de musculatura acessória e nível de consciência preservado. VNI é iniciada. Em 90 minutos, pH cai para 7,19, FR sobe e paciente torna-se confuso. Qual conduta melhor representa reavaliação dinâmica?","options":["Reconhecer falha de VNI e considerar intubação por equipe experiente imediatamente","Insistir na mesma máscara por 12 horas sem reavaliar","Dar alta porque PaCO₂ é cronicamente alta","Suspender oxigênio apesar de hipoxemia"],"answer":0,"explanation":"Piora de acidose, ventilação e consciência sob VNI caracteriza falha clínica e exige escalonamento.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Falha de VNI","difficulty":"avançada","classic_intro":"Caso clássico de DPOC: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-DPO-010","topic":"DPOC","mode":"casos","style":"Caso clínico avançado","question":"Homem de 66 anos com DPOC chega com febre, dor focal e tosse purulenta. RX mostra consolidação lobar, SpO₂ 85%, PA 100/60 e leucocitose. Qual consequência prática decorre do achado de imagem?","options":["Excluir pneumonia por ter DPOC","Tratar apenas com aumento de LAMA","Aguardar espirometria de esforço para antibiótico","Tratar possível pneumonia associada, além da exacerbação obstrutiva e suporte respiratório"],"answer":3,"explanation":"Consolidação focal muda o diagnóstico diferencial e reforça necessidade de abordagem infecciosa específica.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Pneumonia concomitante","difficulty":"avançada"},{"id":"C5-DPO-011","topic":"DPOC","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 61 anos com DPOC diz sentir-se 'curada' após cinco dias de prednisona e SABA. Porém continua tabagista, usa LABA/LAMA de forma errada e faltou a reabilitação. Qual plano de alta reduz risco futuro?","options":["Manter apenas SABA e descartar LAMA","Não orientar cessação porque não altera exacerbações","Reconciliar inaladores, revisar técnica, cessação do tabagismo, vacinação e reabilitação","Suspender seguimento por seis meses"],"answer":2,"explanation":"Alta é oportunidade para prevenir recaídas e otimizar manutenção e medidas não farmacológicas.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Prevenção","difficulty":"avançada"},{"id":"C5-DPO-012","topic":"DPOC","mode":"casos","style":"Caso clínico avançado","question":"Homem de 63 anos chega com tosse habitual e cansaço leves; sem mudança do volume ou purulência do escarro, sem hipoxemia ou acidose. Pede antibiótico porque 'sempre melhora'. Qual decisão apoia boa prática?","options":["Prescrever antibiótico amplo por prevenção","Evitar antibiótico automático, investigar outros fatores e tratar sintomas conforme avaliação","Iniciar corticosteroide por 30 dias sem diagnóstico","Internar em UTI pela idade"],"answer":1,"explanation":"Antibioticoterapia deve ser orientada por critérios clínicos e suspeita infecciosa, não pela preferência isolada.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Stewardship","difficulty":"avançada"},{"id":"Q5-SEP-001","topic":"Sepse","mode":"decorar","style":"Raciocínio rápido","question":"Na triagem de uma pessoa com infecção presumida, qual achado sugere disfunção orgânica mais que mera SIRS?","options":["Febre isolada com função renal normal","Taquicardia isolada após exercício","Oligúria nova e creatinina em ascensão","Leucocitose sem mudança clínica"],"answer":2,"explanation":"Sepse envolve disfunção orgânica ameaçadora à vida decorrente da infecção.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Disfunção orgânica","difficulty":"difícil"},{"id":"Q5-SEP-002","topic":"Sepse","mode":"decorar","style":"Aplicação clínica","question":"Como interpretar qSOFA de apenas 1 em paciente com pneumonia, hipoxemia e alteração renal aguda?","options":["Exclui sepse de maneira definitiva","Não exclui sepse; avaliação estruturada e SOFA clínico continuam necessários","Define choque séptico","Dispensa gasometria e monitorização"],"answer":1,"explanation":"qSOFA não deve funcionar como ferramenta única de triagem.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Escore","difficulty":"média"},{"id":"Q5-SEP-003","topic":"Sepse","mode":"decorar","style":"Pegadinha","question":"Paciente com infecção provável, sem choque, passa por rápida investigação e a hipótese permanece. Qual janela é sugerida pela SSC 2026 para iniciar antibiótico?","options":["Até 3 horas desde a primeira suspeita de sepse possível","Sempre após 12 horas","Somente depois de culturas positivas","Exatamente 24 horas depois"],"answer":0,"explanation":"A SSC 2026 diferencia suspeita sem choque de sepse provável/definida e choque.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Antibiótico","difficulty":"média"},{"id":"Q5-SEP-004","topic":"Sepse","mode":"decorar","style":"Comparação","question":"Em choque séptico reconhecido às 14h, quando deve ser iniciado antimicrobiano empírico?","options":["Até a manhã seguinte","Após 6 horas de observação","Somente quando o lactato normalizar","Imediatamente, idealmente dentro da primeira hora"],"answer":3,"explanation":"O atraso antibiótico em choque séptico está associado a pior prognóstico.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Antibiótico","difficulty":"difícil"},{"id":"Q5-SEP-005","topic":"Sepse","mode":"decorar","style":"Tratamento","question":"Se a primeira tentativa de punção para hemoculturas está muito difícil e o paciente apresenta choque, a prioridade é:","options":["Adiar tratamento até obter duas amostras em qualquer situação","Substituir antibiótico por anti-inflamatório","Não deixar a coleta atrasar antimicrobiano essencial","Liberar alta após uma cultura negativa"],"answer":2,"explanation":"Culturas são desejáveis antes do antibiótico quando não há atraso significativo.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Prioridade","difficulty":"média"},{"id":"Q5-SEP-006","topic":"Sepse","mode":"decorar","style":"Avaliação crítica","question":"Em um adulto com sepse, qual componente hemodinâmico deve ser reavaliado após bolus de cristaloide?","options":["Apenas temperatura axilar","Perfusão, pressão arterial e responsividade a fluidos","Somente leucócitos","Apenas glicemia capilar"],"answer":1,"explanation":"Ressuscitação deve ser individualizada e orientada por resposta.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Fluidos","difficulty":"média"},{"id":"Q5-SEP-007","topic":"Sepse","mode":"decorar","style":"Cálculo e valores","question":"O valor de lactato cai de 5,2 para 3,1 mmol/L após a reanimação. Qual inferência é a mais segura?","options":["A tendência é favorável, mas exige reavaliação clínica e nova interpretação","A sepse está curada","Há necessariamente acidose láctica grave persistente","O lactato nunca é útil para monitorização"],"answer":0,"explanation":"Redução do lactato pode sugerir melhora da perfusão, sem substituir avaliação global.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Lactato","difficulty":"difícil"},{"id":"Q5-SEP-008","topic":"Sepse","mode":"decorar","style":"Diferenciais","question":"Se o paciente em choque permanece hipotenso após fluidos adequados, qual vasopressor é geralmente preferido como primeira escolha?","options":["Dopamina por rotina","Dobutamina isolada em todo paciente","Fenilefrina para todos","Noradrenalina"],"answer":3,"explanation":"Noradrenalina costuma ser o vasopressor inicial do choque séptico.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Vasopressor","difficulty":"média"},{"id":"Q5-SEP-009","topic":"Sepse","mode":"decorar","style":"Raciocínio rápido","question":"Qual finalidade explica titular vasopressor para PAM em torno de 65 mmHg inicialmente?","options":["Normalizar a frequência cardíaca necessariamente","Corrigir a infecção sem antimicrobiano","Manter pressão de perfusão orgânica adequada sem hiperpressurizar indiscriminadamente","Elevar pressão até 120 mmHg em todos"],"answer":2,"explanation":"PAM-alvo inicial de 65 mmHg é uma referência ajustável ao paciente.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"PAM","difficulty":"média"},{"id":"Q5-SEP-010","topic":"Sepse","mode":"decorar","style":"Aplicação clínica","question":"Qual decisão é prioritária diante de abscesso abdominal drenável em paciente séptico sob antibiótico?","options":["Manter apenas vasopressor por uma semana","Planejar controle de foco precoce além do antimicrobiano","Aguardar todo antibiótico terminar para drenar","Dispensar avaliação cirúrgica devido ao lactato"],"answer":1,"explanation":"Controle do foco é componente central do tratamento de sepse.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Foco","difficulty":"difícil"},{"id":"Q5-SEP-011","topic":"Sepse","mode":"decorar","style":"Pegadinha","question":"Por que a administração de volumes fixos de fluidos sem reavaliação pode prejudicar paciente séptico com edema pulmonar?","options":["Pode causar sobrecarga e piora da troca gasosa","Todo líquido é rapidamente eliminado sem efeito adverso","Aumenta sempre a pressão oncótica","Impede uso de vasopressor"],"answer":0,"explanation":"Risco de congestão requer reavaliação frequente, especialmente em cardiopatas.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Segurança","difficulty":"média"},{"id":"Q5-SEP-012","topic":"Sepse","mode":"decorar","style":"Comparação","question":"Qual método ajuda mais do que pressão venosa central isolada a decidir novo bolus?","options":["Uma medida isolada de temperatura","Somente hematócrito","Dosagem de colesterol","Avaliação dinâmica de responsividade a fluidos quando viável"],"answer":3,"explanation":"Parâmetros dinâmicos ajudam a evitar fluidos desnecessários.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Fluidos","difficulty":"média"},{"id":"Q5-SEP-013","topic":"Sepse","mode":"decorar","style":"Tratamento","question":"Qual comportamento é apropriado se culturas revelam patógeno sensível a antibiótico mais restrito e paciente estabiliza?","options":["Manter sempre cobertura máxima até o fim","Suspender toda terapia imediatamente","Reavaliar e descalonar antimicrobiano conforme foco e evolução","Trocar para antifúngico por rotina"],"answer":2,"explanation":"Descalonamento integra boa prática de uso de antimicrobianos.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Stewardship","difficulty":"difícil"},{"id":"Q5-SEP-014","topic":"Sepse","mode":"decorar","style":"Avaliação crítica","question":"Uma pneumonia grave com SpO₂ baixa e creatinina alterada exige qual interpretação inicial?","options":["Apenas SIRS, sem necessidade de avaliar SOFA","Disfunções orgânicas respiratória e renal podem estar presentes","Sepse só existe com hipotensão","Lactato deve estar maior que 10 para diagnóstico"],"answer":1,"explanation":"A disfunção orgânica pode ocorrer mesmo sem choque.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"SOFA","difficulty":"média"},{"id":"Q5-SEP-015","topic":"Sepse","mode":"decorar","style":"Cálculo e valores","question":"Como diferenciar hipotensão isolada do diagnóstico clínico-operacional de choque séptico?","options":["Avaliar necessidade de vasopressor após reposição apropriada e lactato >2 mmol/L","PA menor que 140 é suficiente","Febre acima de 38 define choque","Toda infecção com taquicardia é choque"],"answer":0,"explanation":"Critérios do Sepsis-3 envolvem vasopressor para PAM ≥65 e lactato >2 após volume apropriado.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Definição","difficulty":"média"},{"id":"Q5-SEP-016","topic":"Sepse","mode":"decorar","style":"Diferenciais","question":"Qual informação sobre SIRS continua verdadeira?","options":["Foi concebido como sinônimo exato de sepse","Se presente define choque","É diagnóstico exclusivo de cultura positiva","É sensível e inespecífico, podendo ocorrer sem infecção"],"answer":3,"explanation":"SIRS não equivale a sepse, mas pode contribuir para reconhecimento de inflamação.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Escore","difficulty":"difícil"},{"id":"Q5-SEP-017","topic":"Sepse","mode":"decorar","style":"Raciocínio rápido","question":"Se a causa mais provável de choque é septicemia abdominal, qual local deve ser procurado além de pulmão?","options":["Somente ouvido externo","Sempre pele intacta como único foco","Coleções, perfuração ou foco intra-abdominal drenável","Nenhuma investigação abdominal é necessária"],"answer":2,"explanation":"Exame abdominal e imagem direcionada ajudam a encontrar foco tratável.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Foco","difficulty":"média"},{"id":"Q5-SEP-018","topic":"Sepse","mode":"decorar","style":"Aplicação clínica","question":"Qual alteração à beira-leito pode acompanhar hipoperfusão persistente mesmo se PAM-alvo foi atingida?","options":["Temperatura normal como única informação","Tempo de enchimento capilar prolongado e extremidades mal perfundidas","Leucócitos normais após antibiótico","Frequência respiratória de repouso isolada"],"answer":1,"explanation":"Microcirculação e perfusão periférica merecem reavaliação além da PAM.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Perfusão","difficulty":"média"},{"id":"Q5-SEP-019","topic":"Sepse","mode":"decorar","style":"Pegadinha","question":"O paciente com choque recebe noradrenalina em dose crescente e permanece hipotenso. Qual abordagem global é mais segura?","options":["Rever causa, responsividade a fluidos, perfusão e considerar associação de vasopressor conforme protocolo","Adicionar litros de fluido indefinidamente sem avaliação","Reduzir o monitoramento","Esperar lactato reduzir espontaneamente"],"answer":0,"explanation":"Choque refratário exige reavaliação integrada e escalonamento dirigido.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Choque refratário","difficulty":"difícil"},{"id":"Q5-SEP-020","topic":"Sepse","mode":"decorar","style":"Comparação","question":"Se uma pessoa idosa com infecção tem temperatura de 35,5 °C e confusão, como interpretar ausência de febre?","options":["Exclui sepse em idosos","É obrigatoriamente causada por intoxicação","Prova ausência de inflamação","Não exclui infecção grave nem sepse"],"answer":3,"explanation":"Hipotermia pode acompanhar infecção grave, especialmente em grupos vulneráveis.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Apresentação atípica","difficulty":"média"},{"id":"Q5-SEP-021","topic":"Sepse","mode":"decorar","style":"Tratamento","question":"Qual alteração laboratorial é sinal de disfunção orgânica hematológica no SOFA?","options":["Aumento isolado de colesterol","Hemoglobina normal","Queda de plaquetas","PCR discretamente elevada"],"answer":2,"explanation":"Trombocitopenia integra avaliação de disfunção hematológica.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"SOFA","difficulty":"média"},{"id":"Q5-SEP-022","topic":"Sepse","mode":"decorar","style":"Avaliação crítica","question":"Um paciente usa antimicrobiano amplo há 48 horas e permanece febril sem estabilidade. Qual conduta evita ancoragem?","options":["Repetir só antitérmico","Reexaminar foco, resistência, diagnóstico alternativo e necessidade de drenagem","Concluir que todo caso necessita antifúngico empírico","Dar alta se temperatura cair momentaneamente"],"answer":1,"explanation":"Falha clínica requer reavaliação de foco, adequação e complicações.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Reavaliação","difficulty":"difícil"},{"id":"Q5-SEP-023","topic":"Sepse","mode":"decorar","style":"Cálculo e valores","question":"Qual suporte deve ser considerado em choque séptico com persistência de hipoperfusão e disfunção cardíaca apesar de PA e fluidos adequados?","options":["Avaliação de suporte inotrópico conforme perfil hemodinâmico","Dobutamina para todas as infecções simples","Suspender vasopressor obrigatório","Infusão de corticoide inalatório como único suporte"],"answer":0,"explanation":"Disfunção miocárdica em choque persistente pode justificar inotrópico selecionado.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Hemodinâmica","difficulty":"média"},{"id":"Q5-SEP-024","topic":"Sepse","mode":"decorar","style":"Diferenciais","question":"No pronto-socorro, por que usar PCR e procalcitonina isoladamente para liberar ou negar antibiótico em choque é um erro?","options":["Os marcadores identificam sempre o agente","Excluem choque com resultado baixo","Determinam sozinhos o foco","Marcadores não substituem avaliação clínica nem devem atrasar terapia urgente"],"answer":3,"explanation":"A decisão integra probabilidade de infecção, disfunção e gravidade.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Biomarcadores","difficulty":"média"},{"id":"Q5-SEP-025","topic":"Sepse","mode":"decorar","style":"Raciocínio rápido","question":"Ao verificar deterioração após horas de tratamento de sepse, qual medida deve ser repetida?","options":["Somente repetir temperatura no fim do turno","Somente colher hemocultura semanal","Avaliar sinais vitais, perfusão e disfunções orgânicas","Evitar reavaliação hemodinâmica"],"answer":2,"explanation":"Sepse evolui dinamicamente, exigindo reavaliação clínica e laboratorial.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Monitorização","difficulty":"difícil"},{"id":"Q5-SEP-026","topic":"Sepse","mode":"decorar","style":"Aplicação clínica","question":"Um paciente internado por sepse melhora e não precisa mais de vasopressor. Qual decisão sobre antibiótico deve ser individualizada?","options":["Interromper obrigatoriamente em 24 horas","Duração conforme foco, microbiologia, controle de fonte e resposta","Manter a mesma dose por 30 dias para todos","Aumentar cobertura sem motivo"],"answer":1,"explanation":"A duração é guiada por contexto clínico e controle do foco, não por número universal.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Antibiótico","difficulty":"média"},{"id":"Q5-SEP-027","topic":"Sepse","mode":"decorar","style":"Pegadinha","question":"Qual achado torna inadequada a afirmação de que choque distributivo sempre cursa com pele quente?","options":["Em fases tardias pode haver extremidades frias, moteamento e perfusão ruim","A pele é obrigatoriamente seca e quente até o óbito","Choque nunca altera perfusão cutânea","Livedo exclui sepse"],"answer":0,"explanation":"A apresentação de choque pode variar, incluindo perfusão periférica ruim.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Choque","difficulty":"média"},{"id":"Q5-SEP-028","topic":"Sepse","mode":"decorar","style":"Comparação","question":"Paciente com provável sepse urinária tem obstrução por cálculo e hidronefrose. Qual medida muda prognóstico junto ao antimicrobiano?","options":["Suspender todo volume até cultura","Observar até terminar sete dias de antibiótico","Apenas trocar sonda externa sem avaliar obstrução","Descompressão da via urinária obstruída sem demora indevida"],"answer":3,"explanation":"Infecção associada à obstrução exige controle de foco por desobstrução.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Foco","difficulty":"difícil"},{"id":"Q5-SEP-029","topic":"Sepse","mode":"decorar","style":"Tratamento","question":"Por que infecção com SOFA aumentado em dois pontos é diferente de simples bacteremia assintomática?","options":["A segunda sempre exige vasopressor","Só a bacteremia pode ter febre","A primeira envolve disfunção orgânica ameaçadora à vida","Sepse significa sempre hemocultura positiva"],"answer":2,"explanation":"Sepse é definida por disfunção orgânica associada à resposta à infecção, não por bacteremia obrigatória.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Definição","difficulty":"média"},{"id":"Q5-SEP-030","topic":"Sepse","mode":"decorar","style":"Avaliação crítica","question":"Como evitar atrasar ressuscitação num paciente com choque evidente mas sem acesso central imediato?","options":["Esperar acesso central por várias horas","Iniciar medidas urgentes e vasopressor periférico de forma segura conforme protocolo enquanto obtém acesso adequado","Administrar apenas antitérmico","Usar somente acesso subcutâneo para todo vasopressor"],"answer":1,"explanation":"Acesso central não deve atrasar vasopressor urgente quando acesso periférico apropriado permite início seguro.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Acesso","difficulty":"média"},{"id":"Q5-SEP-031","topic":"Sepse","mode":"decorar","style":"Cálculo e valores","question":"Qual alvo de tempo para controle de foco é sugerido pela SSC 2026 quando existe fonte anatômica tratável?","options":["Idealmente dentro de 6 horas do diagnóstico, quando viável","Somente após 7 dias","Sempre 30 dias após antimicrobiano","Apenas se houver cultura positiva"],"answer":0,"explanation":"A SSC 2026 favorece controle precoce do foco, idealmente dentro de 6 h quando indicado.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Fonte","difficulty":"difícil"},{"id":"Q5-SEP-032","topic":"Sepse","mode":"decorar","style":"Diferenciais","question":"Qual afirmação é mais correta sobre vasopressina em choque séptico persistente sob noradrenalina?","options":["É antibiótico de primeira linha","Substitui controle do foco","Deve ser usada na infecção sem hipotensão","Pode ser acrescentada conforme necessidade de vasopressores e protocolo"],"answer":3,"explanation":"Vasopressina é um possível segundo vasopressor em choque selecionado.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Vasoativos","difficulty":"média"},{"id":"Q5-SEP-033","topic":"Sepse","mode":"decorar","style":"Raciocínio rápido","question":"Uma pessoa com choque séptico apresenta cortisol baixo relativo e permanece instável com vasopressores. Qual adjuvante pode ser considerado em choque dependente de vasopressor?","options":["Corticoide inalatório para todos","Somente antialérgico","Corticosteroide sistêmico, como hidrocortisona, segundo indicação","Suspender antibiótico para tratar cortisol"],"answer":2,"explanation":"Corticoide IV pode ser considerado em choque séptico vasopressor-dependente conforme diretrizes.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Adjuvantes","difficulty":"média"},{"id":"Q5-SEP-034","topic":"Sepse","mode":"decorar","style":"Aplicação clínica","question":"Qual risco deve ser considerado ao prescrever antibiótico amplo a todo febril de baixo risco sem avaliação?","options":["Cura imediata de todas as viroses","Resistência, eventos adversos e tratamento desnecessário","Eliminação de necessidade de exame","Imunização automática"],"answer":1,"explanation":"Antibioticoterapia exige estimativa de probabilidade infecciosa e gravidade.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Antimicrobianos","difficulty":"difícil"},{"id":"Q5-SEP-035","topic":"Sepse","mode":"decorar","style":"Pegadinha","question":"Por que a melhora de extremidades mornas após reanimação não é prova de normalização de perfusão visceral?","options":["Perfusão macrocirculatória e microcirculatória podem não se normalizar ao mesmo tempo","A pele mede diretamente fluxo renal","Lactato deixa de importar","A temperatura determina SOFA"],"answer":0,"explanation":"Reavaliação multimodal continua necessária mesmo quando um sinal melhora.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Microcirculação","difficulty":"média"},{"id":"Q5-SEP-036","topic":"Sepse","mode":"decorar","style":"Comparação","question":"Se há necessidade crescente de noradrenalina e leituras oscilantes de PA com manguito, qual medida pode aperfeiçoar monitorização?","options":["Interromper aferição pressórica","Usar apenas palpação de pulso","Ignorar alterações após um valor normal","Considerar pressão arterial invasiva quando indicado"],"answer":3,"explanation":"Monitorização invasiva pode ajudar em choque com vasopressor alto/escalonando e medidas inconsistentes.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Monitorização","difficulty":"média"},{"id":"Q5-SEP-037","topic":"Sepse","mode":"decorar","style":"Tratamento","question":"O que difere choque séptico de hipotensão passageira que cede a hidratação simples?","options":["Leucocitose isolada","Febre acima de 38 °C","Persistência de disfunção circulatória e necessidade de vasopressor após reposição adequada","Frequência cardíaca 90"],"answer":2,"explanation":"Choque envolve falha circulatória grave persistente.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Definição","difficulty":"difícil"},{"id":"Q5-SEP-038","topic":"Sepse","mode":"decorar","style":"Avaliação crítica","question":"Quando a pessoa melhora clinicamente, qual mudança na prescrição de antimicrobianos costuma ser apropriada se houver cultura específica?","options":["Ampliar para todos os patógenos possíveis sem motivo","Ajustar espectro à sensibilidade e duração ao foco","Adicionar antifúngico em todos","Trocar diariamente sem justificativa"],"answer":1,"explanation":"Ajuste orientado por microbiologia e foco reduz exposição desnecessária.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Stewardship","difficulty":"média"},{"id":"C5-SEP-001","topic":"Sepse","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 76 anos com pielonefrite obstrutiva apresenta PA 84/45, FR 29, confusão, diurese 15 mL/h e lactato 4,2. Foi medicada com antibiótico e recebeu cristaloide inicial; a ultrassonografia mostra hidronefrose por cálculo proximal. Qual ação deve ser articulada urgentemente além da ressuscitação?","options":["Aguardar 72 h para saber se antibioticoterapia resolverá a obstrução","Dar alta quando lactato ficar abaixo de 4","Manter apenas antitérmico e monitorizar","Descompressão da via urinária obstruída com urologia para controle do foco"],"answer":3,"explanation":"Obstrução infectada exige controle mecânico do foco e não responde adequadamente só a antibiótico.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Sepse urinária obstrutiva","difficulty":"avançada","classic_intro":"Caso clássico de Sepse: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-SEP-002","topic":"Sepse","mode":"casos","style":"Caso clínico avançado","question":"Homem de 58 anos com pneumonia grave recebe antimicrobiano logo após coleta de culturas. Após 1,5 L de cristaloide, mantém PA 78/40, lactato 5,1 e perfusão periférica ruim. Foi iniciado noradrenalina. Um residente propõe atrasar titulação até obter acesso central. Qual orientação é correta?","options":["Suspender vasopressor até o cateter central ser instalado","Aguardar hemocultura positiva antes de subir noradrenalina","Manter ressuscitação e usar vasopressor periférico seguro conforme protocolo, sem atrasar PAM-alvo","Administrar apenas solução hipotônica para pressão"],"answer":2,"explanation":"Em choque, vasopressor não deve ser indevidamente retardado pelo acesso central, com cuidados de segurança.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Choque e acesso","difficulty":"avançada","classic_intro":"Caso clássico de Sepse: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-SEP-003","topic":"Sepse","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 65 anos com pneumonia, febre e hipoxemia requer O₂ suplementar; PA 120/72 e lactato 1,6, mas creatinina sobe de 0,9 para 2,3 mg/dL em 48 h. qSOFA = 1. Um colega considera 'apenas infecção' por não ter hipotensão. Qual avaliação é mais correta?","options":["Choque séptico definido sem vasopressor","Há possível sepse por disfunção orgânica renal/respiratória; qSOFA baixo não exclui","qSOFA 1 elimina disfunção orgânica","Não existe sepse sem lactato >4"],"answer":1,"explanation":"A disfunção orgânica pode preceder choque; é preciso avaliar SOFA e contexto.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Disfunção orgânica","difficulty":"avançada"},{"id":"C5-SEP-004","topic":"Sepse","mode":"casos","style":"Caso clínico avançado","question":"Paciente de 69 anos com infecção abdominal tem PAM 58 após reposição inicial, lactato 3,1 e pele marmórea. Noradrenalina eleva PAM a 68, mas a diurese permanece 8 mL/h e o tempo de enchimento capilar é 6 s. Qual conclusão sobre reanimação?","options":["A meta pressórica não basta; perfusão e causa ainda precisam ser reavaliadas","Choque está resolvido definitivamente por PAM >65","É obrigatória infusão ilimitada de fluidos","A diurese baixa prova infecção urinária"],"answer":0,"explanation":"PAM atingida não garante perfusão tecidual; reavaliação dinâmica é essencial.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Perfusão","difficulty":"avançada","classic_intro":"Caso clássico de Sepse: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-SEP-005","topic":"Sepse","mode":"casos","style":"Caso clínico avançado","question":"Idoso de 79 anos com DPOC, insuficiência cardíaca e suspeita de sepse urinária apresenta hipotensão e lactato elevado. Após fluidos iniciais torna-se mais dispneico, com B-lines no POCUS e estertores novos; a PAM segue 56. Qual estratégia é mais segura?","options":["Repetir bolus de 2 L indefinidamente até PAM 65","Excluir choque porque há congestão","Apenas prescrever diurético e aguardar cultura","Reavaliar responsividade, evitar sobrecarga e considerar suporte vasopressor precoce"],"answer":3,"explanation":"Fluidos devem ser individualizados; congestão pode indicar baixo benefício e alto risco de bolus adicionais.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Reanimação individualizada","difficulty":"avançada"},{"id":"C5-SEP-006","topic":"Sepse","mode":"casos","style":"Caso clínico avançado","question":"Paciente pós-operatório de colectomia no 8º dia apresenta febre, taquicardia, PA 88/50, lactato 3,7 e drenagem fecaloide na ferida. TC identifica coleção intra-abdominal com extravasamento. Após iniciar antibióticos e suporte hemodinâmico, qual prioridade determina o prognóstico?","options":["Aguardar hemocultura positiva por 4 dias","Suspender antimicrobianos para melhorar cultura","Controle do foco por cirurgia/drenagem tão cedo quanto viável","Dar alta após normalizar temperatura"],"answer":2,"explanation":"Foco abdominal com fístula/coleção exige controle de fonte precoce.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Fonte abdominal","difficulty":"avançada","classic_intro":"Caso clássico de Sepse: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-SEP-007","topic":"Sepse","mode":"casos","style":"Caso clínico avançado","question":"Homem de 50 anos com febre, disúria e sinais vitais estáveis chega à urgência sem disfunção orgânica documentada. Um aluno declara sepse e prescreve 30 mL/kg de cristaloide independentemente de perfusão. Qual raciocínio é mais apropriado?","options":["Toda infecção urinária é choque séptico","Diferenciar infecção não complicada de sepse e reservar ressuscitação agressiva a hipoperfusão/choque","Febre isolada comprova SOFA ≥2","A hidratação em todos deve ser de 4 L fixos"],"answer":1,"explanation":"Sepse exige disfunção orgânica; 30 mL/kg não é bolus automático para toda infecção.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Definição e fluidos","difficulty":"avançada"},{"id":"C5-SEP-008","topic":"Sepse","mode":"casos","style":"Caso clínico avançado","question":"Paciente com infecção cutânea extensa, PA 82/48, confusão e creatinina elevada recebe noradrenalina e antibiótico. Em duas horas o lactato cai de 6 para 3,8, mas piora a perfusão distal. Qual interpretação é correta?","options":["A queda do lactato é favorável, mas não exclui hipoperfusão persistente","A normalização clínica está garantida pelo lactato","Lactato só tem valor se for superior a 10","Não é necessário examinar extremidades"],"answer":0,"explanation":"Lactato e perfusão periférica devem ser avaliados em conjunto.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Lactato seriado","difficulty":"avançada"},{"id":"C5-SEP-009","topic":"Sepse","mode":"casos","style":"Caso clínico avançado","question":"Uma jovem de 28 anos com pneumonia e possível sepse apresenta PA 112/68, lactato 1,8 e está orientada. Não há choque nem disfunção clara; investigação rápida revela provável etiologia viral, com redução da suspeita bacteriana. Qual conduta sobre antibiótico respeita a diretriz?","options":["Todo paciente febril recebe carbapenêmico em até 1 hora","Aguardar culturas por 7 dias antes de qualquer decisão","Antifúngico empírico para toda pneumonia","Individualizar após investigação breve; não é obrigatório amplo espectro para infecção improvável"],"answer":3,"explanation":"A diretriz diferencia choque, sepse provável e suspeita sem choque e prevê investigação rápida no último grupo.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Janela antibiótica","difficulty":"avançada"},{"id":"C5-SEP-010","topic":"Sepse","mode":"casos","style":"Caso clínico avançado","question":"Homem de 73 anos recebe antibiótico amplo por choque séptico de foco urinário. No terceiro dia está sem vasopressor, culturas revelam E. coli sensível a cefalosporina estreita e sem outra infecção. Qual decisão é a mais racional?","options":["Manter obrigatoriamente meropenem por 30 dias","Adicionar antifúngico profilático","Descalonar a cobertura conforme susceptibilidade, foco e evolução","Interromper qualquer antibiótico independentemente do foco"],"answer":2,"explanation":"Antimicrobianos devem ser reavaliados e estreitados quando há dados para isso.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Descalonamento","difficulty":"avançada"},{"id":"C5-SEP-011","topic":"Sepse","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 62 anos com choque séptico e disfunção cardíaca mantém lactato alto e extremidades frias apesar de PAM 68 com noradrenalina e ressuscitação apropriada. Ecocardiograma mostra baixo débito. Que estratégia adicional pode ser avaliada?","options":["Dobutamina para todo paciente sem exame","Suporte inotrópico selecionado e reavaliação hemodinâmica contínua","Suspender a investigação da infecção","Administrar apenas mais oxigênio com SpO₂ normal"],"answer":1,"explanation":"Persistência de baixo débito em choque pode justificar inotropia guiada por perfil hemodinâmico.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Miocardiopatia séptica","difficulty":"avançada"},{"id":"C5-SEP-012","topic":"Sepse","mode":"casos","style":"Caso clínico avançado","question":"Paciente com sepse provável é intubado por insuficiência respiratória hipoxêmica, recebe antibiótico e fluidos. A equipe pretende usar somente pressão arterial como marcador de resposta e ignora oligúria, pele fria e lactato persistente. O que deve ser corrigido no plano?","options":["Incluir parâmetros de perfusão clínica, diurese e lactato seriado na reavaliação","Dispensar todos os exames após PAM normal","Considerar diurese irrelevante se houver sedação","Usar frequência cardíaca isolada como único parâmetro"],"answer":0,"explanation":"Ressuscitação adequada é multimodal e monitorada ao longo das horas.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Monitorização","difficulty":"avançada"},{"id":"Q5-QUE-001","topic":"Queimaduras","mode":"decorar","style":"Raciocínio rápido","question":"Em queimadura térmica eritematosa, muito dolorosa e sem bolhas, qual camada foi predominantemente lesada?","options":["Derme reticular profunda obrigatoriamente","Epiderme","Musculatura","Osso cortical"],"answer":1,"explanation":"Queimadura superficial afeta principalmente epiderme e não entra na SCQ de ressuscitação.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Profundidade","difficulty":"difícil"},{"id":"Q5-QUE-002","topic":"Queimaduras","mode":"decorar","style":"Aplicação clínica","question":"Bolhas íntegras em superfície rósea, úmida e dolorosa sugerem qual profundidade?","options":["Espessura parcial superficial","Espessura total","Quarto grau","Pele íntegra sem queimadura"],"answer":0,"explanation":"Lesão de derme superficial costuma ter bolhas e sensibilidade preservada.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Profundidade","difficulty":"média"},{"id":"Q5-QUE-003","topic":"Queimaduras","mode":"decorar","style":"Pegadinha","question":"Área esbranquiçada, seca, com sensibilidade reduzida e pouco branqueamento sugere:","options":["Eritema epidérmico simples","Pele sem lesão","Queimadura de primeiro grau exclusivamente","Espessura parcial profunda"],"answer":3,"explanation":"Queimadura dérmica profunda pode ter pouca dor e perfusão diminuída.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Profundidade","difficulty":"média"},{"id":"Q5-QUE-004","topic":"Queimaduras","mode":"decorar","style":"Comparação","question":"Uma placa rígida, semelhante a couro, insensível a estímulos leves após chama sugere:","options":["Queimadura epidérmica","Apenas dermatite","Espessura total","Espessura parcial superficial com boa reepitelização"],"answer":2,"explanation":"Queimadura de espessura total destrói terminações e geralmente exige abordagem cirúrgica.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Profundidade","difficulty":"difícil"},{"id":"Q5-QUE-005","topic":"Queimaduras","mode":"decorar","style":"Tratamento","question":"Por que lesão superficial isolada não deve ser somada no cálculo da área para ressuscitação volêmica?","options":["Sempre ocupa menos de 1%","Não representa destruição dérmica relevante para o cálculo","Nunca causa dor","É indistinguível de lesão profunda"],"answer":1,"explanation":"A SCQ de ressuscitação inclui espessura parcial e total, excluindo eritema simples.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"SCQ","difficulty":"média"},{"id":"Q5-QUE-006","topic":"Queimaduras","mode":"decorar","style":"Avaliação crítica","question":"Na regra dos nove para adulto, qual área corresponde à face anterior de uma perna inteira?","options":["9%","4,5%","18%","27%"],"answer":0,"explanation":"Cada membro inferior inteiro representa 18%, com metade anterior de 9%.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"SCQ","difficulty":"média"},{"id":"Q5-QUE-007","topic":"Queimaduras","mode":"decorar","style":"Cálculo e valores","question":"Um adulto apresenta queimaduras em todo dorso e cabeça anterior. Qual SCQ pelo método dos nove?","options":["18%","27%","36%","22,5%"],"answer":3,"explanation":"Tronco posterior 18% + metade anterior da cabeça 4,5% = 22,5%.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Cálculo","difficulty":"difícil"},{"id":"Q5-QUE-008","topic":"Queimaduras","mode":"decorar","style":"Diferenciais","question":"Se queimadura parcial acomete apenas face posterior de um braço adulto, quanto vale na regra dos nove?","options":["9%","18%","4,5%","2%"],"answer":2,"explanation":"Cada braço total vale 9%, dividido em 4,5% anterior e posterior.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"SCQ","difficulty":"média"},{"id":"Q5-QUE-009","topic":"Queimaduras","mode":"decorar","style":"Raciocínio rápido","question":"Na criança pequena, qual ferramenta ajusta melhor diferenças proporcionais de cabeça e membros?","options":["Regra adulta dos nove aplicada sem ajustes","Tabela de Lund-Browder","Apenas peso ao nascer","Índice de massa corporal"],"answer":1,"explanation":"Lund-Browder leva em conta mudança da proporção corporal com a idade.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Pediatria","difficulty":"média"},{"id":"Q5-QUE-010","topic":"Queimaduras","mode":"decorar","style":"Aplicação clínica","question":"Em adulto de 75 kg com 24% SCQ, qual volume inicial pela estimativa ABA 2 mL/kg/% para 24 horas?","options":["3.600 mL","7.200 mL","1.800 mL","9.000 mL"],"answer":0,"explanation":"2 × 75 × 24 = 3.600 mL; a reposição deve ser titulada pela resposta.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Cálculo ABA","difficulty":"difícil"},{"id":"Q5-QUE-011","topic":"Queimaduras","mode":"decorar","style":"Pegadinha","question":"Qual volume é estimado pela fórmula clássica de Parkland 4 mL/kg/% em adulto de 60 kg com 35% SCQ?","options":["4.200 mL em 24 h","2.100 mL em 24 h","12.600 mL em 24 h","8.400 mL em 24 h"],"answer":3,"explanation":"4 × 60 × 35 = 8.400 mL, contados desde a queimadura no esquema clássico.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Cálculo Parkland","difficulty":"média"},{"id":"Q5-QUE-012","topic":"Queimaduras","mode":"decorar","style":"Comparação","question":"Qual erro clássico afeta o cálculo de fluidos ao chegar ao pronto-socorro 3 horas após queimadura?","options":["Estimar área queimada","Verificar diurese","Contar a primeira janela de infusão a partir da admissão em vez do momento da lesão","Reavaliar perfusão"],"answer":2,"explanation":"Na Parkland clássica, as oito horas iniciais começam no momento da queimadura.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Tempo de infusão","difficulty":"média"},{"id":"Q5-QUE-013","topic":"Queimaduras","mode":"decorar","style":"Tratamento","question":"O cálculo inicial indica 4.800 mL na Parkland clássica. Quanto corresponde teoricamente à primeira metade do período de 24 horas?","options":["4.800 mL em 8 horas","2.400 mL nas primeiras 8 horas desde a queimadura","600 mL em 24 horas","1.200 mL após 24 horas"],"answer":1,"explanation":"Metade do volume calculado na Parkland é infundida nas primeiras 8 horas após lesão.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Cálculo","difficulty":"difícil"},{"id":"Q5-QUE-014","topic":"Queimaduras","mode":"decorar","style":"Avaliação crítica","question":"A diurese de adulto queimado com 70 kg permanece em 10 mL/h após início da reposição. Qual interpretação é mais adequada?","options":["Pode indicar hipoperfusão e necessidade de reavaliar ressuscitação","É meta típica de diurese adequada","Exclui choque","Autoriza suspender monitorização"],"answer":0,"explanation":"Diurese de cerca de 0,5 mL/kg/h é referência comum em adultos queimados.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Monitorização","difficulty":"média"},{"id":"Q5-QUE-015","topic":"Queimaduras","mode":"decorar","style":"Cálculo e valores","question":"No grande queimado, por que não se deve perseguir diurese excessivamente alta?","options":["Sempre melhora perfusão de forma linear","É essencial manter 10 mL/kg/h para todos","Permite ignorar pulmão e abdome","Pode levar a hiper-resuscitação, edema e síndromes compartimentais"],"answer":3,"explanation":"Meta de diurese serve para orientar ajuste, não justificar infusão indiscriminada.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Segurança","difficulty":"média"},{"id":"Q5-QUE-016","topic":"Queimaduras","mode":"decorar","style":"Diferenciais","question":"Paciente com queimadura circumferencial de tórax apresenta expansão torácica muito restrita e aumento das pressões de via aérea. Qual procedimento deve ser avaliado?","options":["Amputação imediata do braço","Apenas hidratação oral","Escarotomia se escara não complacente comprometer ventilação","Nenhuma medida até retirar curativos"],"answer":2,"explanation":"Escara circunferencial rígida pode limitar ventilação e exigir escarotomia.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Escarotomia","difficulty":"difícil"},{"id":"Q5-QUE-017","topic":"Queimaduras","mode":"decorar","style":"Raciocínio rápido","question":"Qual achado em mão queimada profundamente exige exame neurovascular repetido?","options":["Aumento de apetite","Piora da perfusão distal e edema progressivo","Palidez facial isolada","Taquicardia após susto sem outros achados"],"answer":1,"explanation":"Queimaduras circunferenciais podem comprometer perfusão por efeito constritivo.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Perfusão","difficulty":"média"},{"id":"Q5-QUE-018","topic":"Queimaduras","mode":"decorar","style":"Aplicação clínica","question":"Em incêndio fechado, por que uma SpO₂ normal pode ser falsamente tranquilizadora?","options":["Oxímetro convencional não diferencia oxi-hemoglobina de carboxi-hemoglobina","O oxímetro mede monóxido diretamente","A oximetria exclui inalação de fumaça","SpO₂ sempre cai para zero em intoxicação por CO"],"answer":0,"explanation":"CO pode gerar leitura falsamente normal; avaliar exposição e co-oximetria quando indicado.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Lesão inalatória","difficulty":"média"},{"id":"Q5-QUE-019","topic":"Queimaduras","mode":"decorar","style":"Pegadinha","question":"Qual sinal de risco de via aérea demanda avaliação imediata mesmo com queimadura cutânea pequena?","options":["Bolha isolada em antebraço","Eritema restrito em ombro","Dor local após resfriamento","Estridor progressivo após inalação de fumaça"],"answer":3,"explanation":"Edema de via aérea superior pode evoluir rapidamente e justificar proteção precoce.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Via aérea","difficulty":"difícil"},{"id":"Q5-QUE-020","topic":"Queimaduras","mode":"decorar","style":"Comparação","question":"Por que antibiótico sistêmico profilático não é usado de rotina apenas por queimadura térmica limpa?","options":["Todo queimado tem bacteremia obrigatória","Substitui limpeza e curativo","Não previne automaticamente infecção e favorece seleção de resistência","Impede formação de bolhas"],"answer":2,"explanation":"Antibioticoterapia depende de sinais de infecção e outras indicações específicas.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Antibiótico","difficulty":"média"},{"id":"Q5-QUE-021","topic":"Queimaduras","mode":"decorar","style":"Tratamento","question":"Qual procedimento inicial simples é indicado após escaldadura recente sem ameaça à vida?","options":["Aplicar gelo diretamente por uma hora","Interromper exposição e resfriar a área com água corrente fresca, evitando hipotermia","Passar manteiga ou óleo","Romper toda bolha intencionalmente"],"answer":1,"explanation":"Resfriamento adequado pode limitar dano, mas grandes áreas exigem atenção à hipotermia.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Primeiros socorros","difficulty":"média"},{"id":"Q5-QUE-022","topic":"Queimaduras","mode":"decorar","style":"Avaliação crítica","question":"Qual intervenção deve ser evitada sobre uma queimadura aguda devido a vasoconstrição e lesão adicional?","options":["Gelo diretamente na pele","Cobertura limpa e adequada","Retirada de anéis antes de edema","Analgesia"],"answer":0,"explanation":"Gelo pode agravar dano tecidual e deve ser evitado.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Primeiros socorros","difficulty":"difícil"},{"id":"Q5-QUE-023","topic":"Queimaduras","mode":"decorar","style":"Cálculo e valores","question":"Uma vítima com chama e fuligem está confusa, mas a radiografia pulmonar inicial é normal. Qual atitude é correta?","options":["Excluir inalação de fumaça pelo RX","Dar alta se não houver bolha","Aplicar diurético como tratamento de rotina","Investigar lesão inalatória e exposição a gases, independentemente do RX normal"],"answer":3,"explanation":"Achados iniciais de imagem podem ser pouco sensíveis para lesão inalatória.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Diagnóstico","difficulty":"média"},{"id":"Q5-QUE-024","topic":"Queimaduras","mode":"decorar","style":"Diferenciais","question":"Paciente queimado com queimadura profunda de face e mãos, porém SCQ pequena, pode necessitar centro especializado por quê?","options":["Área pequena sempre dispensa referência","Só o peso determina transferência","Região funcional e risco de sequelas importam além da porcentagem","Apenas temperatura define gravidade"],"answer":2,"explanation":"Localização em face, mãos, pés ou articulações altera conduta e encaminhamento.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Encaminhamento","difficulty":"média"},{"id":"Q5-QUE-025","topic":"Queimaduras","mode":"decorar","style":"Raciocínio rápido","question":"Em queimadura química, qual intervenção inicial é prioritária após segurança da equipe e remoção de roupas contaminadas?","options":["Aplicar neutralizante ácido ou base por conta própria","Irrigação copiosa conforme agente e protocolo","Cobrir seco sem remover contaminante","Dar corticoide tópico antes de lavar"],"answer":1,"explanation":"Descontaminação e irrigação precoce são prioritárias na maioria das exposições químicas.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Química","difficulty":"difícil"},{"id":"Q5-QUE-026","topic":"Queimaduras","mode":"decorar","style":"Aplicação clínica","question":"Qual alteração anatômica exige avaliação elétrica sistemática mesmo quando há pequenas marcas cutâneas?","options":["Trajeto de corrente e lesões musculares profundas potencialmente ocultas","Apenas cor superficial da pele","Presença obrigatória de bolhas grandes","Ausência de dor cutânea exclui lesão"],"answer":0,"explanation":"Lesão elétrica pode ser profunda e desproporcional à pele.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Elétrica","difficulty":"média"},{"id":"Q5-QUE-027","topic":"Queimaduras","mode":"decorar","style":"Pegadinha","question":"Qual fórmula usar se o enunciado explicitamente solicitar o método clássico de Parkland em vez da orientação ABA?","options":["2 mL/kg/%SCQ sempre, ignorando a referência","5 L fixos para todos","10 mL/kg independentemente da SCQ","4 mL/kg/%SCQ em 24 horas"],"answer":3,"explanation":"A pergunta pode exigir a fórmula clássica específica; distinguir da estimativa atual recomendada.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Fórmulas","difficulty":"média"},{"id":"Q5-QUE-028","topic":"Queimaduras","mode":"decorar","style":"Comparação","question":"Quais queimaduras devem compor a área usada na fórmula de reposição?","options":["Eritema sem bolha apenas","Pequenos arranhões não térmicos","Somente lesões de espessura parcial ou total","Qualquer área com pele corada por fuligem"],"answer":2,"explanation":"Eritema superficial isolado não entra na SCQ para ressuscitação.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"SCQ","difficulty":"difícil"},{"id":"Q5-QUE-029","topic":"Queimaduras","mode":"decorar","style":"Tratamento","question":"Ao observar a região queimada com aspecto seco e baixa sensibilidade, qual conclusão sobre analgesia é correta?","options":["Quanto menos dor, mais superficial necessariamente","A falta de dor local não exclui queimadura grave","Ausência de dor indica pele sadia","Lesão profunda nunca exige analgesia sistêmica"],"answer":1,"explanation":"Lesões profundas podem destruir terminações nervosas, mas coexistir com áreas dolorosas.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Profundidade","difficulty":"média"},{"id":"Q5-QUE-030","topic":"Queimaduras","mode":"decorar","style":"Avaliação crítica","question":"Que cuidado ajuda a diminuir edema constritivo em membros superiores após queimadura?","options":["Remover cedo joias e anéis antes de edema importante","Manter anéis firmes para estabilizar tecido","Enfaixar sem avaliar circulação","Restringir todos os movimentos sem exame"],"answer":0,"explanation":"Anéis e adornos podem comprometer circulação quando o edema progride.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Primeiros socorros","difficulty":"média"},{"id":"Q5-QUE-031","topic":"Queimaduras","mode":"decorar","style":"Cálculo e valores","question":"Por que uma área de espessura total pode aparecer branca, acastanhada ou carbonizada?","options":["Inflamação exclusiva da epiderme","Hiperemia superficial reversível","Ausência de qualquer agressão","Necrose e destruição de toda espessura cutânea"],"answer":3,"explanation":"Aspecto e ausência de sensibilidade podem sugerir destruição dérmica completa.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Profundidade","difficulty":"difícil"},{"id":"Q5-QUE-032","topic":"Queimaduras","mode":"decorar","style":"Diferenciais","question":"Em queimadura de mão com bolhas e sensibilidade preservada, qual medida preventiva é importante nas primeiras horas?","options":["Manter anel apertado para reduzir inchaço","Cobrir com gelo","Retirar adornos antes do edema","Restringir avaliação vascular"],"answer":2,"explanation":"Edema progressivo pode tornar anéis constritivos.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Cuidados","difficulty":"média"},{"id":"Q5-QUE-033","topic":"Queimaduras","mode":"decorar","style":"Raciocínio rápido","question":"Por que a queimadura por inalação de fumaça pode provocar problema respiratório mesmo com RX normal inicialmente?","options":["RX normal exclui edema laríngeo","Edema e lesão química das vias aéreas podem evoluir","Não há efeito da fumaça em bronquíolos","Oximetria normal descarta lesão inalatória"],"answer":1,"explanation":"Lesão inalatória requer avaliação clínica repetida e possível suporte precoce.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Inalação","difficulty":"média"},{"id":"Q5-QUE-034","topic":"Queimaduras","mode":"decorar","style":"Aplicação clínica","question":"Qual maior risco de transportar queimado grande com escara circunferencial de tronco sem observar ventilação?","options":["Restrição progressiva da expansão torácica","Hipertensão intracraniana obrigatória","Embolia pulmonar sempre presente","Desaparecimento de edema"],"answer":0,"explanation":"Escara não complacente pode dificultar movimentos respiratórios.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Escara","difficulty":"difícil"},{"id":"Q5-QUE-035","topic":"Queimaduras","mode":"decorar","style":"Pegadinha","question":"Num cálculo de SCQ do adulto, quanto representa a face anterior do tronco mais um braço anterior?","options":["27%","18%","9%","22,5%"],"answer":3,"explanation":"Tronco anterior 18% + braço anterior 4,5% = 22,5%.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Cálculo","difficulty":"média"},{"id":"Q5-QUE-036","topic":"Queimaduras","mode":"decorar","style":"Comparação","question":"Se o adulto pesa 90 kg e tem 30% SCQ, qual estimativa inicial ABA de 2 mL/kg/%SCQ?","options":["10.800 mL em 24 h","2.700 mL em 24 h","5.400 mL em 24 h","3.000 mL em 24 h"],"answer":2,"explanation":"2×90×30=5.400 mL; deve-se reavaliar perfusão e diurese.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Cálculo ABA","difficulty":"média"},{"id":"Q5-QUE-037","topic":"Queimaduras","mode":"decorar","style":"Tratamento","question":"Qual diferença de mecanismo separa queimadura química de térmica no atendimento inicial?","options":["Fonte de calor mantém reação química por dias em toda queimadura","Agente químico pode seguir reagindo até descontaminação adequada","Só a térmica exige segurança da equipe","Química não precisa de irrigação"],"answer":1,"explanation":"A remoção do agente é crucial na queimadura química.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Descontaminação","difficulty":"difícil"},{"id":"Q5-QUE-038","topic":"Queimaduras","mode":"decorar","style":"Avaliação crítica","question":"Em queimadura de pequena SCQ mas espessura total de face, qual critério de referência pesa mais?","options":["Profundidade, região especial e potencial de comprometimento funcional","Apenas cálculo de volume","Ausência de dor local como sinal de benignidade","Exclusivamente idade adulta"],"answer":0,"explanation":"Área funcional crítica pode justificar avaliação especializada independentemente do percentual.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Referência","difficulty":"média"},{"id":"C5-QUE-001","topic":"Queimaduras","mode":"casos","style":"Caso clínico avançado","question":"Homem de 35 anos pesa 80 kg e é resgatado de incêndio em galpão há duas horas, com queimaduras de espessura parcial em tronco anterior e braço direito completos (27% SCQ). Está rouco, com fuligem orofaríngea, FR 28 e SpO₂ 97%. Equipe quer aguardar dessaturação antes de agir. Qual decisão é mais correta?","options":["Usar oximetria normal para excluir lesão inalatória","Iniciar antibioticoterapia profilática e adiar via aérea","Avaliar proteção precoce da via aérea pelo risco de edema progressivo, apesar da oximetria preservada","Aplicar apenas pomada em queimadura facial"],"answer":2,"explanation":"Sinais de lesão inalatória ameaçam a via aérea mesmo com SpO₂ inicial preservada.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Lesão inalatória","difficulty":"avançada","classic_intro":"Caso clássico de Queimaduras: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-QUE-002","topic":"Queimaduras","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 44 anos com queimadura de 30% SCQ e 60 kg chega quatro horas após lesão. O hospital adota Parkland clássica de 4 mL/kg/%SCQ, sem fluidos prévios documentados. Quanto volume é estimado para ser infundido até completar as primeiras 8 horas desde a queimadura?","options":["7.200 mL nas próximas 4 horas sem avaliação","3.600 mL nas próximas 4 horas, com ajustes pela perfusão","1.800 mL em 24 horas","3.600 mL somente após completar 8 horas"],"answer":1,"explanation":"Total 4×60×30=7.200 mL; metade 3.600 mL nas primeiras 8 h contadas da lesão.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Cálculo temporal","difficulty":"avançada","classic_intro":"Caso clássico de Queimaduras: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-QUE-003","topic":"Queimaduras","mode":"casos","style":"Caso clínico avançado","question":"Homem de 49 anos com queimadura de 35% SCQ e 70 kg inicia reposição estimada pela ABA 2 mL/kg/%SCQ (4.900 mL/24h). Após seis horas, diurese 8 mL/h, FC 130, extremidades frias, PA 84/48. Qual atitude é preferível a manter a bomba no número fixo?","options":["Reavaliar hipoperfusão, perdas e resposta, titulando reposição e buscando complicações","Não alterar velocidade porque fórmula é definitiva","Suspender monitorização até 24 horas","Considerar diurese baixa meta normal"],"answer":0,"explanation":"Volume previsto é estimativa inicial; débito urinário e perfusão precisam orientar ajuste.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Reanimação guiada","difficulty":"avançada"},{"id":"C5-QUE-004","topic":"Queimaduras","mode":"casos","style":"Caso clínico avançado","question":"Menino de 4 anos apresenta escaldadura em cabeça, tronco e membro superior. Pai calcula SCQ pela regra dos nove adulta e chega a 27%. A criança está estável, mas a área parecia maior na cabeça do que no adulto. Qual avaliação corrige a estimativa?","options":["Aumentar automaticamente a SCQ adulta em 100%","Utilizar apenas regra palmar do adulto como total","Desprezar cabeça em criança","Utilizar tabela de Lund-Browder ajustada à idade"],"answer":3,"explanation":"Proporções corporais infantis exigem ajuste da estimativa de SCQ.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Pediatria","difficulty":"avançada"},{"id":"C5-QUE-005","topic":"Queimaduras","mode":"casos","style":"Caso clínico avançado","question":"Paciente de 52 anos com queimadura circunferencial de perna por chama apresenta edema crescente; pé fica frio, pulsos diminuem, parestesia e dor à mobilização passiva. Cristaloides e analgesia foram iniciados. O que precisa ser avaliado urgentemente?","options":["Aguardar necrose espontânea sem exame","Apertar faixa para conter edema","Comprometimento circulatório por escara e eventual necessidade de escarotomia","Concluir que pulsos fracos são esperados e benignos"],"answer":2,"explanation":"Escara não complacente com déficit vascular distal requer avaliação urgente de liberação.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Escarotomia","difficulty":"avançada","classic_intro":"Caso clássico de Queimaduras: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-QUE-006","topic":"Queimaduras","mode":"casos","style":"Caso clínico avançado","question":"Jovem de 21 anos sofre queimadura por fio de alta tensão com orifício de entrada na mão e saída no pé; área cutânea pequena. Relata mialgia intensa e urina escura. Qual risco oculto importa?","options":["A lesão é necessariamente superficial por pequena SCQ","Lesão muscular profunda com rabdomiólise e risco renal, exigindo avaliação sistêmica","Não há risco de arritmia em lesão elétrica","Basta curativo simples sem exames"],"answer":1,"explanation":"Corrente elétrica pode provocar dano profundo e disfunção sistêmica desproporcional à pele.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Queimadura elétrica","difficulty":"avançada","classic_intro":"Caso clássico de Queimaduras: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-QUE-007","topic":"Queimaduras","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 29 anos apresenta queimadura por produto alcalino no antebraço durante trabalho industrial. A roupa está impregnada e a dor aumenta; não há obstrução de via aérea nem trauma associado. Qual conduta inicial evita progressão da lesão?","options":["Proteger equipe, retirar roupa contaminada e irrigar copiosamente conforme protocolo do agente","Neutralizar com ácido doméstico","Cobrir sem retirar a roupa","Aplicar gelo diretamente por uma hora"],"answer":0,"explanation":"A descontaminação e irrigação são prioritárias para reduzir exposição química contínua.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Queimadura química","difficulty":"avançada"},{"id":"C5-QUE-008","topic":"Queimaduras","mode":"casos","style":"Caso clínico avançado","question":"Homem de 60 anos com queimadura de 18% SCQ, mas espessura total em ambas as mãos e face, está hemodinamicamente estável. A família argumenta que 'abaixo de 20% não precisa encaminhar'. Qual conduta é adequada?","options":["Liberar sem avaliação especializada","Usar SCQ como critério exclusivo","Aguardar infecção purulenta para encaminhar","Considerar centro especializado pela profundidade, localização funcional e risco, mesmo com SCQ menor"],"answer":3,"explanation":"Critérios de referência também consideram local e profundidade das lesões.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Encaminhamento","difficulty":"avançada"},{"id":"C5-QUE-009","topic":"Queimaduras","mode":"casos","style":"Caso clínico avançado","question":"Uma pessoa de 41 anos é retirada de incêndio em espaço fechado. Está cefaleica e confusa, com SpO₂ 99% em oxímetro comum, pH 7,32 e lactato elevado. Não há grande área cutânea queimada. Que análise deve ser considerada?","options":["Excluir intoxicação por fumaça por SpO₂ 99%","Indicar Parkland obrigatória pela confusão isolada","Exposição a monóxido de carbono e outros gases, com co-oximetria e oxigênio conforme protocolo","Desconsiderar lesão inalatória sem queimadura extensa"],"answer":2,"explanation":"SpO₂ usual não distingue carboxi-hemoglobina e pode mascarar exposição significativa.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"CO e fumaça","difficulty":"avançada"},{"id":"C5-QUE-010","topic":"Queimaduras","mode":"casos","style":"Caso clínico avançado","question":"Homem de 68 anos, queimadura de 32% SCQ, está recebendo grande volume desde o resgate. Após 10 horas há aumento da pressão abdominal, oligúria progressiva, dificuldade ventilatória e edema maciço, apesar de PA razoável. Qual complicação deve ser investigada?","options":["Melhora espontânea pelo volume","Síndrome compartimental abdominal por edema e ressuscitação excessiva","Apenas bronquite crônica","Hipovolemia descartada sem avaliação"],"answer":1,"explanation":"Hiper-resuscitação pode provocar edema grave e hipertensão intra-abdominal.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Complicação de volume","difficulty":"avançada"},{"id":"C5-QUE-011","topic":"Queimaduras","mode":"casos","style":"Caso clínico avançado","question":"Criança de 9 anos queimou o antebraço com panela quente. Lesão apresenta bolhas, pele rósea úmida, dor intensa, enchimento capilar preservado e 3% SCQ. Qual profundidade é mais provável e que interpretação sobre ressuscitação é correta?","options":["Espessura parcial superficial; fórmula volumétrica de grande queimado não é automática","Espessura total e Parkland obrigatória","Queimadura de quarto grau","Eritema exclusivamente epidérmico, apesar das bolhas"],"answer":0,"explanation":"Bolhas dolorosas com boa perfusão sugerem derme superficial; extensão pequena geralmente não demanda esquema de grande queimado.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Profundidade","difficulty":"avançada"},{"id":"C5-QUE-012","topic":"Queimaduras","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 54 anos sofre queimadura circular profunda no tórax, é intubada por edema de via aérea e tem elevação progressiva das pressões ventilatórias apesar de tubo e circuito adequados. A parede torácica está rígida. Qual intervenção deve ser discutida?","options":["Retirar toda ventilação e observar","Pedir tomografia eletiva antes de avaliar","Aumentar continuamente pressão sem avaliar parede","Escarotomia torácica quando a escara restringe a expansibilidade"],"answer":3,"explanation":"Escara circular rígida pode comprometer mecânica ventilatória e exigir liberação.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Escarotomia torácica","difficulty":"avançada"},{"id":"Q5-POL-001","topic":"Politraumatismo","mode":"decorar","style":"Raciocínio rápido","question":"Qual problema é tratado antes da etapa A no XABCDE quando presente?","options":["Hemorragia externa exsanguinante","Fratura fechada de punho","Dor muscular","Escoriação superficial"],"answer":0,"explanation":"O X representa controle de hemorragia catastrófica antes das demais etapas.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"XABCDE","difficulty":"difícil"},{"id":"Q5-POL-002","topic":"Politraumatismo","mode":"decorar","style":"Aplicação clínica","question":"Na etapa A de vítima com trauma cervical suspeito, qual manobra manual evita extensão importante do pescoço?","options":["Hiperextensão ampla da cabeça","Compressão carotídea bilateral","Movimento repetido do pescoço","Jaw thrust (anteriorização da mandíbula) com estabilização cervical"],"answer":3,"explanation":"Jaw thrust favorece abertura da via aérea sem extensão cervical desnecessária.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Via aérea","difficulty":"média"},{"id":"Q5-POL-003","topic":"Politraumatismo","mode":"decorar","style":"Pegadinha","question":"Em trauma com respiração ineficaz após proteção da via aérea, qual etapa é prioritária?","options":["Esperar Glasgow completo para ofertar oxigênio","Fazer exame ortopédico detalhado","Avaliar ventilação e lesões torácicas ameaçadoras à vida","Solicitar tomografia antes do ABC"],"answer":2,"explanation":"A etapa B identifica falência ventilatória e lesões torácicas graves.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"XABCDE","difficulty":"média"},{"id":"Q5-POL-004","topic":"Politraumatismo","mode":"decorar","style":"Comparação","question":"Uma vítima apresenta TEC prolongado, taquicardia e pele fria, mas PA 110/70. Qual conclusão é correta?","options":["Pressão normal exclui hipoperfusão","Choque compensado ainda é possível","Hemoglobina normal exclui sangramento","Taquicardia sempre é ansiedade"],"answer":1,"explanation":"Sinais de perfusão podem preceder queda de pressão.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Choque","difficulty":"difícil"},{"id":"Q5-POL-005","topic":"Politraumatismo","mode":"decorar","style":"Tratamento","question":"Logo após sangramento agudo importante, hemoglobina inicial normal deve ser interpretada como:","options":["Valor que não exclui hemorragia aguda","Prova de hemostasia completa","Indicação imediata de alta","Motivo para descartar choque"],"answer":0,"explanation":"Hb pode não refletir perda sanguínea recente imediatamente.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Laboratório","difficulty":"média"},{"id":"Q5-POL-006","topic":"Politraumatismo","mode":"decorar","style":"Avaliação crítica","question":"Qual área externa é apropriada para aplicar torniquete em hemorragia grave de membro?","options":["Diretamente sobre cotovelo","Distal ao sangramento","Sobre a mão contralateral","Proximal à lesão, evitando articulação e seguindo técnica adequada"],"answer":3,"explanation":"Torniquete deve interromper o fluxo arterial proximal à lesão.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Controle de hemorragia","difficulty":"média"},{"id":"Q5-POL-007","topic":"Politraumatismo","mode":"decorar","style":"Cálculo e valores","question":"Um torniquete controlou hemorragia e foi aplicado no pré-hospitalar. Que registro é especialmente importante?","options":["Tipo sanguíneo presumido sem teste","Somente cor da roupa","Hora de aplicação","Marca do veículo envolvido"],"answer":2,"explanation":"Registrar horário auxilia decisão clínica e segurança na reavaliação.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Controle de hemorragia","difficulty":"difícil"},{"id":"Q5-POL-008","topic":"Politraumatismo","mode":"decorar","style":"Diferenciais","question":"Em trauma pélvico instável, onde posicionar a faixa de estabilização?","options":["Acima do umbigo","Na altura dos grandes trocânteres","Na linha da cintura","Sobre a caixa torácica"],"answer":1,"explanation":"A cinta sobre os grandes trocânteres reduz mobilidade e volume pélvico.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Pelve","difficulty":"média"},{"id":"Q5-POL-009","topic":"Politraumatismo","mode":"decorar","style":"Raciocínio rápido","question":"Na suspeita de choque hemorrágico grave, qual medida supera infusão indiscriminada de litros de cristaloide?","options":["Controle de hemorragia e ressuscitação hemostática com hemocomponentes","Somente soluções hipotônicas","Aguardar cultura de sangue","Vasopressor como substituto definitivo do sangue"],"answer":0,"explanation":"Sangramento maciço exige hemostasia e reanimação balanceada.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Transfusão","difficulty":"média"},{"id":"Q5-POL-010","topic":"Politraumatismo","mode":"decorar","style":"Aplicação clínica","question":"Que proporção é frequentemente buscada na transfusão maciça balanceada descrita no ATLS?","options":["10:1:0","Apenas concentrado de hemácias para todos","5:0:0","Concentrado de hemácias:plasma:plaquetas aproximadamente 1:1:1"],"answer":3,"explanation":"A estratégia balanceada busca repor eritrócitos e componentes de coagulação.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Transfusão","difficulty":"difícil"},{"id":"Q5-POL-011","topic":"Politraumatismo","mode":"decorar","style":"Pegadinha","question":"Qual cenário recomenda considerar ácido tranexâmico em hemorragia traumática significativa quando elegível?","options":["Somente após 12 horas","No 4º dia de internação","Nas primeiras 3 horas após o trauma","Em escoriação sem sangramento"],"answer":2,"explanation":"O benefício está associado à administração precoce, geralmente até 3 h.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"TXA","difficulty":"média"},{"id":"Q5-POL-012","topic":"Politraumatismo","mode":"decorar","style":"Comparação","question":"Durante o XABCDE, qual medida reduz coagulopatia agravada por hipotermia?","options":["Infusão de fluidos frios sem indicação","Aquecimento e prevenção da perda de calor","Exposição prolongada sem cobertor","Banho gelado antes de examinar"],"answer":1,"explanation":"Hipotermia piora a coagulopatia e integra a tríade letal.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Temperatura","difficulty":"média"},{"id":"Q5-POL-013","topic":"Politraumatismo","mode":"decorar","style":"Tratamento","question":"Qual sinal pode apontar hemorragia oculta na cavidade abdominal com exame externo pouco alterado?","options":["Pele fria, taquicardia e distensão abdominal","Escoriação de joelho","Cefaleia crônica isolada","Dor na ponta do dedo"],"answer":0,"explanation":"A ausência de sangramento externo não exclui perda sanguínea maciça interna.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Choque","difficulty":"difícil"},{"id":"Q5-POL-014","topic":"Politraumatismo","mode":"decorar","style":"Avaliação crítica","question":"No eFAST, qual região avalia líquido pericárdico quando se suspeita de tamponamento?","options":["Somente região inguinal","Janela da bexiga exclusivamente","Exame da clavícula","Janela subxifoidea/pericárdica"],"answer":3,"explanation":"A janela pericárdica pode identificar derrame associado a tamponamento.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Ultrassom","difficulty":"média"},{"id":"Q5-POL-015","topic":"Politraumatismo","mode":"decorar","style":"Cálculo e valores","question":"Qual grupo de lesões pode abrigar sangramento volumoso sem extravasamento externo evidente?","options":["Somente couro cabeludo","Exclusivamente antebraço e mãos","Tórax, abdome, pelve, retroperitônio e ossos longos","Apenas fratura nasal"],"answer":2,"explanation":"Choque hemorrágico exige buscar fontes externas e internas.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Fontes de sangramento","difficulty":"média"},{"id":"Q5-POL-016","topic":"Politraumatismo","mode":"decorar","style":"Diferenciais","question":"Após intervenção no B, o médico encontra PA 78/44 e TEC 5 s. Qual fase do XABCDE requer atenção imediata?","options":["E — exame completo do dorso primeiro","C — circulação e hemorragia","D — teste neuropsicológico detalhado","Avaliação secundária antes da perfusão"],"answer":1,"explanation":"Ameaça circulatória exige reanimação durante avaliação primária.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"XABCDE","difficulty":"difícil"},{"id":"Q5-POL-017","topic":"Politraumatismo","mode":"decorar","style":"Raciocínio rápido","question":"Vítima instável após acidente tem abdome com FAST positivo. Qual raciocínio evita atraso perigoso?","options":["Controle definitivo de sangramento conforme avaliação cirúrgica, sem insistir em TC instável","TC longa antes de qualquer intervenção","Esperar hemoglobina cair","Alta para observação"],"answer":0,"explanation":"Paciente instável com sinais de hemorragia não deve ter controle definitivo atrasado.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Decisão cirúrgica","difficulty":"média"},{"id":"Q5-POL-018","topic":"Politraumatismo","mode":"decorar","style":"Aplicação clínica","question":"Em rebaixado com vômitos e aspiração, qual indicação de via aérea pesa mais do que a pontuação isolada do Glasgow?","options":["Fratura fechada de falange","Febre leve isolada","Taquicardia após dor sem repercussão","Incapacidade de proteger a via aérea e ventilação inadequada"],"answer":3,"explanation":"A via aérea é protegida pelas condições clínicas, não só por um número.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Via aérea","difficulty":"média"},{"id":"Q5-POL-019","topic":"Politraumatismo","mode":"decorar","style":"Pegadinha","question":"Qual dado sugere lesão de árvore traqueobrônquica após trauma torácico?","options":["Equimose pequena em antebraço","Tosse seca crônica sem trauma","Enfisema subcutâneo extenso e fuga aérea persistente","Dor no calcanhar"],"answer":2,"explanation":"Fuga de ar persistente e enfisema podem revelar lesão de traqueia/brônquio.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Lesão torácica","difficulty":"difícil"},{"id":"Q5-POL-020","topic":"Politraumatismo","mode":"decorar","style":"Comparação","question":"Em paciente em ventilação após IOT, qual exame contínuo ajuda a confirmar posicionamento traqueal e ventilação?","options":["Oximetria digital como única confirmação","Capnografia com onda sustentada","Ausência de ruído no tórax","Cor do tubo endotraqueal"],"answer":1,"explanation":"Capnografia é ferramenta central para confirmação e monitorização pós-IOT.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Capnografia","difficulty":"média"},{"id":"Q5-POL-021","topic":"Politraumatismo","mode":"decorar","style":"Tratamento","question":"Qual componente da etapa D avalia rapidamente lesão neurológica sem exame exaustivo?","options":["Glasgow, pupilas e sinais de lateralização","Mini exame cognitivo de 30 minutos","Teste de caminhada de 6 minutos","Audiometria completa"],"answer":0,"explanation":"Etapa D procura deterioração neurológica aguda rapidamente.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Neurológico","difficulty":"média"},{"id":"Q5-POL-022","topic":"Politraumatismo","mode":"decorar","style":"Avaliação crítica","question":"Na avaliação secundária, qual mnemônico organiza informações da história do trauma?","options":["SABA","CURB-65","CHA₂DS₂-VASc","AMPLE (alergias, medicamentos, passado, última refeição, eventos)"],"answer":3,"explanation":"AMPLE auxilia história dirigida após estabilização inicial.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Avaliação secundária","difficulty":"difícil"},{"id":"Q5-POL-023","topic":"Politraumatismo","mode":"decorar","style":"Cálculo e valores","question":"Como interpretar trauma com mecanismo de alta energia e exame inicial relativamente normal?","options":["Descartar trauma grave definitivamente","Liberar sem checar dorso","Reavaliar sistematicamente porque lesões ocultas podem evoluir","Ignorar mecanismo pelo Glasgow normal"],"answer":2,"explanation":"Mecanismo e evolução exigem vigilância e reavaliação.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Reavaliação","difficulty":"média"},{"id":"Q5-POL-024","topic":"Politraumatismo","mode":"decorar","style":"Diferenciais","question":"Qual intervenção deve preceder longa imobilização e imagem de fraturas de extremidades quando há hemorragia exsanguinante?","options":["Documentação fotográfica","Hemostasia imediata da hemorragia externa","Redução eletiva de dedo","Solicitação de densitometria"],"answer":1,"explanation":"Prioridade é tratar o que ameaça a vida antes de lesões ortopédicas estáveis.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Prioridades","difficulty":"média"},{"id":"Q5-POL-025","topic":"Politraumatismo","mode":"decorar","style":"Raciocínio rápido","question":"Um homem com choque hemorrágico persistente recebe vasopressor sem hemostasia. Qual crítica é correta?","options":["Vasopressor não substitui controle de sangramento nem ressuscitação com sangue","Noradrenalina corrige perda de hemácias","PA normal após vasoativo exclui hipoperfusão","Controle de sangramento só deve ocorrer depois de 24 horas"],"answer":0,"explanation":"Reanimar apenas números de pressão pode mascarar choque hemorrágico.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Choque","difficulty":"difícil"},{"id":"Q5-POL-026","topic":"Politraumatismo","mode":"decorar","style":"Aplicação clínica","question":"Ao expor a vítima para examinar o dorso, qual cuidado deve ser simultâneo?","options":["Manter paciente descoberto até terminar todos os exames","Virar sem equipe independentemente de lesão","Aplicar gelo em tronco","Prevenir perda de calor e restringir movimentos da coluna conforme indicação"],"answer":3,"explanation":"Exposição e proteção térmica são inseparáveis na etapa E.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Exposição","difficulty":"média"},{"id":"Q5-POL-027","topic":"Politraumatismo","mode":"decorar","style":"Pegadinha","question":"Qual sinal precoce de deterioração circulatória costuma aparecer antes de hipotensão franca?","options":["Icterícia imediata","Catarata","Taquicardia persistente com perfusão periférica ruim","Bradicardia atlética isolada"],"answer":2,"explanation":"Taquicardia e mudança cutânea frequentemente antecedem colapso pressórico.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Choque","difficulty":"média"},{"id":"Q5-POL-028","topic":"Politraumatismo","mode":"decorar","style":"Comparação","question":"Durante reanimação hemostática, por que monitorar cálcio ionizado pode ser relevante?","options":["Cálcio nunca se altera com hemocomponentes","Transfusão maciça pode cursar com hipocalcemia por citrato","Hipercalcemia é inevitável em toda transfusão","Não há relação com coagulação e contratilidade"],"answer":1,"explanation":"Citrato dos hemocomponentes pode reduzir cálcio e prejudicar coagulação/contratilidade.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Transfusão","difficulty":"difícil"},{"id":"Q5-POL-029","topic":"Politraumatismo","mode":"decorar","style":"Tratamento","question":"Após trauma fechado com perda de consciência e choque, qual princípio impede iniciar avaliação secundária antes de estabilizar?","options":["Ameaças vitais descobertas na primária devem ser tratadas imediatamente","Avaliação secundária identifica sangramento antes do X","Documentar história é prioridade sobre vias aéreas","Examinar dedo lesionado define risco de morte"],"answer":0,"explanation":"A primária XABCDE tem prioridade sobre coleta detalhada de dados.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Fluxo","difficulty":"média"},{"id":"Q5-POL-030","topic":"Politraumatismo","mode":"decorar","style":"Avaliação crítica","question":"Em politrauma com suspeita de fratura de pelve, por que testar repetidamente a estabilidade por compressão é prejudicial?","options":["Melhora hemostasia ao mobilizar","Reduz dor de forma sustentada","É exigido a cada 5 minutos","Pode agravar sangramento e deslocamento dos fragmentos"],"answer":3,"explanation":"Uma vez suspeitada fratura instável, deve-se evitar manipulação excessiva.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Pelve","difficulty":"média"},{"id":"Q5-POL-031","topic":"Politraumatismo","mode":"decorar","style":"Cálculo e valores","question":"Após resolver sangramento externo da perna e proteger via aérea, qual achado direciona para etapa B ameaçadora à vida?","options":["Dor em punho fechado","Equimose pequena de joelho","Hipóxia e desvio traqueal com murmúrio abolido","Alergia alimentar prévia"],"answer":2,"explanation":"A etapa B busca lesões ventilatórias letais como pneumotórax hipertensivo.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"B","difficulty":"difícil"},{"id":"Q5-POL-032","topic":"Politraumatismo","mode":"decorar","style":"Diferenciais","question":"Por que administrar 3 litros de cristalóide frio rapidamente em choque hemorrágico grave pode piorar o quadro?","options":["Corrige sempre deficiência plaquetária","Diluição de coagulação, hipotermia e atraso da hemostasia","É equivalente a transfundir eritrócitos","Aumenta capacidade carreadora de oxigênio"],"answer":1,"explanation":"Ressuscitação hemostática prioriza sangue e controle de sangramento, evitando excesso de cristaloide.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Fluidos","difficulty":"média"},{"id":"Q5-POL-033","topic":"Politraumatismo","mode":"decorar","style":"Raciocínio rápido","question":"Qual sinal durante reavaliação da etapa C sugere ressuscitação ainda insuficiente?","options":["Persistência de extremidades frias, confusão e TEC longo","Pulsos normais com aquecimento","Diurese recuperada","Melhora do estado mental"],"answer":0,"explanation":"Perfusão clínica complementa pressão e exames.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Perfusão","difficulty":"média"},{"id":"Q5-POL-034","topic":"Politraumatismo","mode":"decorar","style":"Aplicação clínica","question":"Qual é a vantagem de um acesso intraósseo em choque quando dois acessos periféricos falham?","options":["Substitui controle de sangramento","Dispensa checagem de posicionamento","É exclusivo de crianças","Permite acesso emergencial rápido para ressuscitação quando indicado"],"answer":3,"explanation":"IO é alternativa quando acesso venoso imediato não é viável.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Acesso","difficulty":"difícil"},{"id":"Q5-POL-035","topic":"Politraumatismo","mode":"decorar","style":"Pegadinha","question":"Por que a hemorragia pélvica pode permanecer sem alteração evidente de abdome?","options":["FAST sempre mostra todo hematoma pélvico","Pelve nunca sangra sem fratura exposta","Muito sangue pode se acumular no retroperitônio","Dor pélvica exclui lesão visceral"],"answer":2,"explanation":"Retroperitônio pode ocultar grande volume hemorrágico.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Sangramento oculto","difficulty":"média"},{"id":"Q5-POL-036","topic":"Politraumatismo","mode":"decorar","style":"Comparação","question":"Em trauma com choque e queda de consciência, qual motivo justifica reavaliar glicemia na etapa D?","options":["Glicose identifica hemoperitônio","Hipoglicemia pode contribuir para alteração neurológica","Substitui Glasgow","Define fratura cervical"],"answer":1,"explanation":"Glicemia é causa reversível de alteração de consciência concomitante.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"D","difficulty":"média"},{"id":"Q5-POL-037","topic":"Politraumatismo","mode":"decorar","style":"Tratamento","question":"Qual conclusão sobre checar parte posterior do paciente é correta após estabilização inicial?","options":["Rolamento em bloco apropriado pode revelar ferimentos ocultos","Dorso nunca contém lesão relevante","Não é necessário examinar se roupa está íntegra","A etapa E termina ao despir somente a frente"],"answer":0,"explanation":"Exposição completa inclui dorso, com proteção da coluna conforme contexto.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"E","difficulty":"difícil"},{"id":"Q5-POL-038","topic":"Politraumatismo","mode":"decorar","style":"Avaliação crítica","question":"Que risco clínico aumenta com reposição inadequada de sangue em choque hemorrágico?","options":["Compensação perfeita sem intervenção","Lesões cerebrais não são afetadas por fluxo","Desaparecimento de coagulopatia","Dívida de oxigênio e acidose por hipoperfusão"],"answer":3,"explanation":"Hipoperfusão leva à disfunção celular e acúmulo de metabólitos.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Choque","difficulty":"média"},{"id":"C5-POL-001","topic":"Politraumatismo","mode":"casos","style":"Caso clínico avançado","question":"Homem de 29 anos sofre colisão moto-caminhão. Há sangramento pulsátil na coxa, Glasgow 13, FR 32, SpO₂ 88%, PA 80/50 e desvio traqueal com MV abolido à direita. Equipe inicia TC de corpo inteiro. Qual combinação de prioridades deve ocorrer antes?","options":["Tomografia antes de qualquer intervenção","Controle imediato do sangramento exsanguinante e avaliação/tratamento de pneumotórax hipertensivo no XABCDE","Exame completo de membros antes do X","Aguardar lactato para decidir torniquete"],"answer":1,"explanation":"Há duas ameaças imediatas, hemorragia externa e potencial pneumotórax hipertensivo, que exigem ação na avaliação primária.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Ameaças simultâneas","difficulty":"avançada","classic_intro":"Caso clássico de Politraumatismo: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-POL-002","topic":"Politraumatismo","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 34 anos cai de seis metros. Está pálida, FR 22, FC 135, PA 92/60, Hb 13,8, FAST negativo, pelve instável e dor lombar. Durante reposição mantém má perfusão. Qual explicação fisiopatológica e conduta são mais coerentes?","options":["Hemorragia pélvica/retroperitoneal oculta; estabilizar pelve e iniciar abordagem hemostática","Hemoglobina normal exclui perda sanguínea","FAST negativo exclui sangramento pélvico","Vasopressor isolado substitui hemostasia"],"answer":0,"explanation":"Sangramento oculto pélvico pode coexistir com FAST negativo e Hb inicial normal.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Hemorragia oculta","difficulty":"avançada","classic_intro":"Caso clássico de Politraumatismo: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-POL-003","topic":"Politraumatismo","mode":"casos","style":"Caso clínico avançado","question":"Paciente de 48 anos, vítima de atropelamento, chega com FR 10, Glasgow 6 e vômitos ativos após controle de sangramento no membro. Há suspeita de lesão cervical. Qual manobra inicial e estratégia definitiva são adequadas?","options":["Hiperestender o pescoço vigorosamente sem restrição","Dar água antes da intubação","Realizar avaliação secundária antes da via aérea","Aspirar secreções, realizar jaw thrust com estabilização cervical e preparar via aérea definitiva por equipe experiente"],"answer":3,"explanation":"Trauma com rebaixamento e aspiração exige controle da via aérea preservando coluna cervical.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Via aérea","difficulty":"avançada"},{"id":"C5-POL-004","topic":"Politraumatismo","mode":"casos","style":"Caso clínico avançado","question":"Motociclista de 24 anos, hipotenso, sofre hemorragia de braço controlada por torniquete há 45 minutos. Chega com acidose, temperatura 34 °C e coagulopatia, necessitando transfusão. Qual estratégia combate o ciclo de deterioração?","options":["Infundir grandes volumes de cristaloide frio","Priorizar vasopressor como única terapêutica","Controle definitivo da hemorragia, hemocomponentes balanceados e aquecimento ativo","Remover torniquete sem preparo e observar"],"answer":2,"explanation":"Hemorragia, hipotermia, acidose e coagulopatia exigem reanimação hemostática e prevenção de hipotermia.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Tríade letal","difficulty":"avançada"},{"id":"C5-POL-005","topic":"Politraumatismo","mode":"casos","style":"Caso clínico avançado","question":"Homem de 56 anos é intubado após trauma. Saturação cai para 82%, a capnografia perde onda e a ausculta identifica ruídos gástricos em vez de pulmonares; o tubo foi fixado durante transporte. Qual é a prioridade?","options":["Aumentar apenas dose de sedativo","Verificar posicionamento do tubo e reestabelecer via aérea/ventilação adequadas","Concluir pneumotórax por ausência de capnografia","Ignorar capnografia se há pulso"],"answer":1,"explanation":"Ausência de onda capnográfica sustentada com ventilação gástrica sugere malposição de via aérea.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"IOT","difficulty":"avançada"},{"id":"C5-POL-006","topic":"Politraumatismo","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 26 anos apresenta trauma de alta energia, PA 74/44, MV preservado, FAST positivo e suspeita de hemorragia abdominal. Um interno quer dar 3 L de soro fisiológico até normalizar a PA antes de chamar cirurgia. Qual plano é mais adequado?","options":["Ativar reanimação hemostática, controle de fonte cirúrgica e limitar cristaloide excessivo","Adiar equipe cirúrgica até hemoglobina cair","Trocar todo sangue por coloide","Investigar apenas radiografia de punho"],"answer":0,"explanation":"Choque hemorrágico exige controle rápido do sangramento e hemocomponentes conforme protocolo.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Choque hemorrágico","difficulty":"avançada","classic_intro":"Caso clássico de Politraumatismo: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-POL-007","topic":"Politraumatismo","mode":"casos","style":"Caso clínico avançado","question":"Homem de 44 anos com fratura exposta de tíbia após acidente está orientado e estável, mas apresenta dor torácica, FR 34 e MV diminuído unilateralmente. Equipe de ortopedia pede redução imediata antes de avaliar tórax. Qual sequência é apropriada?","options":["Reduzir tíbia primeiro porque fratura é visível","Ignorar oxigenação porque Glasgow é 15","Aguardar exame do D antes do tórax","Completar e tratar problemas do B antes do manejo definitivo da fratura"],"answer":3,"explanation":"No XABCDE, ameaça ventilatória precede lesão ortopédica estável.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Priorização","difficulty":"avançada"},{"id":"C5-POL-008","topic":"Politraumatismo","mode":"casos","style":"Caso clínico avançado","question":"Trauma penetrante grave por facada, duas horas desde a lesão, envolve sangramento importante. Hemostasia e protocolo de transfusão estão em andamento. A equipe questiona o uso de ácido tranexâmico. Qual decisão temporal está correta?","options":["Aplicar somente se trauma tiver mais de 6 horas","TXA substitui controle do sangramento","Considerar em paciente elegível, idealmente o quanto antes e dentro de 3 horas do trauma","Usar apenas quando Hb atingir zero"],"answer":2,"explanation":"TXA pode ser adjuvante precoce na hemorragia traumática, sem substituir hemostasia.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"TXA","difficulty":"avançada"},{"id":"C5-POL-009","topic":"Politraumatismo","mode":"casos","style":"Caso clínico avançado","question":"Paciente de 35 anos chega após colisão, inicialmente com pressão normal, FC 120 e TEC 4 segundos. Duas horas depois torna-se hipotenso. O primeiro exame não revelou hemorragia externa, mas há dor pélvica. Qual lição da evolução é correta?","options":["PA normal no início excluía choque","Choque pode estar compensado inicialmente; repetir XABCDE e buscar hemorragia oculta","A taquicardia era irrelevante","Hemorragia ocorre só em lesão visível"],"answer":1,"explanation":"Trauma é dinâmico, e perfusão pode deteriorar antes de queda da PA.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Choque compensado","difficulty":"avançada"},{"id":"C5-POL-010","topic":"Politraumatismo","mode":"casos","style":"Caso clínico avançado","question":"Um paciente de 31 anos sofre esmagamento industrial e recebe grande quantidade de hemocomponentes. Durante a ressuscitação há hipotensão persistente, QT prolongado, cálcio ionizado reduzido e sangramento difuso. Qual componente metabólico pode agravar o quadro?","options":["Hipocalcemia relacionada ao citrato da transfusão, que precisa ser reconhecida e tratada conforme protocolo","Hipercalcemia obrigatória pela transfusão","Ausência de efeito dos hemocomponentes na coagulação","Apenas hiponatremia por água"],"answer":0,"explanation":"Transfusão maciça pode causar hipocalcemia e prejudicar coagulação e contratilidade.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Complicação transfusional","difficulty":"avançada"},{"id":"C5-POL-011","topic":"Politraumatismo","mode":"casos","style":"Caso clínico avançado","question":"Homem de 21 anos vítima de capotamento está estável após XABCDE. Queixa-se de dor lombar leve, mas não consegue explicar detalhes do acidente. Quando a equipe inicia história AMPLE e exame de dorso, surgem equimoses e dor abdominal discreta. O que este cenário ilustra?","options":["A secundária substitui permanentemente XABCDE","O paciente está fora de risco pela PA normal","Equimose dorsal descarta lesões internas","A avaliação secundária identifica lesões não evidentes, mas exige reavaliação da primária se houver deterioração"],"answer":3,"explanation":"Depois da primária, AMPLE e exame completo podem encontrar lesões ocultas e requerer retorno às prioridades.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Avaliação secundária","difficulty":"avançada"},{"id":"C5-POL-012","topic":"Politraumatismo","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 39 anos com choque hemorrágico por ferimento penetrante recebe transfusão; a equipe considera que manter PAS de 80–90 mmHg pode evitar piora do sangramento até controle cirúrgico. Entretanto, a paciente também tem TCE grave suspeito. Qual detalhe muda a estratégia?","options":["TCE reforça manter PAS sempre em 70","Hipotensão profunda protege cérebro","Traumatismo craniano exige evitar hipotensão para preservar perfusão cerebral; não aplicar hipotensão permissiva indiscriminadamente","Não há conflito entre perfusão cerebral e ressuscitação"],"answer":2,"explanation":"Hipotensão permissiva não é adequada indiscriminadamente em TCE grave concomitante.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"TCE concomitante","difficulty":"avançada","classic_intro":"Caso clássico de Politraumatismo: interprete o conjunto de sinais e exames antes de decidir."},{"id":"Q5-TCE-001","topic":"TCE","mode":"decorar","style":"Raciocínio rápido","question":"Se um paciente abre os olhos espontaneamente, está orientado e obedece comandos, qual o Glasgow?","options":["12 pontos","13 pontos","14 pontos","15 pontos"],"answer":3,"explanation":"E4 + V5 + M6 = 15.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Glasgow","difficulty":"difícil"},{"id":"Q5-TCE-002","topic":"TCE","mode":"decorar","style":"Aplicação clínica","question":"Um paciente abre os olhos ao estímulo doloroso, emite sons incompreensíveis e faz extensão à dor. Qual o Glasgow?","options":["7 pontos","8 pontos","6 pontos","5 pontos"],"answer":2,"explanation":"E2 + V2 + M2 = 6.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Glasgow","difficulty":"média"},{"id":"Q5-TCE-003","topic":"TCE","mode":"decorar","style":"Pegadinha","question":"Qual escore descreve TCE moderado?","options":["Glasgow de 13 a 15","Glasgow de 9 a 12","Glasgow de 3 a 8","Qualquer Glasgow 15 com cefaleia"],"answer":1,"explanation":"TCE é comumente classificado em leve 13–15, moderado 9–12 e grave 3–8.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Classificação","difficulty":"média"},{"id":"Q5-TCE-004","topic":"TCE","mode":"decorar","style":"Comparação","question":"Com Glasgow 8 e vômitos em jato, qual problema é prioritário?","options":["Avaliar proteção da via aérea e ventilação","Iniciar dieta oral","Testar escrita","Solicitar apenas radiografia de coluna lombar"],"answer":0,"explanation":"TCE grave frequentemente exige manejo avançado de via aérea conforme condições clínicas.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Via aérea","difficulty":"difícil"},{"id":"Q5-TCE-005","topic":"TCE","mode":"decorar","style":"Tratamento","question":"Por que um paciente com TCE grave não deve ser hiperventilado agressivamente de rotina?","options":["Hipocapnia sempre eleva fluxo cerebral","A ventilação nunca modifica CO₂","Hiperventilação aumenta oferta de glicose cerebral","Hipocapnia acentuada provoca vasoconstrição e pode reduzir perfusão cerebral"],"answer":3,"explanation":"Hiperventilação profilática prolongada aumenta risco de isquemia cerebral.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Ventilação","difficulty":"média"},{"id":"Q5-TCE-006","topic":"TCE","mode":"decorar","style":"Avaliação crítica","question":"Qual relação permite calcular a pressão de perfusão cerebral?","options":["PPC = PIC − PAM","PPC = PAM + glicemia","PPC = PAM − PIC","PPC = FC × SpO₂"],"answer":2,"explanation":"PPC depende do gradiente entre pressão arterial média e pressão intracraniana.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"PPC","difficulty":"média"},{"id":"Q5-TCE-007","topic":"TCE","mode":"decorar","style":"Cálculo e valores","question":"Se PAM é 90 mmHg e PIC é 25 mmHg, qual PPC?","options":["115 mmHg","65 mmHg","45 mmHg","25 mmHg"],"answer":1,"explanation":"PPC = 90 − 25 = 65 mmHg.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Cálculo","difficulty":"difícil"},{"id":"Q5-TCE-008","topic":"TCE","mode":"decorar","style":"Diferenciais","question":"Qual pressão intracraniana sustentada frequentemente exige considerar tratamento em TCE grave?","options":["PIC acima de 22 mmHg","PIC acima de 5 mmHg","PIC de 8 mmHg","PIC de 0 mmHg"],"answer":0,"explanation":"Elevação sustentada da PIC acima de 22 mmHg associa-se a pior prognóstico.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"PIC","difficulty":"média"},{"id":"Q5-TCE-009","topic":"TCE","mode":"decorar","style":"Raciocínio rápido","question":"Qual conjunto representa a tríade de Cushing, alerta de hipertensão intracraniana importante?","options":["Hipotensão, taquicardia e febre","Hipoglicemia, sudorese e tremor","Cefaleia, tosse e diarreia","Hipertensão, bradicardia e alteração respiratória"],"answer":3,"explanation":"A tríade de Cushing sugere elevação da pressão intracraniana.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"HIC","difficulty":"média"},{"id":"Q5-TCE-010","topic":"TCE","mode":"decorar","style":"Aplicação clínica","question":"Após trauma temporal, paciente tem midríase unilateral progressiva e queda de consciência. Qual mecanismo é especialmente preocupante?","options":["Paralisia facial periférica isolada","Lesão de nervo radial","Herniação uncal com compressão do III par","Labirintite"],"answer":2,"explanation":"Herniação uncal pode comprimir o III par e o tronco cerebral.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Herniação","difficulty":"difícil"},{"id":"Q5-TCE-011","topic":"TCE","mode":"decorar","style":"Pegadinha","question":"Qual conjunto é clássico de fratura de base do crânio?","options":["Equimose de joelho e dor no tornozelo","Sinal de Battle, equimose periorbital e possível rinorreia liquórica","Hematoma de braço isolado","Otite média crônica comprovada"],"answer":1,"explanation":"Sinais de base requerem atenção, inclusive evitar instrumentação nasal em contexto apropriado.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Fratura de base","difficulty":"média"},{"id":"Q5-TCE-012","topic":"TCE","mode":"decorar","style":"Comparação","question":"Diante de otorreia de líquido claro após trauma craniano, qual conduta diagnóstica é mais correta?","options":["Suspeitar de fístula liquórica e investigar lesão de base","Considerar sempre cerume líquido","Descartar trauma por ausência de sangue","Realizar irrigação vigorosa do ouvido"],"answer":0,"explanation":"Fístula liquórica pode indicar fratura de base e risco de complicações.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Fístula","difficulty":"média"},{"id":"Q5-TCE-013","topic":"TCE","mode":"decorar","style":"Tratamento","question":"Na TC de crânio, hematoma em crescente é mais característico de:","options":["Hematoma epidural","Infarto lacunar","Pneumoencéfalo isolado","Hematoma subdural"],"answer":3,"explanation":"Sangramento subdural frequentemente forma coleção em crescente.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Imagem","difficulty":"difícil"},{"id":"Q5-TCE-014","topic":"TCE","mode":"decorar","style":"Avaliação crítica","question":"Em hematoma epidural temporal após breve melhora, qual vaso é tradicionalmente implicado?","options":["Artéria femoral","Veia porta","Artéria meníngea média","Artéria renal"],"answer":2,"explanation":"Fratura temporal pode lesar a artéria meníngea média.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Anatomia","difficulty":"média"},{"id":"Q5-TCE-015","topic":"TCE","mode":"decorar","style":"Cálculo e valores","question":"Em suspeita de lesão axonal difusa, o que pode ocorrer apesar de TC inicial pouco expressiva?","options":["Glasgow obrigatoriamente 15","Comprometimento neurológico importante","Melhora imediata sem observação","Ausência completa de lesão"],"answer":1,"explanation":"Mecanismo de aceleração-desaceleração pode causar disfunção cerebral desproporcional à TC.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Lesão difusa","difficulty":"média"},{"id":"Q5-TCE-016","topic":"TCE","mode":"decorar","style":"Diferenciais","question":"Qual dado no exame neurológico indica deterioração que justifica reavaliação imediata?","options":["Queda de Glasgow em avaliações seriadas","Mantém resposta adequada","Pupilas simétricas e responsivas estáveis","Redução da dor após analgesia"],"answer":0,"explanation":"Piora de consciência e alterações pupilares são sinais de alarme.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Monitorização","difficulty":"difícil"},{"id":"Q5-TCE-017","topic":"TCE","mode":"decorar","style":"Raciocínio rápido","question":"Qual fenômeno agrava lesão cerebral secundária em paciente com TCE?","options":["Perfusão preservada","Controle da oxigenação","Temperatura normal","Hipotensão arterial e hipóxia"],"answer":3,"explanation":"O cérebro lesado é vulnerável à baixa entrega de oxigênio e fluxo.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Lesão secundária","difficulty":"média"},{"id":"Q5-TCE-018","topic":"TCE","mode":"decorar","style":"Aplicação clínica","question":"Por que trauma craniano em pessoa anticoagulada merece maior cautela mesmo após queda de baixa altura?","options":["Anticoagulante impede hematomas","Glasgow normal exclui sangramento","Maior risco de hemorragia intracraniana","Menor mecanismo reduz a zero o risco"],"answer":2,"explanation":"Coagulopatia aumenta risco e muda avaliação, imagem e observação.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Anticoagulação","difficulty":"média"},{"id":"Q5-TCE-019","topic":"TCE","mode":"decorar","style":"Pegadinha","question":"A suspeita de fratura deprimida exposta de crânio após pancada justifica qual abordagem?","options":["Compressão manual sobre fragmentos ósseos para reduzir","Avaliação urgente especializada e investigação por TC após estabilização","Alta rotineira sem imagem","Apenas pomada tópica sem avaliação"],"answer":1,"explanation":"Lesão aberta/deprimida eleva risco de complicações e precisa de avaliação especializada.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Fratura","difficulty":"difícil"},{"id":"Q5-TCE-020","topic":"TCE","mode":"decorar","style":"Comparação","question":"Se uma pessoa de 70 anos cai e apresenta vômitos repetidos, qual conclusão sobre necessidade de imagem é adequada?","options":["Há critérios de alto risco que justificam TC conforme protocolo","TC é sempre proibida acima de 65 anos","Vômitos repetidos excluem sangramento","Basta avaliar pressão"],"answer":0,"explanation":"Idade avançada e vômitos repetidos são fatores importantes de decisão por TC.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Critérios de TC","difficulty":"média"},{"id":"Q5-TCE-021","topic":"TCE","mode":"decorar","style":"Tratamento","question":"Na Glasgow-P, se Glasgow é 11 e uma pupila não reage, qual resultado?","options":["12 pontos","9 pontos","11 pontos","10 pontos"],"answer":3,"explanation":"Subtrai-se 1 pela não reatividade unilateral: Glasgow-P = 11 −1.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Glasgow-P","difficulty":"média"},{"id":"Q5-TCE-022","topic":"TCE","mode":"decorar","style":"Avaliação crítica","question":"Na Glasgow-P, Glasgow 9 com ambas as pupilas não reativas corresponde a:","options":["11 pontos","8 pontos","7 pontos","9 pontos"],"answer":2,"explanation":"Glasgow-P penaliza 2 pontos quando ambas as pupilas não reagem.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Glasgow-P","difficulty":"difícil"},{"id":"Q5-TCE-023","topic":"TCE","mode":"decorar","style":"Cálculo e valores","question":"Um paciente localiza estímulo doloroso, mas não obedece ordens. Qual nota motora é atribuída?","options":["M6","M5","M4","M3"],"answer":1,"explanation":"Localizar a dor é M5; obedecer comandos é M6.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Glasgow","difficulty":"média"},{"id":"Q5-TCE-024","topic":"TCE","mode":"decorar","style":"Diferenciais","question":"Qual diferença clínica permite distinguir retirada à dor de flexão anormal?","options":["Retirada flexiona para afastar estímulo, enquanto flexão anormal é estereotipada","Retirada é extensão de braços","Flexão anormal vale mais que retirada","Ambas recebem M6"],"answer":0,"explanation":"Retirada normal = M4; flexão anormal = M3.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Glasgow","difficulty":"média"},{"id":"Q5-TCE-025","topic":"TCE","mode":"decorar","style":"Raciocínio rápido","question":"Qual dado fisiológico justifica evitar hipotensão no TCE grave?","options":["Baixa PAM eleva PPC","PIC deixa de importar","Hipotensão cura edema","Baixa PAM reduz PPC e favorece isquemia"],"answer":3,"explanation":"PPC depende da PAM menos PIC.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"PPC","difficulty":"difícil"},{"id":"Q5-TCE-026","topic":"TCE","mode":"decorar","style":"Aplicação clínica","question":"Paciente tem PA 95/60 mmHg após TCE, mas sinais de hipoperfusão. Qual princípio de manejo é prioritário?","options":["Permitir hipotensão até a TC para reduzir sangramento cerebral","Ignorar perfusão com Glasgow 15","Corrigir hipotensão e investigar outras lesões hemorrágicas","Dar sedativo e observar"],"answer":2,"explanation":"Evitar hipotensão é central para reduzir lesão cerebral secundária.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Hemodinâmica","difficulty":"média"},{"id":"Q5-TCE-027","topic":"TCE","mode":"decorar","style":"Pegadinha","question":"Por que usar pupilas na avaliação inicial do TCE não substitui Glasgow?","options":["As pupilas medem diretamente resposta verbal","São avaliações complementares de consciência e possíveis disfunções neurológicas","Glasgow não inclui comportamento motor","Pupila reativa exclui lesão intracraniana"],"answer":1,"explanation":"Pupilas e Glasgow fornecem informações complementares.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Neurológico","difficulty":"média"},{"id":"Q5-TCE-028","topic":"TCE","mode":"decorar","style":"Comparação","question":"O sinal de Battle refere-se a equimose em qual região após trauma?","options":["Retroauricular sobre mastoide","Umbigo","Hipocôndrio direito","Região plantar"],"answer":0,"explanation":"Equimose retroauricular pode indicar fratura de base de crânio.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Semiologia","difficulty":"difícil"},{"id":"Q5-TCE-029","topic":"TCE","mode":"decorar","style":"Tratamento","question":"Na classificação da resposta ocular, abrir os olhos ao chamado verbal vale:","options":["E4","E2","E1","E3"],"answer":3,"explanation":"Abertura ocular à voz recebe três pontos.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Glasgow","difficulty":"média"},{"id":"Q5-TCE-030","topic":"TCE","mode":"decorar","style":"Avaliação crítica","question":"Na resposta verbal, paciente conversa mas está desorientado no tempo e espaço. Qual nota?","options":["V5","V3","V4","V2"],"answer":2,"explanation":"Conversação confusa, ainda inteligível, corresponde a V4.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Glasgow","difficulty":"média"},{"id":"Q5-TCE-031","topic":"TCE","mode":"decorar","style":"Cálculo e valores","question":"Qual achado da TC sugere edema cerebral difuso com risco de hipertensão intracraniana?","options":["Aumento do tamanho dos sulcos com atrofia isolada","Apagamento de sulcos e cisternas","Imagem normal de órbitas","Retificação de diafragma"],"answer":1,"explanation":"Redução de espaços liquóricos pode acompanhar edema cerebral.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"TC","difficulty":"difícil"},{"id":"Q5-TCE-032","topic":"TCE","mode":"decorar","style":"Diferenciais","question":"Quando considerar urgência especial em TCE com pupila fixa unilateral?","options":["Piora da consciência associada e suspeita de herniação","Saturação normal isolada","Cefaleia leve sem sinais neurológicos","Sono noturno preservado"],"answer":0,"explanation":"Alteração pupilar nova e deterioração são sinais graves.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Herniação","difficulty":"média"},{"id":"Q5-TCE-033","topic":"TCE","mode":"decorar","style":"Raciocínio rápido","question":"Um paciente mostra E2 V3 M5. Qual Glasgow total?","options":["9","11","12","10"],"answer":3,"explanation":"2+3+5=10 pontos, classificado como TCE moderado.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Glasgow","difficulty":"média"},{"id":"Q5-TCE-034","topic":"TCE","mode":"decorar","style":"Aplicação clínica","question":"A PA média está 78 mmHg e PIC 24 mmHg. Qual PPC?","options":["102 mmHg","78 mmHg","54 mmHg","24 mmHg"],"answer":2,"explanation":"PPC = PAM − PIC = 54 mmHg.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"PPC","difficulty":"difícil"},{"id":"Q5-TCE-035","topic":"TCE","mode":"decorar","style":"Pegadinha","question":"Um paciente com Glasgow 8 abre olhos à dor (E2) e emite palavras inadequadas (V3). Qual resposta motora completa o total?","options":["Obedece ordens (M6)","Flexão anormal (M3)","Localiza dor (M5)","Extensão (M2)"],"answer":1,"explanation":"8−2−3=3; M3 é flexão anormal.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Escala de Glasgow","difficulty":"média"},{"id":"Q5-TCE-036","topic":"TCE","mode":"decorar","style":"Comparação","question":"Por que uma escala de Glasgow baixa após sedação deve ser interpretada com cautela?","options":["Sedativos podem modificar respostas observadas e limitar o exame","Sedação torna Glasgow sempre 15","Glasgow não sofre interferência","Sedação exclui lesão estrutural"],"answer":0,"explanation":"Fatores como sedação e paralisia podem limitar avaliação neurológica.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Interpretação","difficulty":"média"},{"id":"Q5-TCE-037","topic":"TCE","mode":"decorar","style":"Tratamento","question":"Quando a hipotensão em TCE grave é mais perigosa para cérebro?","options":["Somente quando não existe trauma torácico","Ela sempre diminui edema sem custo","Não afeta perfusão cerebral","Quando diminui PPC num contexto de PIC elevada"],"answer":3,"explanation":"PPC baixo aumenta risco de isquemia no cérebro vulnerável.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Perfusão","difficulty":"difícil"},{"id":"Q5-TCE-038","topic":"TCE","mode":"decorar","style":"Avaliação crítica","question":"O paciente tem Glasgow 15, mas grande mecanismo de trauma, sangramento nasal e equimose retroauricular. Qual argumento favorece imagem?","options":["Glasgow 15 exclui fratura","Sem convulsão não há indicação","Sinais de fratura de base podem indicar lesão intracraniana mesmo com escore alto","A dor frontal exclui lesão temporal"],"answer":2,"explanation":"Sinais clínicos de base mudam avaliação, independentemente do Glasgow.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"TC","difficulty":"média"},{"id":"C5-TCE-001","topic":"TCE","mode":"casos","style":"Caso clínico avançado","question":"Homem de 37 anos sofre queda de andaime e chega com Glasgow 7, SpO₂ 84%, PA 82/50, anisocoria e suspeita de fratura de pelve. Neurocirurgia pede TC imediatamente. Qual ordem de prioridades reduz lesão cerebral secundária?","options":["Assegurar oxigenação, via aérea e perfusão antes de encaminhamento à imagem, tratando hemorragia concomitante","Transportar para TC apesar de choque e hipoxemia não tratados","Hiperventilar sem monitorização como rotina","Aguardar o Glasgow melhorar antes de agir"],"answer":0,"explanation":"Hipóxia e hipotensão pioram TCE e devem ser corrigidas durante avaliação inicial.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Lesão secundária","difficulty":"avançada"},{"id":"C5-TCE-002","topic":"TCE","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 68 anos usa anticoagulante por fibrilação atrial, cai da própria altura e chega com Glasgow 15, leve cefaleia e sem déficit focal. Duas horas depois fica confusa. Qual conduta é mais adequada?","options":["Dar alta porque o Glasgow inicial foi 15","Dispensar imagem por queda de baixa altura","Prescrever apenas analgésico e retorno em sete dias","Avaliar hemorragia intracraniana com TC urgente e considerar manejo da anticoagulação conforme achados/protocolo"],"answer":3,"explanation":"Anticoagulação e deterioração neurológica após trauma exigem investigação imediata.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Anticoagulação","difficulty":"avançada"},{"id":"C5-TCE-003","topic":"TCE","mode":"casos","style":"Caso clínico avançado","question":"Jovem de 22 anos recebe golpe temporal numa partida e perde consciência por um minuto. Conversa normalmente por 30 minutos, então passa a vomitar, apresenta midríase unilateral e queda de Glasgow. TC mostra coleção biconvexa temporal. Qual combinação diagnóstico-mecanismo melhor explica o quadro?","options":["Subdural crônico por ruptura lenta de veias em ponte","Lesão axonal difusa sem sangramento","Hematoma epidural com possível lesão da artéria meníngea média e herniação em evolução","Acidente vascular isquêmico primário"],"answer":2,"explanation":"Intervalo lúcido, coleção biconvexa temporal e deterioração são clássicos do epidural.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Epidural","difficulty":"avançada","classic_intro":"Caso clássico de TCE: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-TCE-004","topic":"TCE","mode":"casos","style":"Caso clínico avançado","question":"Homem de 75 anos cai há três semanas, manteve boa recuperação inicial, mas desenvolve cefaleia e confusão progressivas. TC evidencia coleção extra-axial em crescente com diferentes densidades. Está em uso de anticoagulante. Qual diagnóstico melhor integra tempo e imagem?","options":["Hematoma epidural agudo típico","Hematoma subdural subagudo/crônico","Pneumotórax","TCE leve sem complicação"],"answer":1,"explanation":"Evolução lenta em idoso anticoagulado e coleção em crescente apontam para subdural.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Subdural","difficulty":"avançada","classic_intro":"Caso clássico de TCE: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-TCE-005","topic":"TCE","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 41 anos após colisão tem abertura ocular à voz (E3), verbal confusa (V4) e localiza dor (M5). Pupila direita não reage à luz; esquerda reage. Qual Glasgow-P e interpretação estão corretos?","options":["Glasgow 12, Glasgow-P 11; a alteração pupilar aumenta preocupação com lesão intracraniana","Glasgow 12, Glasgow-P 13; pupila fixa eleva pontuação","Glasgow 15, Glasgow-P 15","Glasgow 10, Glasgow-P 8"],"answer":0,"explanation":"E3 + V4 + M5 = 12; subtrai-se um ponto por pupila não reativa.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Glasgow-P","difficulty":"avançada","classic_intro":"Caso clássico de TCE: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-TCE-006","topic":"TCE","mode":"casos","style":"Caso clínico avançado","question":"Homem de 27 anos sofre colisão de alta velocidade, permanece em coma com Glasgow 5 e hipóxia. TC inicial mostra pequenas lesões puntiformes, sem grande hematoma. Equipe pergunta como pode haver coma tão profundo com imagem relativamente discreta. Qual mecanismo é plausível?","options":["Subdural crônico obrigatório","Ansiedade como única causa","Ausência de dano cerebral por TC sem massa","Lesão axonal difusa por forças de aceleração e cisalhamento"],"answer":3,"explanation":"Lesão axonal difusa pode causar coma desproporcional às alterações da TC.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Lesão axonal difusa","difficulty":"avançada"},{"id":"C5-TCE-007","topic":"TCE","mode":"casos","style":"Caso clínico avançado","question":"Paciente com TCE grave está em UTI com PAM 84 mmHg e PIC 28 mmHg. Há queda de diurese e nova assimetria pupilar. Qual PPC calculada e sua interpretação?","options":["112 mmHg; normal em todo TCE","28 mmHg; suficiente para excluir isquemia","56 mmHg; valor que exige avaliação urgente do risco de perfusão inadequada","84 mmHg; PIC não importa"],"answer":2,"explanation":"PPC = PAM – PIC = 56; a PIC elevada e alteração pupilar exigem reavaliação urgente.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"PPC","difficulty":"avançada"},{"id":"C5-TCE-008","topic":"TCE","mode":"casos","style":"Caso clínico avançado","question":"Homem de 32 anos com fratura de base suspeita após trauma facial apresenta equimose retroauricular, rinorreia aquosa e epistaxe. Uma equipe sugere introduzir sonda nasogástrica cegamente pela narina. Qual cuidado é mais seguro?","options":["A rinorreia exclui lesão de base","Evitar instrumentação nasal cega em suspeita de fratura de base e buscar alternativa conforme indicação","Introduzir sonda profunda sem avaliação","Dar alta se a pupila estiver normal"],"answer":1,"explanation":"Sinais de fratura de base tornam instrumentação nasal potencialmente arriscada.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Fratura de base","difficulty":"avançada"},{"id":"C5-TCE-009","topic":"TCE","mode":"casos","style":"Caso clínico avançado","question":"Jovem de 19 anos com TCE apresenta PA 180/65, FC 42 e padrão respiratório irregular. Evolui com midríase direita e Glasgow em queda. Qual hipótese e prioridade explicam o conjunto?","options":["Hipertensão intracraniana grave com possível herniação; acionar suporte avançado e neurocirurgia","Hipovolemia compensada sem necessidade de intervenção","Crise vagal benigna","Hipertensão essencial isolada"],"answer":0,"explanation":"Tríade de Cushing e anisocoria progressiva sugerem aumento crítico de PIC e herniação.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Herniação","difficulty":"avançada","classic_intro":"Caso clássico de TCE: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-TCE-010","topic":"TCE","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 30 anos com trauma craniano mantém Glasgow 14, mas vomita três vezes e apresenta otorreia de líquido claro. Está hemodinamicamente estável. Qual plano evita subestimar o risco pelo escore 'quase normal'?","options":["Alta imediata porque Glasgow 14 é leve","Dispensar exame de ouvido","Ignorar vômitos por não haver convulsão","Indicar investigação por imagem e avaliação de possível fratura de base/lesão intracraniana"],"answer":3,"explanation":"Critérios clínicos de risco podem indicar TC mesmo em TCE leve.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"TC no TCE leve","difficulty":"avançada"},{"id":"C5-TCE-011","topic":"TCE","mode":"casos","style":"Caso clínico avançado","question":"Homem de 51 anos com TCE grave está ventilado e recebe hiperventilação contínua para PaCO₂ 24 mmHg sem sinais de herniação. A equipe afirma que 'quanto menor o CO₂, melhor a oxigenação cerebral'. Qual correção é necessária?","options":["PaCO₂ 24 é objetivo universal","Hiperventilação não modifica fluxo cerebral","Hipocapnia prolongada pode reduzir fluxo cerebral e causar isquemia; evitar hiperventilação profilática","O risco é apenas acidose respiratória"],"answer":2,"explanation":"Vasoconstrição cerebral por hipocapnia pode comprometer perfusão.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Hiperventilação","difficulty":"avançada"},{"id":"C5-TCE-012","topic":"TCE","mode":"casos","style":"Caso clínico avançado","question":"Após queda de motocicleta, jovem apresenta lesão frontal com edema cerebral, PaO₂ 58, PAM 70 e PIC 26. Neurologicamente não abre olhos, apenas flexão anormal. Qual risco integrado exige ação?","options":["As variáveis são independentes e podem aguardar","Hipoxemia, PPC reduzida e disfunção neurológica grave simultâneas","PaO₂ 58 é sempre suficiente","A PIC de 26 protege o cérebro por compressão"],"answer":1,"explanation":"PaO₂ baixa e PPC de 44 mmHg (70−26) aumentam risco de lesão secundária; é necessário corrigir causas.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Fisiologia cerebral","difficulty":"avançada"},{"id":"Q5-TOR-001","topic":"Trauma torácico","mode":"decorar","style":"Raciocínio rápido","question":"Após trauma, o conjunto hipotensão, turgência jugular, hipoxemia e hipersonoridade unilateral sugere:","options":["Hemotórax simples estável","Contusão de ombro","Pneumotórax hipertensivo","Fratura isolada de clavícula"],"answer":2,"explanation":"Pressão intrapleural elevada pode comprimir retorno venoso e provocar choque obstrutivo.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Emergência","difficulty":"difícil"},{"id":"Q5-TOR-002","topic":"Trauma torácico","mode":"decorar","style":"Aplicação clínica","question":"Por que um paciente instável com suspeita clínica de pneumotórax hipertensivo não deve esperar radiografia?","options":["A radiografia sempre precede manobras salvadoras","A descompressão é uma intervenção tempo-dependente guiada pela clínica","Não há risco antes de exames","O diagnóstico depende de cultura de escarro"],"answer":1,"explanation":"A ameaça à vida exige tratamento imediato sem atraso por imagem.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Prioridade","difficulty":"média"},{"id":"Q5-TOR-003","topic":"Trauma torácico","mode":"decorar","style":"Pegadinha","question":"Que procedimento normalmente sucede descompressão de emergência de pneumotórax hipertensivo?","options":["Drenagem pleural definitiva conforme técnica e contexto","Curativo de pele isolado para todos","Toracocentese diagnóstica sem intervenção definitiva","Intubação obrigatória para todos após descompressão"],"answer":0,"explanation":"Descompressão inicial não substitui tratamento definitivo.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Drenagem","difficulty":"média"},{"id":"Q5-TOR-004","topic":"Trauma torácico","mode":"decorar","style":"Comparação","question":"Uma ferida aberta aspirativa de tórax precisa de qual intervenção provisória?","options":["Curativo ininterrupto completamente fechado sem vigilância","Sutura complexa antes do ABC","Nenhuma cobertura","Vedação torácica adequada, preferencialmente ventilada, com monitorização de tensão"],"answer":3,"explanation":"Curativo torácico ventilado com monitorização é estratégia para pneumotórax aberto.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Pneumotórax aberto","difficulty":"difícil"},{"id":"Q5-TOR-005","topic":"Trauma torácico","mode":"decorar","style":"Tratamento","question":"Qual característica da dinâmica de parede define tórax instável?","options":["Sibilos difusos em paciente asmático","Crepitação apenas da clavícula","Movimento paradoxal de segmento costal","Movimento normal de todas as costelas"],"answer":2,"explanation":"O segmento instável pode mover-se para dentro na inspiração e para fora na expiração.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Tórax instável","difficulty":"média"},{"id":"Q5-TOR-006","topic":"Trauma torácico","mode":"decorar","style":"Avaliação crítica","question":"Uma contusão pulmonar significativa pode piorar algumas horas depois do impacto porque:","options":["A lesão sempre desaparece imediatamente","Edema e hemorragia alveolar evoluem progressivamente","Não interfere na oxigenação","O RX inicial é obrigatoriamente diagnóstico"],"answer":1,"explanation":"Contusão evolui nas horas seguintes e exige reavaliação.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Contusão","difficulty":"média"},{"id":"Q5-TOR-007","topic":"Trauma torácico","mode":"decorar","style":"Cálculo e valores","question":"Hemotórax agudo com choque e macicez à percussão deve levantar qual hipótese?","options":["Sangramento pleural significativo","Pneumotórax hipertensivo com hipersonoridade","Asma isolada","Bronquite crônica sem trauma"],"answer":0,"explanation":"Sangue na pleura pode causar macicez, redução do murmúrio e choque hemorrágico.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Hemotórax","difficulty":"difícil"},{"id":"Q5-TOR-008","topic":"Trauma torácico","mode":"decorar","style":"Diferenciais","question":"Na drenagem torácica, saída imediata de 1.800 mL de sangue justifica qual conduta?","options":["Alta após esvaziar dreno","Drenagem por sete dias sem controle","Suspender monitorização","Avaliação cirúrgica torácica urgente com ressuscitação"],"answer":3,"explanation":"Volume inicial muito elevado sugere hemorragia que pode exigir cirurgia.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Toracotomia","difficulty":"média"},{"id":"Q5-TOR-009","topic":"Trauma torácico","mode":"decorar","style":"Raciocínio rápido","question":"Qual limiar de perda inicial pelo dreno é usado classicamente para discutir exploração em hemotórax maciço no adulto?","options":["Cerca de 50 mL","Menos de 100 mL","Cerca de 1.500 mL","Somente acima de 5.000 mL"],"answer":2,"explanation":"Saída inicial superior a ~1.500 mL é referência clássica, integrada à fisiologia e evolução.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Limiar","difficulty":"média"},{"id":"Q5-TOR-010","topic":"Trauma torácico","mode":"decorar","style":"Aplicação clínica","question":"Por que sangramento persistente de 250 mL/h por horas não deve ser ignorado?","options":["É sempre normal após drenagem","Pode sinalizar hemorragia pleural contínua que exige discussão cirúrgica","Confirma hemostasia","Impede reavaliação do trauma"],"answer":1,"explanation":"Perda contínua importa tanto quanto o volume inicial.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Drenagem","difficulty":"difícil"},{"id":"Q5-TOR-011","topic":"Trauma torácico","mode":"decorar","style":"Pegadinha","question":"Após trauma penetrante, hipotensão, bulhas abafadas e turgência jugular formam qual tríade?","options":["Tríade de Beck do tamponamento cardíaco","Tríade de Cushing","Tríade de Charcot","Tríade de Anthonisen"],"answer":0,"explanation":"Tríade de Beck é clássica de tamponamento, embora nem sempre completa.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Tamponamento","difficulty":"média"},{"id":"Q5-TOR-012","topic":"Trauma torácico","mode":"decorar","style":"Comparação","question":"Que achado do POCUS reforça suspeita de tamponamento traumático?","options":["Ausência de conteúdo abdominal","Hiperinsuflação pulmonar isolada","Trombo venoso distal","Líquido pericárdico com sinais de comprometimento hemodinâmico"],"answer":3,"explanation":"O ultrassom direcionado pode identificar derrame pericárdico no trauma.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Ultrassom","difficulty":"média"},{"id":"Q5-TOR-013","topic":"Trauma torácico","mode":"decorar","style":"Tratamento","question":"Que achado radiográfico após desaceleração brusca pode sugerir lesão de aorta torácica?","options":["Hiperinsuflação isolada","Desvio de septo nasal","Mediastino alargado","Lesão de joelho"],"answer":2,"explanation":"Alargamento mediastinal é sinal de alerta, não diagnóstico isolado.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Aorta","difficulty":"difícil"},{"id":"Q5-TOR-014","topic":"Trauma torácico","mode":"decorar","style":"Avaliação crítica","question":"Em paciente estável com suspeita de lesão traumática da aorta, qual exame geralmente confirma a lesão?","options":["Eletroencefalograma","Angiotomografia de tórax","Colangiografia","Radiografia de joelho"],"answer":1,"explanation":"Angio-TC avalia a aorta e suas lesões traumáticas.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Imagem","difficulty":"média"},{"id":"Q5-TOR-015","topic":"Trauma torácico","mode":"decorar","style":"Cálculo e valores","question":"Por que intubação e ventilação com pressão positiva podem precipitar colapso em pneumotórax não tratado?","options":["Podem aumentar pressão intrapleural e converter para tensão","Eliminam sempre a necessidade de drenagem","Curam toda laceração pleural","Aumentam perfusão pleural obrigatoriamente"],"answer":0,"explanation":"Pressão positiva pode piorar pneumotórax e hemodinâmica.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Ventilação","difficulty":"média"},{"id":"Q5-TOR-016","topic":"Trauma torácico","mode":"decorar","style":"Diferenciais","question":"Após IOT por trauma, ausculta unilateralmente reduzida pode ocorrer por:","options":["Perfusão cerebral excessiva","Gastrite aguda","Fratura de tíbia como causa isolada","Intubação seletiva ou lesão pleural; verificar tubo e tórax"],"answer":3,"explanation":"A posição do tubo deve ser conferida antes de atribuir achado apenas à pleura.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"IOT","difficulty":"difícil"},{"id":"Q5-TOR-017","topic":"Trauma torácico","mode":"decorar","style":"Raciocínio rápido","question":"Que sinal clínico favorece pneumotórax simples sem tensão quando comparado ao hipertensivo?","options":["Hipotensão profunda com desvio traqueal","Turgência jugular e piora rápida","Paciente relativamente estável, sem sinais de choque obstrutivo","Parada iminente"],"answer":2,"explanation":"Pneumotórax simples pode cursar com dor e dispneia sem instabilidade.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Diagnóstico","difficulty":"média"},{"id":"Q5-TOR-018","topic":"Trauma torácico","mode":"decorar","style":"Aplicação clínica","question":"A analgesia em fraturas múltiplas de costelas tem qual benefício respiratório?","options":["Aumenta sempre hipercapnia","Melhora capacidade de ventilar, tossir e eliminar secreções","Substitui avaliação de contusão","Dispensa suporte ventilatório quando necessário"],"answer":1,"explanation":"Dor intensa induz hipoventilação e atelectasia.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Analgesia","difficulty":"média"},{"id":"Q5-TOR-019","topic":"Trauma torácico","mode":"decorar","style":"Pegadinha","question":"Em vítima com múltiplas fraturas costais, qual consequência da ventilação superficial merece prevenção?","options":["Atelectasia e pneumonia","Aumento obrigatório de capacidade pulmonar","Desaparecimento do risco de infecção","Melhora progressiva sem suporte"],"answer":0,"explanation":"Controle da dor e suporte respiratório reduzem complicações.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Complicações","difficulty":"difícil"},{"id":"Q5-TOR-020","topic":"Trauma torácico","mode":"decorar","style":"Comparação","question":"O que muda no manejo de lesão torácica com instabilidade hemodinâmica progressiva?","options":["Solicitação de exames eletivos antes de intervir","Alta se ainda houver consciência","Reavaliação somente após o turno","Reanimação e correção imediata da causa, sem esperar investigação extensa"],"answer":3,"explanation":"Prioridade em trauma é reconhecer e tratar causas reversíveis fatais.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Prioridade","difficulty":"média"},{"id":"Q5-TOR-021","topic":"Trauma torácico","mode":"decorar","style":"Tratamento","question":"Que apresentação é compatível com contusão pulmonar mesmo com radiografia inicial normal?","options":["Tosse de meses sem trauma","Glasgow 15 sem dispneia em qualquer momento","Hipoxemia progressiva horas após impacto e dor torácica","Dor de tornozelo isolada"],"answer":2,"explanation":"Contusão pode manifestar-se radiologicamente e clinicamente de forma tardia.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Contusão","difficulty":"média"},{"id":"Q5-TOR-022","topic":"Trauma torácico","mode":"decorar","style":"Avaliação crítica","question":"Qual dado respiratório deve ser monitorado seriamente no trauma torácico?","options":["Apenas temperatura","Saturação, frequência, trabalho respiratório e evolução hemodinâmica","Somente escore de dor inicial","Apenas cor do curativo"],"answer":1,"explanation":"Lesões e complicações podem evoluir ao longo do atendimento.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Monitorização","difficulty":"difícil"},{"id":"Q5-TOR-023","topic":"Trauma torácico","mode":"decorar","style":"Cálculo e valores","question":"Se há enfisema subcutâneo maciço após impacto e fuga aérea persistente pelo dreno, suspeite de:","options":["Lesão traqueobrônquica","Pneumonia viral isolada","Hematoma cerebral","Lesão uretral"],"answer":0,"explanation":"Fístula aérea persistente pode revelar ruptura de via aérea central.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Traqueobrônquica","difficulty":"média"},{"id":"Q5-TOR-024","topic":"Trauma torácico","mode":"decorar","style":"Diferenciais","question":"Por que deve-se evitar considerar ausência de desvio traqueal como exclusão de pneumotórax hipertensivo?","options":["Está presente em toda fase inicial","Determina saturação","Só aparece em choque séptico","Desvio traqueal é sinal tardio e pode estar ausente"],"answer":3,"explanation":"Pneumotórax hipertensivo é diagnóstico sobretudo clínico e evolutivo.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Armadilha","difficulty":"média"},{"id":"Q5-TOR-025","topic":"Trauma torácico","mode":"decorar","style":"Raciocínio rápido","question":"Durante atendimento de ferida penetrante com choque e murmúrio diminuído bilateralmente, que abordagem é essencial?","options":["Assumir sempre lesão única unilateral","Descartar hemotórax porque não há macicez descrita","Avaliar ambos os hemitórax e possibilidades simultâneas de lesão","Fazer somente ECG"],"answer":2,"explanation":"Trauma de alta energia pode provocar lesões múltiplas e bilaterais.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Avaliação","difficulty":"difícil"},{"id":"Q5-TOR-026","topic":"Trauma torácico","mode":"decorar","style":"Aplicação clínica","question":"Na avaliação de tórax instável, qual afirmação é mais correta?","options":["Sempre basta imobilizar costelas externamente","A gravidade depende também de contusão pulmonar e ventilação, não apenas do número de fraturas","Toda fratura exige IOT imediata","Não há risco de insuficiência respiratória"],"answer":1,"explanation":"Suporte de oxigenação, analgesia e avaliação da contusão guiam tratamento.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Tórax instável","difficulty":"média"},{"id":"Q5-TOR-027","topic":"Trauma torácico","mode":"decorar","style":"Pegadinha","question":"Em drenagem de hemotórax, qual fator pode ser tão relevante quanto o volume medido?","options":["Instabilidade e necessidade transfusional crescente","Marca comercial do dreno","Hora do dia","Cor da parede da sala"],"answer":0,"explanation":"Critérios cirúrgicos integram fisiologia, débito e transfusões.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Hemotórax","difficulty":"média"},{"id":"Q5-TOR-028","topic":"Trauma torácico","mode":"decorar","style":"Comparação","question":"Diante de lesão aórtica em paciente estável, a prioridade diagnóstica é diferente da tensão porque:","options":["Ambas exigem radiografia antes de qualquer terapia","Nenhuma demanda emergência","Aorta só é identificada por exame de urina","A aorta pode ser avaliada por angio-TC após estabilização, enquanto tensão exige descompressão imediata"],"answer":3,"explanation":"A estabilidade fisiológica define o tempo disponível para investigação.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Prioridade","difficulty":"difícil"},{"id":"Q5-TOR-029","topic":"Trauma torácico","mode":"decorar","style":"Tratamento","question":"Qual procedimento definitivo é comum em pneumotórax traumático significativo com repercussão respiratória?","options":["Diurético de alça obrigatório","Antibiótico isolado","Drenagem pleural conforme indicação e avaliação","Toracotomia em todos os pacientes"],"answer":2,"explanation":"A escolha depende do tamanho, sintomas, ventilação e contexto traumático.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Tratamento","difficulty":"média"},{"id":"Q5-TOR-030","topic":"Trauma torácico","mode":"decorar","style":"Avaliação crítica","question":"Qual mecanismo pode levar à hipoxemia na contusão pulmonar?","options":["Aumento de ar puro nos alvéolos","Edema e hemorragia alveolar geram desequilíbrio ventilação-perfusão","Broncodilatação total","Aumento exclusivo de hemoglobina"],"answer":1,"explanation":"Contusão altera troca gasosa mesmo sem pneumotórax.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Fisiopatologia","difficulty":"média"},{"id":"Q5-TOR-031","topic":"Trauma torácico","mode":"decorar","style":"Cálculo e valores","question":"Em trauma com PA 80/50, MV ausente à esquerda e macicez, qual causa de choque predomina?","options":["Hemorragia pleural significativa","Retenção de CO₂ crônica isolada","Pneumotórax hipertensivo com hiperressonância","Asma persistente sem trauma"],"answer":0,"explanation":"Macicez e instabilidade sugerem hemotórax maciço.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Diagnóstico","difficulty":"difícil"},{"id":"Q5-TOR-032","topic":"Trauma torácico","mode":"decorar","style":"Diferenciais","question":"Por que a drenagem de sangue do tórax não representa hemostasia por si só?","options":["O dreno sempre cauteriza vasos","O dreno repõe volume","Sangramento pleural cessa ao se colocar curativo","O dreno evacua sangue, mas a lesão vascular pode continuar sangrando"],"answer":3,"explanation":"Controle de sangramento pode precisar de cirurgia ou embolização conforme caso.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Hemotórax","difficulty":"média"},{"id":"Q5-TOR-033","topic":"Trauma torácico","mode":"decorar","style":"Raciocínio rápido","question":"Qual achado após trauma sinaliza necessidade de considerar ruptura diafragmática associada?","options":["Bolha em membro superior","Edema periorbital","Vísceras abdominais projetadas no hemitórax","Sibilância difusa após gripe"],"answer":2,"explanation":"Ruptura diafragmática pode permitir herniação de estruturas abdominais.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Diafragma","difficulty":"média"},{"id":"Q5-TOR-034","topic":"Trauma torácico","mode":"decorar","style":"Aplicação clínica","question":"Uma ferida penetrante com turgência jugular, bulhas abafadas e MV presente bilateralmente sugere prioridade de investigar:","options":["Pneumotórax hipertensivo confirmado","Tamponamento cardíaco","Contusão de perna","Asma"],"answer":1,"explanation":"MV bilateral preservado com sinais de Beck favorece tamponamento.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Diagnóstico","difficulty":"difícil"},{"id":"Q5-TOR-035","topic":"Trauma torácico","mode":"decorar","style":"Pegadinha","question":"Em vítima com fraturas costais, qual piora pode se instalar em 24 horas apesar de RX inicial pouco alterado?","options":["Insuficiência respiratória por contusão pulmonar","Cura anatômica completa de fraturas","Ausência de qualquer complicação","Normalização universal da oxigenação"],"answer":0,"explanation":"Contusão pode evoluir, exigindo observação clínica.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Contusão","difficulty":"média"},{"id":"Q5-TOR-036","topic":"Trauma torácico","mode":"decorar","style":"Comparação","question":"Qual decisão sobre toracotomia em hemotórax deve integrar além do volume inicial?","options":["Apenas idade do paciente","Só presença de tosse","Somente cor do curativo","Sangramento por hora, instabilidade e transfusões necessárias"],"answer":3,"explanation":"Critérios cirúrgicos são contextuais, com perda sustentada e fisiologia.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Decisão cirúrgica","difficulty":"média"},{"id":"Q5-TOR-037","topic":"Trauma torácico","mode":"decorar","style":"Tratamento","question":"Um paciente estável com pneumotórax pequeno e ventilação espontânea demanda qual conduta?","options":["Descompressão emergencial obrigatória para todo pneumotórax","IOT imediata para todos","Avaliar tamanho, sintomas e indicação de observação/drenagem conforme protocolo","Antibioticoterapia por 14 dias obrigatória"],"answer":2,"explanation":"Pneumotórax simples pode admitir manejo individualizado se paciente estável.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Manejo","difficulty":"difícil"},{"id":"C5-TOR-001","topic":"Trauma torácico","mode":"casos","style":"Caso clínico avançado","question":"Homem de 32 anos chega após colisão moto-carro com PA 76/40, FC 142, SpO₂ 82%, distensão de jugulares, hiperressonância à direita e MV abolido nesse lado. Há necessidade de IOT, mas a equipe aguarda radiografia antes de qualquer procedimento pleural. Qual prioridade é mais adequada?","options":["Fazer TC de tórax antes de qualquer intervenção","Administrar diurético para reduzir jugulares","Considerar a presença de pulso suficiente para excluir ameaça","Descomprimir imediatamente o hemitórax comprometido e providenciar drenagem definitiva, sem atrasar por imagem"],"answer":3,"explanation":"Pneumotórax hipertensivo é diagnóstico clínico em paciente instável e requer descompressão urgente.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Pneumotórax hipertensivo","difficulty":"avançada","classic_intro":"Caso clássico de Trauma torácico: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-TOR-002","topic":"Trauma torácico","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 45 anos sofre trauma torácico penetrante. Está pálida, PA 85/52 e MV reduzido à esquerda; percussão maciça. Dreno pleural libera imediatamente 1.650 mL de sangue e o choque persiste com transfusão iniciada. Qual decisão é mais apropriada?","options":["Aguardar 24 horas e anotar volume","Retirar dreno para reter sangue","Acionar avaliação cirúrgica torácica urgente para controle hemorrágico","Prescrever broncodilatador e alta"],"answer":2,"explanation":"Hemotórax maciço com perda inicial acima de 1.500 mL e choque sugere necessidade de intervenção cirúrgica.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Hemotórax maciço","difficulty":"avançada","classic_intro":"Caso clássico de Trauma torácico: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-TOR-003","topic":"Trauma torácico","mode":"casos","style":"Caso clínico avançado","question":"Homem de 71 anos cai de escada. Tem múltiplas fraturas costais, dor 9/10, respiração superficial, SpO₂ 91% e crepitações discretas. RX inicial quase normal. Após 8 horas, piora oxigenação e surgem opacidades no hemitórax contuso. Qual combinação melhor explica o quadro?","options":["Pneumotórax hipertensivo comprovado pelo RX inicial","Contusão pulmonar evolutiva e hipoventilação por dor, exigindo suporte e analgesia","Asma sem trauma","Ruptura de aorta inevitável"],"answer":1,"explanation":"Contusão pulmonar pode evoluir em horas, enquanto analgesia inadequada piora ventilação.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Contusão pulmonar","difficulty":"avançada"},{"id":"C5-TOR-004","topic":"Trauma torácico","mode":"casos","style":"Caso clínico avançado","question":"Paciente de 28 anos vítima de facada apresenta PA 80/50, turgência jugular, MV bilateral preservado, bulhas abafadas e derrame pericárdico no POCUS. Sua equipe discute choque hemorrágico simples. Qual lesão deve ser tratada como causa de choque obstrutivo?","options":["Tamponamento cardíaco traumático, com necessidade de intervenção definitiva urgente","Pneumotórax hipertensivo bilateral obrigatório","Asma refratária","Hipovolemia por desidratação"],"answer":0,"explanation":"Perfusão prejudicada por derrame pericárdico sob pressão produz choque obstrutivo.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Tamponamento","difficulty":"avançada","classic_intro":"Caso clássico de Trauma torácico: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-TOR-005","topic":"Trauma torácico","mode":"casos","style":"Caso clínico avançado","question":"Homem de 36 anos apresenta ferida torácica aberta com ruído de sucção, dispneia, PA 115/74 e SpO₂ 90%. Curativo oclusivo improvisado sem via de escape é colocado, após o que surge hipotensão e piora ventilatória. Qual explicação orienta correção?","options":["A piora comprova pneumonia bacteriana","Curativo hermético sem vigilância é sempre inofensivo","Basta aumentar sedativo","Oclusão não ventilada pode favorecer tensão; usar vedação apropriada e tratar pneumotórax conforme clínica"],"answer":3,"explanation":"Pneumotórax aberto exige vedação que considere escape de ar e vigilância para tensão.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Pneumotórax aberto","difficulty":"avançada"},{"id":"C5-TOR-006","topic":"Trauma torácico","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 40 anos sofre impacto torácico, apresenta movimento paradoxal de segmento de costelas, FR 33, SpO₂ 88% e muita dor. A PA estável; não há sinal de pneumotórax hipertensivo. Qual manejo inicial é mais apropriado?","options":["Fixação externa da parede em todos sem suporte respiratório","Intubação em todo caso independentemente do esforço","Analgesia eficaz, oxigenação, suporte ventilatório conforme necessidade e avaliação de contusão pulmonar","Alta após analgesia mínima"],"answer":2,"explanation":"Tórax instável exige controle da dor e suporte respiratório; contusão associada pode determinar gravidade.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Tórax instável","difficulty":"avançada","classic_intro":"Caso clássico de Trauma torácico: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-TOR-007","topic":"Trauma torácico","mode":"casos","style":"Caso clínico avançado","question":"Jovem de 27 anos após trauma em desaceleração está estável, com dor interescapular e mediastino alargado no RX. A equipe propõe drenagem pleural sem evidência de pneumotórax. Qual investigação direcionada é mais adequada?","options":["Drenagem torácica sem critério","Angiotomografia de aorta torácica para excluir lesão traumática de grande vaso","Apenas repetir RX após alta","Ecografia de vesícula"],"answer":1,"explanation":"Lesão aórtica pode cursar com estabilidade inicial; angio-TC é método de escolha na suspeita.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Aorta","difficulty":"avançada"},{"id":"C5-TOR-008","topic":"Trauma torácico","mode":"casos","style":"Caso clínico avançado","question":"Homem de 55 anos intubado após colisão apresenta redução súbita de SpO₂ e hipotensão minutos após iniciar ventilação com pressão positiva. Capnografia está presente e tubo bem posicionado; MV ausente à esquerda, hiperressonância local. Qual hipótese e ação são prioritárias?","options":["Pneumotórax hipertensivo precipitado/agravado pela pressão positiva; descompressão imediata","Retenção de CO₂ crônica como única causa","Tamponamento comprovado pela hiperressonância","Suspender ventilação e observar sem intervenção"],"answer":0,"explanation":"Pressão positiva pode agravar pneumotórax para tensão, com choque e falência ventilatória.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Pneumotórax em VM","difficulty":"avançada"},{"id":"C5-TOR-009","topic":"Trauma torácico","mode":"casos","style":"Caso clínico avançado","question":"Paciente de 38 anos com hemotórax traumático drenado inicialmente libera 350 mL, mas mantém perda de 260 mL/h nas quatro horas seguintes e requer transfusões repetidas. Qual interpretação evita falso conforto pelo débito inicial baixo?","options":["Somente o primeiro volume importa","Drenagem persistente é sempre esperada","A PA após bolus dispensa reavaliação","Perda contínua elevada e necessidade transfusional exigem discussão urgente de controle cirúrgico"],"answer":3,"explanation":"Debito continuado e fisiologia integram indicação cirúrgica, além do volume inicial.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Hemotórax persistente","difficulty":"avançada"},{"id":"C5-TOR-010","topic":"Trauma torácico","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 25 anos com trauma torácico por queda apresenta MV quase ausente à esquerda depois de IOT. Capnografia confirma tubo traqueal; RX mostra ponta avançada no brônquio principal direito, sem pneumotórax e com hipoventilação esquerda. Qual hipótese deve ser avaliada antes de punção pleural?","options":["Pneumotórax hipertensivo clínico já confirmado","Ruptura de aorta obrigatória","Posicionamento inadequado do tubo, incluindo intubação seletiva","Contusão renal"],"answer":2,"explanation":"Assimetria ventilatória após IOT exige primeiro conferir posição do tubo e hipóteses pleurais.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Posicionamento IOT","difficulty":"avançada"},{"id":"C5-TOR-011","topic":"Trauma torácico","mode":"casos","style":"Caso clínico avançado","question":"Homem de 29 anos é trazido após acidente com ferimento perfurante no tórax. Está normotenso, alerta e com ar subcutâneo no pescoço; após drenagem de pneumotórax, continua fuga aérea abundante e dificuldade de expansão pulmonar. Qual lesão é especialmente suspeita?","options":["Fratura nasal isolada","Ruptura traqueobrônquica, com necessidade de avaliação especializada da via aérea","Hipoglicemia","DPOC não diagnosticada como única hipótese"],"answer":1,"explanation":"Fuga de ar persistente e enfisema subcutâneo podem sinalizar lesão de via aérea central.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Traqueobrônquica","difficulty":"avançada"},{"id":"C5-TOR-012","topic":"Trauma torácico","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 62 anos com trauma torácico apresenta duas costelas fraturadas, atelectasia basal e tosse ineficaz pela dor. Usa analgésico leve, mas mantém respiração superficial; não há choque. Qual intervenção previne piora infecciosa/ventilatória?","options":["Otimizar analgesia e mobilização/fisioterapia respiratória conforme avaliação","Restringir tosse e ventilação","Prescrever antibiótico profilático obrigatório para toda fratura","Imobilizar tórax com faixas muito apertadas"],"answer":0,"explanation":"Analgesia e cuidados pulmonares evitam hipoventilação e complicações por dor.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Fraturas costais","difficulty":"avançada"},{"id":"Q5-ABD-001","topic":"Trauma abdominal","mode":"decorar","style":"Raciocínio rápido","question":"Em trauma abdominal contuso de paciente estável, qual exame tem maior utilidade para avaliar lesões de órgãos sólidos e retroperitônio?","options":["FAST isolado como exame definitivo em todos","Tomografia computadorizada com contraste conforme indicação","Radiografia de punho","Colonoscopy no primeiro minuto"],"answer":1,"explanation":"A TC permite caracterizar lesões quando o paciente está hemodinamicamente estável.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"TC","difficulty":"difícil"},{"id":"Q5-ABD-002","topic":"Trauma abdominal","mode":"decorar","style":"Aplicação clínica","question":"Qual aspecto do FAST deve ser lembrado ao explicar um resultado negativo?","options":["Não exclui todas as lesões, sobretudo de vísceras ocas ou retroperitônio","Garante ausência de qualquer lesão intestinal","Descarta sangramento retroperitoneal por completo","Impede reavaliação posterior"],"answer":0,"explanation":"FAST é exame de rastreamento de líquido livre com limitações.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"FAST","difficulty":"média"},{"id":"Q5-ABD-003","topic":"Trauma abdominal","mode":"decorar","style":"Pegadinha","question":"Uma vítima de colisão tem choque e FAST positivo para líquido livre. Qual prioridade é mais adequada?","options":["Encaminhar para TC demorada sem estabilização","Dar alta com retorno eletivo","Prescrever antiácido","Ressuscitar e providenciar controle definitivo da provável hemorragia"],"answer":3,"explanation":"Instabilidade com líquido livre sugere sangramento abdominal importante.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Decisão cirúrgica","difficulty":"média"},{"id":"Q5-ABD-004","topic":"Trauma abdominal","mode":"decorar","style":"Comparação","question":"Qual estrutura pode sangrar intensamente após trauma abdominal fechado com dor no hipocôndrio esquerdo?","options":["Tireoide","Apêndice obrigatório","Baço","Bexiga isolada"],"answer":2,"explanation":"Baço é órgão frequentemente lesado em trauma contuso.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Órgãos","difficulty":"difícil"},{"id":"Q5-ABD-005","topic":"Trauma abdominal","mode":"decorar","style":"Tratamento","question":"Após impacto no quadrante superior direito, dor local e queda de Hb, qual órgão sólido merece avaliação?","options":["Pâncreas exclusivamente","Fígado","Tireoide","Rim esquerdo necessariamente"],"answer":1,"explanation":"Fígado é alvo frequente em lesões do quadrante superior direito.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Órgãos","difficulty":"média"},{"id":"Q5-ABD-006","topic":"Trauma abdominal","mode":"decorar","style":"Avaliação crítica","question":"Uma marca transversa de cinto no abdome após colisão deve levar a considerar:","options":["Lesão intestinal e mesentérica potencialmente oculta","Apenas queimadura solar","Ausência de risco devido à proteção","Pneumonia bacteriana"],"answer":0,"explanation":"Sinal do cinto está associado a maior risco de lesões de víscera oca/mesentério.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Sinal do cinto","difficulty":"média"},{"id":"Q5-ABD-007","topic":"Trauma abdominal","mode":"decorar","style":"Cálculo e valores","question":"Paciente com dor abdominal difusa, rigidez e descompressão dolorosa após facada. Qual interpretação é adequada?","options":["Somente cólica intestinal funcional","Ausência de indicação de avaliação cirúrgica","Contusão muscular superficial comprovada","Sinais de peritonite e possível lesão de víscera oca"],"answer":3,"explanation":"Irritação peritoneal após trauma penetrante é sinal de gravidade.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Peritonite","difficulty":"difícil"},{"id":"Q5-ABD-008","topic":"Trauma abdominal","mode":"decorar","style":"Diferenciais","question":"Após queda de bicicleta sobre guidão epigástrico, qual órgão retroperitoneal exige atenção apesar de FAST negativo?","options":["Baço sempre","Pulmão","Pâncreas","Cérebro"],"answer":2,"explanation":"Impacto focal pode lesar pâncreas ou duodeno sem líquido livre inicial.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Retroperitônio","difficulty":"média"},{"id":"Q5-ABD-009","topic":"Trauma abdominal","mode":"decorar","style":"Raciocínio rápido","question":"Hematúria visível após impacto de flanco e estabilidade hemodinâmica orienta investigação de:","options":["Lesão do sistema nervoso central","Lesão renal ou do trato urinário","DPOC","Pneumonia"],"answer":1,"explanation":"Hematúria pós-trauma pode indicar lesão urológica relevante.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Urológico","difficulty":"média"},{"id":"Q5-ABD-010","topic":"Trauma abdominal","mode":"decorar","style":"Aplicação clínica","question":"Equimose periumbilical em paciente com sangramento intra-abdominal é chamada de:","options":["Sinal de Cullen","Sinal de Battle","Sinal de Grey Turner","Sinal de Murphy"],"answer":0,"explanation":"Cullen descreve equimose periumbilical, um sinal tardio de sangramento.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Semiologia","difficulty":"difícil"},{"id":"Q5-ABD-011","topic":"Trauma abdominal","mode":"decorar","style":"Pegadinha","question":"Equimose nos flancos associada a sangramento retroperitoneal é:","options":["Sinal de Cullen","Sinal de Jobert","Sinal de Battle","Sinal de Grey Turner"],"answer":3,"explanation":"Grey Turner refere-se a equimose de flancos.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Semiologia","difficulty":"média"},{"id":"Q5-ABD-012","topic":"Trauma abdominal","mode":"decorar","style":"Comparação","question":"No exame abdominal, desaparecimento da macicez hepática à percussão pode indicar:","options":["Hemotórax","Hematoma epidural","Pneumoperitônio (sinal de Jobert)","Asma"],"answer":2,"explanation":"Ar livre pode substituir o som maciço habitual do fígado.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Semiologia","difficulty":"média"},{"id":"Q5-ABD-013","topic":"Trauma abdominal","mode":"decorar","style":"Tratamento","question":"Dor referida para ombro esquerdo após impacto esplênico sugere:","options":["Fratura de clavícula obrigatória","Irritação diafragmática (sinal de Kehr)","Pneumonia isolada","Infarto sem trauma"],"answer":1,"explanation":"Sangue subdiafragmático pode irritar nervo frênico e causar dor referida.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Sinal de Kehr","difficulty":"difícil"},{"id":"Q5-ABD-014","topic":"Trauma abdominal","mode":"decorar","style":"Avaliação crítica","question":"Trauma fechado com suspeita de lesão duodenal deve ser lembrado principalmente por sua localização:","options":["Retroperitoneal parcial, dificultando avaliação pelo FAST","Somente intratorácica","Exclusivamente superficial","Sempre visível à inspeção"],"answer":0,"explanation":"Parte do duodeno é retroperitoneal e pode apresentar sinais sutis inicialmente.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Anatomia","difficulty":"média"},{"id":"Q5-ABD-015","topic":"Trauma abdominal","mode":"decorar","style":"Cálculo e valores","question":"Qual cenário favorece tratamento não operatório monitorizado de lesão esplênica?","options":["Choque persistente apesar de reanimação","Peritonite difusa progressiva","Instabilidade extrema sem recurso de vigilância","Paciente estável, sem peritonite, com estrutura de observação adequada"],"answer":3,"explanation":"Estabilidade e recursos de monitorização são essenciais ao tratamento não operatório.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Conduta","difficulty":"média"},{"id":"Q5-ABD-016","topic":"Trauma abdominal","mode":"decorar","style":"Diferenciais","question":"Na presença de trauma abdominal penetrante e choque refratário, qual decisão deve ser antecipada?","options":["Exame colonoscópico eletivo","Repetição ilimitada de FAST sem intervenção","Abordagem cirúrgica para controle de hemorragia","Alta com antibiótico oral"],"answer":2,"explanation":"A instabilidade hemodinâmica e peritonite podem indicar laparotomia urgente.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Cirurgia","difficulty":"difícil"},{"id":"Q5-ABD-017","topic":"Trauma abdominal","mode":"decorar","style":"Raciocínio rápido","question":"Qual limitação da concentração de hemoglobina inicial também vale para trauma abdominal?","options":["Exclui hemorragia na primeira amostra","Pode ser normal nas primeiras horas de sangramento importante","Prova ausência de lesão esplênica","Substitui FAST e TC"],"answer":1,"explanation":"Hemoglobina isolada no início não descarta sangramento.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Laboratório","difficulty":"média"},{"id":"Q5-ABD-018","topic":"Trauma abdominal","mode":"decorar","style":"Aplicação clínica","question":"Em trauma pélvico associado, uma fonte de sangramento oculta pode estar no:","options":["Retroperitônio e pelve","Canal auditivo apenas","Cavidade nasal como única fonte","Tecido adiposo do ombro"],"answer":0,"explanation":"Choque em trauma pélvico pode ter origem retroperitoneal mesmo com FAST negativo.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Pelve","difficulty":"média"},{"id":"Q5-ABD-019","topic":"Trauma abdominal","mode":"decorar","style":"Pegadinha","question":"Qual fator justifica repetir exame abdominal em vítima inicialmente estável após mecanismo de alta energia?","options":["Exame inicial exclui lesão futura","FAST negativo dispensa exame de dor","Ausência inicial de dor descarta lesão","Lesões intestinais e sangramentos podem manifestar sinais tardiamente"],"answer":3,"explanation":"Reavaliação clínica seriada é essencial no trauma abdominal.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Reavaliação","difficulty":"difícil"},{"id":"Q5-ABD-020","topic":"Trauma abdominal","mode":"decorar","style":"Comparação","question":"Que sinal físico isolado é pouco sensível para excluir lesão abdominal em paciente sedado e intubado?","options":["Sinais de choque","Perda sanguínea visível","Ausência de defesa voluntária","TC com lesão franca"],"answer":2,"explanation":"Exame físico perde confiabilidade quando consciência e dor estão alteradas.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Paciente não avaliável","difficulty":"média"},{"id":"Q5-ABD-021","topic":"Trauma abdominal","mode":"decorar","style":"Tratamento","question":"Uma TC mostra hematoma esplênico em paciente estável sem extravasamento ativo. Qual raciocínio é adequado?","options":["Laparotomia obrigatória em toda lesão esplênica","Avaliar tratamento não operatório em centro com vigilância apropriada","Descartar observação porque toda lesão sangra sem parar","Suspender monitorização"],"answer":1,"explanation":"Muitos casos estáveis podem receber tratamento conservador com reavaliação.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Baço","difficulty":"média"},{"id":"Q5-ABD-022","topic":"Trauma abdominal","mode":"decorar","style":"Avaliação crítica","question":"Como interpretar extravasamento ativo de contraste em órgão abdominal lesionado na TC?","options":["Sugere sangramento em atividade e pode alterar necessidade de intervenção","Confirma hemostasia definitiva","É achado exclusivamente infeccioso","Impede avaliação de estabilidade"],"answer":0,"explanation":"Sinal de sangramento ativo pode justificar angioembolização ou cirurgia conforme contexto.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Radiologia","difficulty":"difícil"},{"id":"Q5-ABD-023","topic":"Trauma abdominal","mode":"decorar","style":"Cálculo e valores","question":"Uma fratura de arcos costais inferiores à esquerda após impacto toracoabdominal deve despertar atenção também a:","options":["Fratura nasal","Lesão tireoidiana","Osteomielite espontânea","Lesão esplênica"],"answer":3,"explanation":"Impacto em costelas inferiores pode associar-se a trauma do órgão subjacente.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Mecanismo","difficulty":"média"},{"id":"Q5-ABD-024","topic":"Trauma abdominal","mode":"decorar","style":"Diferenciais","question":"Quando trauma penetrante abdominal produz evisceração com sinais de choque, qual atitude inicial é correta?","options":["Recolocar vísceras manualmente sem condições estéreis","Prescrever apenas analgésico e alta","Estabilização, proteção das vísceras e avaliação cirúrgica imediata","Aguardar exames eletivos"],"answer":2,"explanation":"Evisceração é sinal de gravidade; proteger tecido exposto e acionar cirurgia.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Urgência","difficulty":"média"},{"id":"Q5-ABD-025","topic":"Trauma abdominal","mode":"decorar","style":"Raciocínio rápido","question":"Na suspeita de lesão diafragmática traumática, qual achado pode surgir em exames torácicos?","options":["Apenas aumento de silhueta cardíaca","Vísceras abdominais deslocadas para tórax","Pneumoperitônio obrigatório","Lesão de osso frontal"],"answer":1,"explanation":"Ruptura diafragmática pode causar herniação visceral torácica.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Diafragma","difficulty":"difícil"},{"id":"Q5-ABD-026","topic":"Trauma abdominal","mode":"decorar","style":"Aplicação clínica","question":"Qual fator aumenta suspeita de lesão de víscera oca apesar de TC inicial inconclusiva?","options":["Dor progressiva, peritonismo e leucocitose em evolução","Dor completamente resolvida e exame normal","Ausência de trauma abdominal","Exame externo normal como único dado"],"answer":0,"explanation":"Evolução clínica pode revelar perfuração ou lesão mesentérica.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Víscera oca","difficulty":"média"},{"id":"Q5-ABD-027","topic":"Trauma abdominal","mode":"decorar","style":"Pegadinha","question":"Em criança após trauma abdominal fechado, o mecanismo pode ser preocupante mesmo com poucos achados iniciais porque:","options":["A parede abdominal infantil impede toda lesão","Dor inicial ausente exclui trauma","FAST substitui avaliação clínica","Lesões internas podem ser relevantes com alterações externas discretas"],"answer":3,"explanation":"Mecanismo e exame seriado são importantes em pediatria.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Pediatria","difficulty":"média"},{"id":"Q5-ABD-028","topic":"Trauma abdominal","mode":"decorar","style":"Comparação","question":"Após acidente, paciente com abdome distendido, choque e FAST duvidoso não deve ter a conduta determinada exclusivamente por:","options":["Estado hemodinâmico","Exame físico seriado","Um exame isolado sem integrar estabilidade e reavaliação","Mecanismo e resposta à reanimação"],"answer":2,"explanation":"A decisão integra fisiologia e evolução, não só FAST.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Tomada de decisão","difficulty":"difícil"},{"id":"Q5-ABD-029","topic":"Trauma abdominal","mode":"decorar","style":"Tratamento","question":"Em vítima de trauma estável com contusão abdominal, qual achado contraindica ignorar o caso por ausência de dor intensa?","options":["Exame de pele totalmente limpo e sem mecanismo","Marca de cinto e mecanismo de desaceleração relevante","Sinais vitais continuamente normais por observação adequada","Nenhuma história de trauma"],"answer":1,"explanation":"O sinal do cinto exige suspeita de lesão interna, mesmo com poucos sintomas iniciais.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Sinal do cinto","difficulty":"média"},{"id":"Q5-ABD-030","topic":"Trauma abdominal","mode":"decorar","style":"Avaliação crítica","question":"Qual exame complementar ganha prioridade em paciente estável e cooperativo após trauma penetrante selecionado, quando indicado?","options":["Imagem abdominal contrastada e avaliação especializada conforme trajetória","Teste ergométrico","Radiografia de coluna lombar isolada","Densitometria"],"answer":0,"explanation":"A trajetória e estabilidade definem a investigação seletiva do trauma penetrante.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Investigação","difficulty":"média"},{"id":"Q5-ABD-031","topic":"Trauma abdominal","mode":"decorar","style":"Cálculo e valores","question":"Por que a angioembolização pode ser opção em órgão sólido com extravasamento e estabilidade?","options":["Substitui cirurgia em qualquer choque profundo","Não requer imagem","É usada apenas para infecções","Permite controle vascular seletivo em paciente apropriado"],"answer":3,"explanation":"Paciente estável com lesão vascular localizada pode ser elegível a intervenção radiológica.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Intervenção","difficulty":"difícil"},{"id":"Q5-ABD-032","topic":"Trauma abdominal","mode":"decorar","style":"Diferenciais","question":"Um paciente com trauma abdominal tem defesa involuntária e rigidez. Qual estrutura pode estar irritada?","options":["Tireoide","Nervo facial","Peritônio","Artéria radial"],"answer":2,"explanation":"Irritação peritoneal indica possível lesão intra-abdominal importante.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Semiologia","difficulty":"média"},{"id":"Q5-ABD-033","topic":"Trauma abdominal","mode":"decorar","style":"Raciocínio rápido","question":"Qual achado faz suspeitar de lesão do mesentério numa colisão com cinto?","options":["Dor de garganta após tosse","Dor progressiva e hematoma em alça/estrias mesentéricas na TC","Otite","Sibilância isolada"],"answer":1,"explanation":"Mecanismo com compressão e desaceleração pode lesar vasos e intestino.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Mesentério","difficulty":"média"},{"id":"Q5-ABD-034","topic":"Trauma abdominal","mode":"decorar","style":"Aplicação clínica","question":"Na hipotensão com FAST positivo, qual órgão adicional não pode ser esquecido além dos sólidos?","options":["Possível lesão vascular ou mesentérica com hemorragia","Somente pele","Tireoide","Olho"],"answer":0,"explanation":"Fontes de sangramento abdominal podem ser de vasos e mesentério, não apenas baço/fígado.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Foco hemorrágico","difficulty":"difícil"},{"id":"Q5-ABD-035","topic":"Trauma abdominal","mode":"decorar","style":"Pegadinha","question":"Qual dado objetivo orienta segurança de observação não operatória de baço?","options":["Apenas uma ausculta abdominal","Ausência de dor após uma dose de analgésico","Idade abaixo de 40","Monitorização seriada de sinais vitais, exame e hemoglobina conforme caso"],"answer":3,"explanation":"Tratamento não operatório exige condições de detecção de deterioração.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Monitorização","difficulty":"média"},{"id":"Q5-ABD-036","topic":"Trauma abdominal","mode":"decorar","style":"Comparação","question":"O que pode tornar trauma duodenal especialmente difícil de identificar na primeira ultrassonografia?","options":["Obrigatoriedade de hemoperitônio maciço","Ausência de sintoma por décadas","Localização retroperitoneal e pouca quantidade de líquido livre","A lesão sempre causa icterícia"],"answer":2,"explanation":"Lesão retroperitoneal pode escapar a FAST e ter diagnóstico tardio.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Duodeno","difficulty":"média"},{"id":"Q5-ABD-037","topic":"Trauma abdominal","mode":"decorar","style":"Tratamento","question":"Em paciente com dor de ombro esquerdo, quais achados reforçam origem diafragmática após trauma?","options":["Dor cervical isolada","Trauma no hipocôndrio esquerdo e líquido periesplênico","Fratura de úmero sem trauma abdominal","Otite externa"],"answer":1,"explanation":"Sinal de Kehr aparece por irritação diafragmática secundária a sangramento esplênico.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Kehr","difficulty":"difícil"},{"id":"Q5-ABD-038","topic":"Trauma abdominal","mode":"decorar","style":"Avaliação crítica","question":"Qual condição faz suspeitar de necessidade de laparotomia sem esperar novo exame de imagem?","options":["Trauma penetrante com peritonite e instabilidade","Paciente estável sem dor e TC normal","Contusão superficial sem sinais sistêmicos","Ferida cutânea pequena sem trajeto profundo"],"answer":0,"explanation":"Peritonite e choque após trauma penetrante são sinais de gravidade cirúrgica.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Urgência","difficulty":"média"},{"id":"C5-ABD-001","topic":"Trauma abdominal","mode":"casos","style":"Caso clínico avançado","question":"Homem de 30 anos é levado após colisão de alta velocidade. PA 80/45, FC 137, abdome distendido, FAST mostra líquido no espaço hepatorrenal. Recebe sangue aquecido e estabilização inicial parcial; cirurgião quer TC antes de decidir. Qual plano respeita a instabilidade?","options":["Realizar TC independentemente da resposta a volume","Descartar hemorragia por ausência de hematêmese","Prosseguir reanimação e controle cirúrgico do sangramento sem atrasar por TC demorada","Aguardar hemoglobina diminuir"],"answer":2,"explanation":"Choque com FAST positivo exige priorizar controle definitivo de hemorragia.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"FAST positivo instável","difficulty":"avançada","classic_intro":"Caso clássico de Trauma abdominal: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-ABD-002","topic":"Trauma abdominal","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 27 anos atropelada apresenta marca de cinto, dor moderada e FAST negativo, mas mantém PA 118/72. TC inicial identifica discreto espessamento mesentérico, sem grande hemoperitônio. Após 6 horas, tem febre, dor crescente e defesa. Qual hipótese deve orientar reavaliação?","options":["Trauma abdominal definitivamente excluído pelo FAST","Lesão intestinal/mesentérica com possível perfuração evolutiva","Gastrite como único diagnóstico certo","Ausência de necessidade cirúrgica porque TC inicial foi discreta"],"answer":1,"explanation":"Lesões de víscera oca podem ser sutis inicialmente e evoluir com peritonite.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Víscera oca","difficulty":"avançada","classic_intro":"Caso clássico de Trauma abdominal: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-ABD-003","topic":"Trauma abdominal","mode":"casos","style":"Caso clínico avançado","question":"Rapaz de 17 anos sofre impacto de guidão no epigástrio. Está estável, mas tem dor persistente, vômitos e amilase que aumenta horas depois. FAST é negativo e US não detalha retroperitônio. Qual próximo raciocínio é adequado?","options":["Investigar lesão pancreatoduodenal por método de imagem apropriado e avaliação especializada","Descartar lesão porque FAST foi negativo","Atribuir amilase exclusivamente à alimentação","Dar alta sem seguimento porque não há equimose"],"answer":0,"explanation":"Trauma epigástrico focal pode lesar pâncreas e duodeno, órgãos em parte retroperitoneais.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Pancreatoduodenal","difficulty":"avançada","classic_intro":"Caso clássico de Trauma abdominal: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-ABD-004","topic":"Trauma abdominal","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 44 anos tem trauma esplênico contuso após queda. Está alerta, PA 124/76, sem peritonismo; TC mostra laceração esplênica moderada, sem sangramento ativo. Hospital dispõe de equipe cirúrgica e monitorização. Qual conduta pode ser apropriada?","options":["Laparotomia mandatória em toda lesão de baço","Alta imediata por PA normal","Proibição de controle laboratorial","Tratamento não operatório vigiado com reavaliação e prontidão para intervenção"],"answer":3,"explanation":"Em pacientes estáveis, lesão de órgão sólido pode ser manejada de forma não operatória em centro preparado.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Baço estável","difficulty":"avançada"},{"id":"C5-ABD-005","topic":"Trauma abdominal","mode":"casos","style":"Caso clínico avançado","question":"Homem de 65 anos, após impacto no flanco esquerdo, apresenta hematúria macroscópica, FC 110 e PA 116/70. Sem defesa abdominal; FAST negativo. Qual exame complementar é mais adequado à suspeita de trauma renal num paciente estável?","options":["Apenas repetição do FAST como diagnóstico renal definitivo","Cintilografia tireoidiana","TC com contraste e protocolo apropriado conforme avaliação","Colonoscopia imediata"],"answer":2,"explanation":"FAST pode não detectar lesão renal retroperitoneal; TC contrastada caracteriza a lesão se estável.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Trauma renal","difficulty":"avançada"},{"id":"C5-ABD-006","topic":"Trauma abdominal","mode":"casos","style":"Caso clínico avançado","question":"Homem de 38 anos sofre facada abdominal com evisceração, dor intensa, PA 85/50 e rigidez generalizada. O serviço pede tempo para preparar um exame eletivo de imagem. Qual prioridade é mais adequada?","options":["Reintroduzir vísceras manualmente","Proteger as vísceras expostas, reanimar e obter avaliação cirúrgica imediata","Administrar apenas antiácido e analgésico","Aguardar 24 horas por redução do edema"],"answer":1,"explanation":"Evisceração com peritonite e instabilidade é emergência cirúrgica.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Trauma penetrante","difficulty":"avançada","classic_intro":"Caso clássico de Trauma abdominal: interprete o conjunto de sinais e exames antes de decidir."},{"id":"C5-ABD-007","topic":"Trauma abdominal","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 51 anos após colisão apresenta trauma em costelas inferiores esquerdas, hipotensão discreta e dor referida ao ombro esquerdo. FAST mostra líquido periesplênico. Qual associação anatômica ajuda no raciocínio?","options":["Lesão esplênica com irritação diafragmática causando sinal de Kehr","Lesão hepática direita exclusiva","Fratura de crânio com sinal de Battle","Obstrução brônquica unilateral"],"answer":0,"explanation":"Sinal de Kehr é dor referida ao ombro pela irritação diafragmática, comum em lesão esplênica.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Kehr","difficulty":"avançada"},{"id":"C5-ABD-008","topic":"Trauma abdominal","mode":"casos","style":"Caso clínico avançado","question":"Homem de 58 anos apresenta fratura instável de bacia, choque persistente e FAST negativo, sem sangramento externo significativo. Equipe concentra toda investigação no abdome intraperitoneal. Qual fonte e tratamento precoce devem ser considerados?","options":["Ausência de sangramento por FAST negativo","Somente trauma cerebral","Descompressão torácica sem achados","Hemorragia pélvica/retroperitoneal com estabilizador pélvico e protocolo hemostático"],"answer":3,"explanation":"Sangramento pélvico pode ser retroperitoneal e não aparecer no FAST.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Pelve","difficulty":"avançada"},{"id":"C5-ABD-009","topic":"Trauma abdominal","mode":"casos","style":"Caso clínico avançado","question":"Jovem de 20 anos sofre trauma fechado e tem PA 120/78, Glasgow 15 e dor abdominal leve. Exame mostra equimose linear por cinto e sensibilidade à palpação profunda. A família deseja alta imediata. Qual decisão clínica é mais apropriada?","options":["Concluir que a marca do cinto é inofensiva","Descartar lesão pelo Glasgow 15","Observar/investigar com atenção para lesão de víscera oca, conforme exame, mecanismo e recursos","Não reavaliar se dor piorar"],"answer":2,"explanation":"Mecanismo de desaceleração e sinal do cinto aumentam risco de lesão mesentérica/intestinal.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Sinal do cinto","difficulty":"avançada"},{"id":"C5-ABD-010","topic":"Trauma abdominal","mode":"casos","style":"Caso clínico avançado","question":"Homem de 49 anos apresenta ferimento penetrante em flanco posterior, está estável mas relata dor lombar e hematúria microscópica. FAST é negativo. Qual limitação do ultrassom é relevante para a decisão?","options":["FAST negativo exclui rim e ureter","Lesões retroperitoneais e urinárias podem escapar ao FAST e exigir imagem dirigida","Hematúria prova lesão exclusiva de bexiga","Todo trauma penetrante precisa de laparotomia imediata"],"answer":1,"explanation":"Avaliação depende de trajetória e lesões retroperitoneais, nem sempre evidenciadas pelo FAST.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Retroperitônio","difficulty":"avançada"},{"id":"C5-ABD-011","topic":"Trauma abdominal","mode":"casos","style":"Caso clínico avançado","question":"Mulher de 36 anos, politraumatizada, apresenta trauma abdominal contuso e dor em hipocôndrio direito. TC com contraste mostra lesão hepática com extravasamento ativo, mas a paciente permanece estável após reanimação. Qual opção terapêutica pode ser considerada por equipe especializada?","options":["Angioembolização seletiva conforme estabilidade e recursos","Alta imediata porque PA normal","Descartar sangramento pela ausência de peritonismo","Antibiótico isolado como hemostasia"],"answer":0,"explanation":"Extravasamento ativo em paciente estável pode ser manejado com radiologia intervencionista conforme caso.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Fígado","difficulty":"avançada"},{"id":"C5-ABD-012","topic":"Trauma abdominal","mode":"casos","style":"Caso clínico avançado","question":"Homem de 55 anos recebe alta após contusão abdominal leve e retorna 18 horas depois com febre, dor abdominal progressiva, rigidez e descompressão dolorosa. O FAST inicial havia sido negativo. O que o retorno demonstra?","options":["FAST negativo descarta perfuração por 48 horas","Peritonismo tardio é sempre gastrite","Somente trauma renal causa defesa abdominal","Lesão intestinal oculta pode evoluir e exigir intervenção mesmo com FAST negativo prévio"],"answer":3,"explanation":"Peritonite tardia após trauma exige reavaliação cirúrgica urgente.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Peritonite tardia","difficulty":"avançada"},{"id":"I5-ASM-001","topic":"Asma","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Em crise asmática grave, PaCO₂ evolui de 29 para 52 mmHg. Quantos mmHg foi o aumento absoluto?","explanation":"52 − 29 = 23 mmHg; elevação com exaustão sugere deterioração da ventilação.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Recordação ativa","accepted":["23"]},{"id":"I5-ASM-002","topic":"Asma","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Na crise asmática, qual é a duração mínima usual, em dias, do curso de prednisolona oral em adultos? Responda apenas número.","explanation":"Na GINA, o curso oral para adultos costuma durar 5–7 dias.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Recordação ativa","accepted":["5"]},{"id":"I5-ASM-003","topic":"Asma","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Se um adulto precisa de 2 g de magnésio IV, quantos miligramas são?","explanation":"2 g equivalem a 2.000 mg.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Recordação ativa","accepted":["2000"]},{"id":"I5-ASM-004","topic":"Asma","mode":"decorar","style":"Ordene as etapas","kind":"order","question":"Organize a sequência segura da alta após atendimento de crise asmática que melhorou.","explanation":"Alta segura inclui estabilidade, controle e prevenção de nova exacerbação.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Recordação ativa","steps":["Confirmar melhora clínica sustentada","Revisar tratamento controlador com corticoide inalatório","Conferir técnica de inaladores","Entregar plano de ação e sinais de alarme","Organizar seguimento precoce"]},{"id":"I5-ASM-005","topic":"Asma","mode":"decorar","style":"Ligue os pares","kind":"match","question":"Relacione padrão clínico a interpretação respiratória.","explanation":"Os achados respiratórios precisam ser interpretados com fluxo, consciência e evolução.","source":"Apostila Urgências e Emergências (tema Asma); GINA 2026","keypoint":"Recordação ativa","pairs":[["Estridor inspiratório","Via aérea superior"],["Sibilância expiratória difusa","Obstrução brônquica"],["Silêncio auscultatório com sonolência","Ventilação criticamente comprometida"],["Hipocapnia inicial em crise importante","Hiperventilação compensatória"]]},{"id":"I5-DPO-001","topic":"DPOC","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Paciente com DPOC tem pH 7,29 e PaCO₂ 64 mmHg. Qual distúrbio ácido-base primário está presente? Escreva duas palavras.","explanation":"pH reduzido associado a PaCO₂ elevada define acidose respiratória.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Recordação ativa","accepted":["acidose respiratória","acidose respiratoria"]},{"id":"I5-DPO-002","topic":"DPOC","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Um paciente com VEF₁ de 35% do previsto é GOLD qual estágio numérico?","explanation":"GOLD 3 corresponde a VEF₁ previsto entre 30 e 49%.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Recordação ativa","accepted":["3"]},{"id":"I5-DPO-003","topic":"DPOC","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Na DPOC exacerbada, qual é o limite superior habitual da meta de SpO₂ em porcentagem?","explanation":"O teto inicial habitual é 92%, com titulação e gasometria quando indicada.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Recordação ativa","accepted":["92"]},{"id":"I5-DPO-004","topic":"DPOC","mode":"decorar","style":"Ordene as etapas","kind":"order","question":"Ordene a conduta após falha progressiva de VNI em DPOC.","explanation":"Falha de VNI pede reavaliação e eventual ventilação invasiva sem atraso.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Recordação ativa","steps":["Reconhecer deterioração de consciência e gasometria","Checar interface, vazamentos e causas reversíveis sem atrasar cuidado","Acionar equipe experiente em via aérea","Preparar intubação conforme indicação","Acompanhar ventilação e hemodinâmica após estabilização"]},{"id":"I5-DPO-005","topic":"DPOC","mode":"decorar","style":"Ligue os pares","kind":"match","question":"Associe perfis de DPOC aos conceitos corretos.","explanation":"A gravidade espirométrica é classificada pelo VEF₁ percentual do previsto.","source":"Apostila Urgências e Emergências (tema DPOC); GOLD 2027","keypoint":"Recordação ativa","pairs":[["VEF₁ pós-BD 85% do previsto","GOLD 1"],["VEF₁ pós-BD 55% do previsto","GOLD 2"],["VEF₁ pós-BD 35% do previsto","GOLD 3"],["VEF₁ pós-BD 25% do previsto","GOLD 4"]]},{"id":"I5-SEP-001","topic":"Sepse","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Uma infecção gera aumento agudo de SOFA em quantos pontos para atender ao critério operacional de sepse?","explanation":"Sepse-3 considera aumento de SOFA ≥2 atribuível à infecção.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Recordação ativa","accepted":["2"]},{"id":"I5-SEP-002","topic":"Sepse","mode":"decorar","style":"Resposta livre","kind":"fill","question":"No choque séptico, o antibiótico deve ser iniciado idealmente em até quantos minutos?","explanation":"Uma hora equivale a 60 minutos após reconhecimento de choque ou sepse provável/definida.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Recordação ativa","accepted":["60"]},{"id":"I5-SEP-003","topic":"Sepse","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Qual é a PAM inicial-alvo usual em choque séptico, expressa em mmHg?","explanation":"PAM inicial de aproximadamente 65 mmHg, individualizada.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Recordação ativa","accepted":["65"]},{"id":"I5-SEP-004","topic":"Sepse","mode":"decorar","style":"Ordene as etapas","kind":"order","question":"Organize os passos da reavaliação após início de noradrenalina na sepse.","explanation":"A reanimação é guiada por perfusão e foco, não apenas pelo número da pressão.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Recordação ativa","steps":["Verificar PAM e perfusão periférica","Reavaliar responsividade a fluidos e sinais de sobrecarga","Repetir lactato conforme gravidade","Conferir diurese e disfunção orgânica","Reexaminar necessidade de controle de foco"]},{"id":"I5-SEP-005","topic":"Sepse","mode":"decorar","style":"Ligue os pares","kind":"match","question":"Relacione situação com conduta.","explanation":"Momento e tipo de intervenção dependem da gravidade e da certeza clínica.","source":"Apostila Urgências e Emergências (tema Sepse); SSC 2026","keypoint":"Recordação ativa","pairs":[["Choque séptico reconhecido","Antimicrobiano imediato"],["Sepse possível sem choque","Investigação rápida e antibiótico em até 3 h se suspeita persistir"],["Coleção abdominal drenável","Controle precoce do foco"],["Hipoperfusão após volume apropriado","Considerar vasopressor conforme necessidade"]]},{"id":"I5-QUE-001","topic":"Queimaduras","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Na regra dos nove do adulto, quanto vale o períneo em porcentagem?","explanation":"O períneo corresponde a aproximadamente 1% na regra dos nove.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Recordação ativa","accepted":["1"]},{"id":"I5-QUE-002","topic":"Queimaduras","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Adulto de 70 kg com queimadura de 20% SCQ: pela fórmula ABA de 2 mL/kg/%SCQ, quantos mL são estimados em 24 horas?","explanation":"2 × 70 × 20 = 2.800 mL como estimativa inicial.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Recordação ativa","accepted":["2800"]},{"id":"I5-QUE-003","topic":"Queimaduras","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Uma queimadura ocupa apenas face posterior de um braço adulto. Quantos pontos percentuais são?","explanation":"Metade do braço corresponde a 4,5% pela regra dos nove.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Recordação ativa","accepted":["4.5"]},{"id":"I5-QUE-004","topic":"Queimaduras","mode":"decorar","style":"Ordene as etapas","kind":"order","question":"Ponha em ordem os primeiros cuidados de escaldadura sem instabilidade.","explanation":"Os primeiros socorros priorizam interromper dano e proteger a área, sem gelo direto.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Recordação ativa","steps":["Interromper exposição à fonte térmica","Remover adornos/roupa não aderida quando seguro","Resfriar com água corrente fresca evitando hipotermia","Cobrir de modo limpo e avaliar profundidade/área","Decidir analgesia, curativo e encaminhamento"]},{"id":"I5-QUE-005","topic":"Queimaduras","mode":"decorar","style":"Ligue os pares","kind":"match","question":"Relacione aparência da queimadura à profundidade.","explanation":"A profundidade resulta da combinação de cor, umidade, dor e perfusão.","source":"Apostila Urgências e Emergências (tema Queimaduras); ABA 2024","keypoint":"Recordação ativa","pairs":[["Eritema sem bolhas","Superficial epidérmica"],["Bolhas e pele úmida rósea","Espessura parcial superficial"],["Pele pálida com pouca perfusão","Espessura parcial profunda"],["Placa rígida insensível","Espessura total"]]},{"id":"I5-POL-001","topic":"Politraumatismo","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Uma vítima de trauma recebeu TXA três horas e meia após acidente. Quantos minutos se passaram?","explanation":"3,5 horas equivalem a 210 minutos, acima da janela de até 3 h indicada em geral.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Recordação ativa","accepted":["210"]},{"id":"I5-POL-002","topic":"Politraumatismo","mode":"decorar","style":"Resposta livre","kind":"fill","question":"No protocolo de reanimação balanceada, a razão concentrado de hemácias:plasma:plaquetas é 1:1: quantas unidades proporcionais de plaquetas?","explanation":"A proporção clássica é 1:1:1.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Recordação ativa","accepted":["1"]},{"id":"I5-POL-003","topic":"Politraumatismo","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Qual letra do XABCDE representa a avaliação neurológica rápida?","explanation":"D corresponde a Disability, ou avaliação neurológica rápida.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Recordação ativa","accepted":["D","d"]},{"id":"I5-POL-004","topic":"Politraumatismo","mode":"decorar","style":"Ordene as etapas","kind":"order","question":"Sequencie reavaliações em politrauma após controlar hemorragia externa maciça.","explanation":"Após X, a avaliação primária segue A–B–C–D–E, tratando achados imediatamente.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Recordação ativa","steps":["Verificar via aérea com proteção cervical","Verificar ventilação e tratar ameaças torácicas","Avaliar choque e buscar sangramento oculto","Reavaliar Glasgow, pupilas e glicemia","Expor corpo e prevenir hipotermia"]},{"id":"I5-POL-005","topic":"Politraumatismo","mode":"decorar","style":"Ligue os pares","kind":"match","question":"Faça a correspondência entre a etapa do trauma e a ameaça.","explanation":"As etapas do XABCDE classificam prioridades vitais.","source":"Apostila Urgências e Emergências (tema Politraumatismo); ATLS 11ª ed.","keypoint":"Recordação ativa","pairs":[["X","Hemorragia exsanguinante"],["A","Obstrução de via aérea"],["B","Pneumotórax hipertensivo"],["C","Choque hemorrágico"]]},{"id":"I5-TCE-001","topic":"TCE","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Paciente com PAM 92 mmHg e PIC 27 mmHg. Qual PPC, em mmHg?","explanation":"PPC = 92 − 27 = 65 mmHg.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Recordação ativa","accepted":["65"]},{"id":"I5-TCE-002","topic":"TCE","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Um paciente tem Glasgow 10 e as duas pupilas não reagem. Qual o Glasgow-P?","explanation":"O Glasgow-P subtrai dois pontos quando ambas as pupilas são não reativas.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Recordação ativa","accepted":["8"]},{"id":"I5-TCE-003","topic":"TCE","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Paciente abre olhos à voz e localiza a dor. Quantos pontos recebe só pela abertura ocular?","explanation":"Abrir olhos à voz corresponde a E3.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Recordação ativa","accepted":["3"]},{"id":"I5-TCE-004","topic":"TCE","mode":"decorar","style":"Ordene as etapas","kind":"order","question":"Organize medidas da prevenção de lesão secundária no TCE grave durante estabilização.","explanation":"Evitar hipóxia/hipotensão antecede investigação complementar demorada.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Recordação ativa","steps":["Garantir via aérea e oxigenação","Corrigir hipotensão e buscar hemorragia concomitante","Realizar Glasgow e pupilas seriados","Solicitar TC após estabilizar condições vitais","Acionar neurocirurgia conforme risco e imagem"]},{"id":"I5-TCE-005","topic":"TCE","mode":"decorar","style":"Ligue os pares","kind":"match","question":"Associe os achados neurológicos a conceitos de TCE.","explanation":"Padrões morfológicos e de evolução ajudam diagnóstico rápido.","source":"Apostila Urgências e Emergências (tema TCE); ATLS 11ª ed.","keypoint":"Recordação ativa","pairs":[["Coleção biconvexa","Hematoma epidural"],["Coleção em crescente","Hematoma subdural"],["Midríase por compressão do III par","Herniação uncal"],["Coma profundo com TC discreta","Suspeita de lesão axonal difusa"]]},{"id":"I5-TOR-001","topic":"Trauma torácico","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Quanto sangue, em mL, é um valor clássico de alerta para hemotórax maciço na drenagem inicial em adulto?","explanation":"Saída inicial em torno de 1.500 mL integra critérios clássicos de discussão cirúrgica.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Recordação ativa","accepted":["1500"]},{"id":"I5-TOR-002","topic":"Trauma torácico","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Uma drenagem perde 240 mL/h por quatro horas. Qual a perda total nesse período em mL?","explanation":"240 × 4 = 960 mL, o que requer interpretar hemorragia contínua com fisiologia.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Recordação ativa","accepted":["960"]},{"id":"I5-TOR-003","topic":"Trauma torácico","mode":"decorar","style":"Resposta livre","kind":"fill","question":"No critério clássico de tórax instável, quantas costelas consecutivas, no mínimo, costumam estar fraturadas em pelo menos dois pontos?","explanation":"Em geral, considera-se três ou mais costelas adjacentes fraturadas em dois pontos, formando segmento instável.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Recordação ativa","accepted":["3"]},{"id":"I5-TOR-004","topic":"Trauma torácico","mode":"decorar","style":"Ordene as etapas","kind":"order","question":"Organize a sequência em pneumotórax hipertensivo com choque.","explanation":"A intervenção não deve esperar imagem; a drenagem definitiva e reavaliação seguem.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Recordação ativa","steps":["Reconhecer sinais clínicos de tensão","Iniciar suporte de oxigenação e preparar material","Realizar descompressão imediatamente","Providenciar drenagem pleural definitiva","Reavaliar ventilação e hemodinâmica"]},{"id":"I5-TOR-005","topic":"Trauma torácico","mode":"decorar","style":"Ligue os pares","kind":"match","question":"Associe lesão torácica a achado clínico.","explanation":"A interpretação depende da combinação de exame físico e fisiologia.","source":"Apostila Urgências e Emergências (tema Trauma torácico); ATLS 11ª ed.","keypoint":"Recordação ativa","pairs":[["Hemotórax maciço","Macicez e choque"],["Pneumotórax hipertensivo","Hipersonoridade e choque obstrutivo"],["Tamponamento traumático","Derrame pericárdico e limitação de enchimento"],["Tórax instável","Movimento paradoxal de parede"]]},{"id":"I5-ABD-001","topic":"Trauma abdominal","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Após trauma abdominal, há choque e FAST positivo. Qual sigla identifica o ultrassom focalizado da avaliação inicial?","explanation":"FAST significa avaliação ultrassonográfica focalizada para trauma.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Recordação ativa","accepted":["FAST","fast"]},{"id":"I5-ABD-002","topic":"Trauma abdominal","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Em paciente estável após trauma abdominal contuso, qual sigla identifica o exame de imagem que ajuda a estadiar lesão esplênica?","explanation":"A tomografia computadorizada contrastada pode caracterizar lesão esplênica em paciente estável.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Recordação ativa","accepted":["TC","tc"]},{"id":"I5-ABD-003","topic":"Trauma abdominal","mode":"decorar","style":"Resposta livre","kind":"fill","question":"Qual nome do sinal de desaparecimento da macicez hepática à percussão em pneumoperitônio?","explanation":"O sinal de Jobert pode ocorrer quando ar livre substitui a macicez hepática.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Recordação ativa","accepted":["Jobert","jobert"]},{"id":"I5-ABD-004","topic":"Trauma abdominal","mode":"decorar","style":"Ordene as etapas","kind":"order","question":"Em trauma abdominal fechado estável, organize a investigação inicial.","explanation":"Estabilidade orienta a possibilidade de imagem detalhada, com reavaliação seriada.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Recordação ativa","steps":["Realizar XABCDE e confirmar estabilidade","Examinar abdome e mecanismo de trauma","Usar FAST conforme indicação e reconhecer limitações","Solicitar TC contrastada se apropriada","Reavaliar clinicamente e decidir observação ou intervenção"]},{"id":"I5-ABD-005","topic":"Trauma abdominal","mode":"decorar","style":"Ligue os pares","kind":"match","question":"Associe achado a lesão ou interpretação abdominal.","explanation":"O mecanismo, a fisiologia e os sinais complementares direcionam a investigação.","source":"Apostila Urgências e Emergências (tema Trauma abdominal); ATLS 11ª ed.","keypoint":"Recordação ativa","pairs":[["Equimose de cinto","Risco de lesão intestinal/mesentérica"],["Trauma de guidão no epigástrio","Possível lesão pancreatoduodenal"],["Dor referida ao ombro esquerdo","Irritação diafragmática por baço"],["FAST positivo e choque","Prioridade de controle hemorrágico"]]}],"cards":[{"id":"F4-001","topic":"Asma","question":"Por que menos sibilo nem sempre significa melhora?","answer":"Fluxo aéreo crítico pode ser tão baixo que quase não produz som.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-002","topic":"Asma","question":"Que risco pode passar despercebido ao ver uma PaCO₂ normal numa crise intensa?","answer":"O paciente pode estar perdendo a capacidade de hiperventilar.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-003","topic":"Asma","question":"Que vantagem clínica o espaçador oferece a quem tem técnica inalatória ruim?","answer":"Melhora a entrega do medicamento sem exigir tanta coordenação.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-004","topic":"Asma","question":"Qual componente da doença o SABA não controla no longo prazo?","answer":"A inflamação crônica das vias aéreas.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-005","topic":"Asma","question":"O que torna uma exacerbação um aviso sobre o tratamento de manutenção?","answer":"Ela sugere risco futuro e exige revisão do controlador e da técnica.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-006","topic":"Asma","question":"Qual relação temporal diferencia broncoespasmo da fase inflamatória tardia?","answer":"Broncoespasmo é rápido; inflamação tardia pode manter sintomas horas depois.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-007","topic":"Asma","question":"Por que uma pessoa com asma pode melhorar após broncodilatador e recair?","answer":"A inflamação subjacente pode persistir mesmo após alívio do espasmo.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-008","topic":"Asma","question":"Que mudança da fala preocupa mais do que apenas contar sibilos?","answer":"Passar de frases para palavras isoladas.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-009","topic":"Asma","question":"Por que o uso excessivo do inalador de resgate merece investigação?","answer":"Pode indicar controle insuficiente e maior risco de exacerbação.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-010","topic":"Asma","question":"Que sinal sugere obstrução acima da traqueia intratorácica?","answer":"Estridor inspiratório predominante.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-011","topic":"Asma","question":"Quando o médico não deve esperar a imagem para começar terapia da crise?","answer":"Quando há desconforto respiratório ou hipoxemia relevantes.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-012","topic":"Asma","question":"Que erro há em usar sedação para tratar a agitação da asma grave?","answer":"Pode deprimir a ventilação e mascarar exaustão.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-013","topic":"Asma","question":"Qual aspecto não pode faltar no plano pós-alta?","answer":"Tratamento anti-inflamatório, técnica correta, plano de ação e retorno.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-014","topic":"Asma","question":"Para que o pico de fluxo é mais útil durante a observação?","answer":"Acompanhar objetivamente a resposta junto aos sinais clínicos.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-015","topic":"Asma","question":"Como uma infecção viral pode precipitar sintomas asmáticos?","answer":"Aumentando inflamação e hiperresponsividade brônquica.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-016","topic":"Asma","question":"O que indica o alívio rápido do SABA sobre o mecanismo obstrutivo?","answer":"Há componente broncoconstritor reversível.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-017","topic":"Asma","question":"Por que ipratrópio e SABA não são fármacos redundantes?","answer":"Atuam em vias receptoras distintas para broncodilatar.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-018","topic":"Asma","question":"Que achado de laboratório pode surgir após muitas doses de salbutamol?","answer":"Queda de potássio, além de taquicardia ou tremor.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-019","topic":"Asma","question":"Por que saturação normal não dispensa reavaliação da ventilação?","answer":"SpO₂ não mostra retenção de CO₂ nem fadiga muscular.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-020","topic":"Asma","question":"Como suspeitar que uma asma sintomática é, na verdade, outra emergência?","answer":"Procurar dor pleurítica focal, assimetria, congestão ou anafilaxia.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-021","topic":"Asma","question":"Qual é o objetivo de ajustar oxigênio, em vez de fornecê-lo ao máximo?","answer":"Corrigir hipoxemia evitando hiperóxia desnecessária.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-022","topic":"Asma","question":"O que pode indicar a necessidade de uma equipe experiente em via aérea?","answer":"Fadiga, consciência piorando e ventilação em falência.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-023","topic":"Asma","question":"Por que uma criança não recebe automaticamente a mesma dose de corticoide do adulto?","answer":"Dose pediátrica considera peso e limite máximo.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-024","topic":"Asma","question":"Que informação da anamnese ajuda a estratificar risco de nova crise?","answer":"História de exacerbação quase fatal ou internações recentes.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-025","topic":"Asma","question":"Qual é o papel do corticoide sistêmico durante uma exacerbação significativa?","answer":"Reduzir inflamação e risco de recaída, não broncodilatar em segundos.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-026","topic":"Asma","question":"Qual é a diferença entre chiado e intensidade do fluxo de ar?","answer":"O chiado depende do fluxo; obstrução extrema pode reduzir o ruído.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-027","topic":"Asma","question":"Como o estado mental modifica o significado de uma SpO₂ aparentemente aceitável?","answer":"Confusão ou sonolência sinalizam risco de falência respiratória.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-028","topic":"Asma","question":"O que procurar se há sibilos e urticária após alimento?","answer":"Anafilaxia associada ao broncoespasmo.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-029","topic":"Asma","question":"Por que reavaliar após cada ciclo de broncodilatação?","answer":"Para identificar resposta, efeitos adversos e necessidade de escalonamento.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-030","topic":"Asma","question":"Qual pergunta de alta antecipa a próxima exacerbação?","answer":"O paciente sabe quando usar o controlador, o resgate e procurar ajuda?","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-031","topic":"DPOC","question":"Por que um paciente com DPOC pode permanecer hipercápnico quando está estável?","answer":"Pode haver retenção crônica de CO₂ compensada metabolicamente.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-032","topic":"DPOC","question":"O que o bicarbonato alto sugere em hipercapnia persistente?","answer":"Compensação renal crônica.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-033","topic":"DPOC","question":"Que dado transforma retenção de CO₂ em acidose respiratória aguda?","answer":"Queda do pH no contexto de PaCO₂ elevada.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-034","topic":"DPOC","question":"Como usar a saturação no tratamento sem precipitar hiperóxia?","answer":"Titular O₂ e reavaliar para manter alvo controlado.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-035","topic":"DPOC","question":"Por que 'não dar oxigênio a DPOC' é uma regra perigosa?","answer":"Hipoxemia precisa ser corrigida, porém com metas e vigilância.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-036","topic":"DPOC","question":"Que recurso reduz trabalho respiratório quando a ventilação não invasiva é adequada?","answer":"Pressão positiva não invasiva com supervisão.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-037","topic":"DPOC","question":"Quando a máscara de VNI deixa de ser uma opção segura?","answer":"Se há falha de proteção de via aérea ou consciência comprometida.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-038","topic":"DPOC","question":"Por que um pico de dispneia com dor pleurítica exige olhar além da DPOC?","answer":"Pode indicar TEP ou pneumotórax, entre outras causas.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-039","topic":"DPOC","question":"Que pista do escarro sugere etiologia bacteriana de uma exacerbação?","answer":"Mudança para escarro purulento, associada aos outros critérios clínicos.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-040","topic":"DPOC","question":"Qual dimensão a gravidade GOLD 1–4 não descreve sozinha?","answer":"Carga de sintomas e histórico de exacerbações.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-041","topic":"DPOC","question":"Por que um VEF₁ relativamente alto não exclui grupo E?","answer":"O agrupamento ABE atual depende de exacerbações recentes.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-042","topic":"DPOC","question":"Qual etapa confirma limitação persistente em vez de flutuação ocasional?","answer":"Espirometria pós-broncodilatador no contexto clínico correto.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-043","topic":"DPOC","question":"Como o enfisema leva a aprisionamento aéreo?","answer":"Perda do recolhimento elástico dificulta esvaziamento expiratório.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-044","topic":"DPOC","question":"Que tipo de imagem é sugestiva de hiperinsuflação?","answer":"Diafragmas achatados e aumento do espaço retroesternal.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-045","topic":"DPOC","question":"O que as pequenas vias aéreas inflamadas acrescentam ao quadro de DPOC?","answer":"Aumento da resistência ao fluxo expiratório.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-046","topic":"DPOC","question":"Por que uma infecção viral não implica antibiótico automático?","answer":"Nem toda exacerbação apresenta indício de infecção bacteriana.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-047","topic":"DPOC","question":"Que efeito pode limitar repetição indiscriminada de beta-2 agonistas?","answer":"Taquicardia, tremor e hipocalemia.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-048","topic":"DPOC","question":"Que benefício motiva cursos curtos de corticoide sistêmico?","answer":"Acelerar recuperação e reduzir falha, minimizando efeitos adversos.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-049","topic":"DPOC","question":"Por que revisar técnica inalatória após internação?","answer":"Uso incorreto reduz entrega do broncodilatador de manutenção.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-050","topic":"DPOC","question":"Que conduta preventiva tem impacto importante na progressão da doença?","answer":"Cessação do tabagismo e de exposições nocivas.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-051","topic":"DPOC","question":"O que falta ao paciente estável que só recebe receitas sem educação?","answer":"Adesão, técnica, vacinação, reabilitação e prevenção de crises.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-052","topic":"DPOC","question":"Como insuficiência cardíaca pode imitar exacerbação obstrutiva?","answer":"Congestão provoca dispneia e até sibilos.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-053","topic":"DPOC","question":"Por que a gasometria importa mesmo após melhora de SpO₂?","answer":"Ela revela pH e PaCO₂, que a oximetria não informa.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-054","topic":"DPOC","question":"Que combinação ventilatória sugere benefício de VNI?","answer":"Hipercapnia acidótica com esforço e possibilidade de cooperação.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-055","topic":"DPOC","question":"Como reconhecer cor pulmonale no exame físico?","answer":"Edema, turgência jugular e sinais de hipertensão pulmonar.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-056","topic":"DPOC","question":"Qual erro há em usar PaCO₂ isolada para decidir intubação?","answer":"É necessário integrar pH, consciência, trabalho e resposta ao suporte.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-057","topic":"DPOC","question":"Por que a exacerbação pede broncodilatador de curta ação primeiro?","answer":"Alívio rápido da limitação ao fluxo e do desconforto.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-058","topic":"DPOC","question":"Qual história de infecção muda a escolha do antibiótico empírico?","answer":"Culturas prévias e risco de patógenos resistentes.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-059","topic":"DPOC","question":"O que deve acontecer quando uma VNI não melhora acidose e consciência?","answer":"Reavaliar imediatamente e considerar via aérea invasiva.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-060","topic":"DPOC","question":"Como explicar ao paciente o motivo de prevenir novas exacerbações?","answer":"Elas aumentam morbidade, declínio funcional e risco de internação.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-061","topic":"Sepse","question":"Qual é o erro conceitual de definir sepse apenas como 'bactéria no sangue'?","answer":"Sepse é disfunção orgânica por resposta desregulada à infecção.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-062","topic":"Sepse","question":"Por que uma cultura negativa não exclui sepse?","answer":"Nem toda sepse produz bacteremia demonstrável.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-063","topic":"Sepse","question":"Qual alteração de função orgânica pode ser percebida na diurese?","answer":"Oligúria nova sugere hipoperfusão ou lesão renal.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-064","topic":"Sepse","question":"Como a consciência ajuda a identificar gravidade da infecção?","answer":"Confusão nova pode representar disfunção orgânica.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-065","topic":"Sepse","question":"Por que o qSOFA não deve substituir toda triagem?","answer":"Sua sensibilidade é insuficiente como ferramenta isolada.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-066","topic":"Sepse","question":"Que evento diferencia choque séptico de sepse sem choque?","answer":"Insuficiência circulatória persistente apesar de ressuscitação adequada.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-067","topic":"Sepse","question":"Qual é a lógica de coletar culturas antes de antimicrobiano sem causar atraso?","answer":"Aumentar chance de identificação e direcionamento terapêutico.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-068","topic":"Sepse","question":"Por que a probabilidade clínica muda a urgência do antibiótico?","answer":"Choque e sepse provável exigem maior rapidez que suspeita incerta sem choque.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-069","topic":"Sepse","question":"Que característica torna lactato um marcador útil, mas imperfeito?","answer":"Reflete gravidade/alterações metabólicas e deve ser interpretado com perfusão.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-070","topic":"Sepse","question":"Quando a melhora da PAM não garante ressuscitação suficiente?","answer":"Se persistem oligúria, moteamento ou enchimento capilar lento.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-071","topic":"Sepse","question":"Por que o controle do foco pode ser decisivo mesmo com antibiótico potente?","answer":"Coleção ou obstrução infectada pode manter a fonte de microrganismos.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-072","topic":"Sepse","question":"Que foco oculto exige descompressão quando há infecção e obstrução urinária?","answer":"Sistema coletor obstruído, como cálculo com hidronefrose.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-073","topic":"Sepse","question":"Qual é a vantagem de reavaliar responsividade antes de novo fluido?","answer":"Evitar sobrecarga sem benefício hemodinâmico.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-074","topic":"Sepse","question":"Que achados indicam dano potencial por ressuscitação excessiva?","answer":"Congestão pulmonar, edema e piora da oxigenação.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-075","topic":"Sepse","question":"Por que noradrenalina é útil na vasoplegia do choque séptico?","answer":"Eleva resistência vascular e ajuda a manter perfusão arterial.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-076","topic":"Sepse","question":"Que objetivo representa inicialmente a PAM-alvo?","answer":"Referência mínima de perfusão a ser ajustada ao indivíduo.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-077","topic":"Sepse","question":"Que atitude usar quando uma via venosa central ainda não está disponível?","answer":"Não atrasar vasopressor urgente se há acesso periférico seguro.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-078","topic":"Sepse","question":"Por que queda de lactato deve ser acompanhada de exame físico?","answer":"O lactato pode melhorar antes de a hipoperfusão desaparecer.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-079","topic":"Sepse","question":"Qual é a diferença prática entre descalonar e interromper empiricamente?","answer":"Descalonar estreita cobertura conforme evidência; interromper remove tratamento.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-080","topic":"Sepse","question":"Quando considerar investigar infecção de dispositivo?","answer":"Quando há cateter e sinais locais ou bacteremia sem outro foco.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-081","topic":"Sepse","question":"Por que a idade avançada exige atenção para hipotermia?","answer":"Infecção grave pode ocorrer sem febre clássica.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-082","topic":"Sepse","question":"Que sinal vascular periférico sugere microcirculação comprometida?","answer":"Moteamento, pele fria ou enchimento capilar demorado.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-083","topic":"Sepse","question":"Qual vantagem de titular fluidos com métodos dinâmicos?","answer":"Estimam probabilidade de melhorar débito com mais volume.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-084","topic":"Sepse","question":"O que deve motivar revisar antibiótico em 48–72 horas?","answer":"Microbiologia disponível, resposta clínica e foco identificado.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-085","topic":"Sepse","question":"Que condição permite antibiótico com espectro menor?","answer":"Patógeno e susceptibilidade conhecidos, com estabilidade clínica.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-086","topic":"Sepse","question":"Que fator diferencia profilaxia antimicrobiana de tratamento de sepse?","answer":"Na sepse há infecção que requer tratamento, não prevenção inespecífica.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-087","topic":"Sepse","question":"Por que corrigir hipotensão não basta se há disfunção miocárdica?","answer":"Pode permanecer baixo débito com perfusão insuficiente.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-088","topic":"Sepse","question":"Que risco há em chamar toda febre de sepse?","answer":"Exposição a intervenções desnecessárias sem disfunção documentada.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-089","topic":"Sepse","question":"Quando suspeitar de choque refratário?","answer":"Persistência de instabilidade/perfusão ruim apesar do manejo inicial apropriado.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-090","topic":"Sepse","question":"Que pergunta evita ancoragem terapêutica em sepse que não melhora?","answer":"O foco infeccioso foi realmente identificado e controlado?","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-091","topic":"Queimaduras","question":"Por que uma queimadura pode doer menos quanto mais profunda for?","answer":"Destruição de terminações nervosas reduz sensibilidade local.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-092","topic":"Queimaduras","question":"Qual diferença visual ajuda a distinguir derme superficial de espessura total?","answer":"Úmida e rósea com bolhas versus seca, rígida e insensível.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-093","topic":"Queimaduras","question":"O que torna a regra dos nove menos precisa em crianças pequenas?","answer":"A proporção cabeça/pernas muda com a idade.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-094","topic":"Queimaduras","question":"Por que eritema sem bolhas não entra na SCQ de ressuscitação?","answer":"É lesão superficial de epiderme, sem perda dérmica extensa.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-095","topic":"Queimaduras","question":"Que raciocínio explica a recomendação de menor volume inicial da ABA?","answer":"Reduzir excesso de fluido e edema, mantendo titulação pela resposta.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-096","topic":"Queimaduras","question":"Por que contar o relógio desde a queimadura importa na Parkland?","answer":"A janela de reposição começa no momento da lesão.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-097","topic":"Queimaduras","question":"O que o volume calculado não consegue prever sozinho?","answer":"Necessidade real de fluidos, avaliada por perfusão e diurese.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-098","topic":"Queimaduras","question":"Como reconhecer hiper-resuscitação?","answer":"Edema progressivo, comprometimento ventilatório ou pressão abdominal alta.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-099","topic":"Queimaduras","question":"Qual é a pista de queimadura com circulação distal ameaçada?","answer":"Queimadura circunferencial rígida com sinais de hipoperfusão distal.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-100","topic":"Queimaduras","question":"Quando pensar em liberação da escara torácica?","answer":"Quando a rigidez restringe expansão e ventilação.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-101","topic":"Queimaduras","question":"Que complicação grave pode existir em incêndio com pouca queimadura cutânea?","answer":"Lesão inalatória ou intoxicação por gases.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-102","topic":"Queimaduras","question":"Por que SpO₂ normal não exclui exposição relevante a monóxido?","answer":"Oxímetro comum não diferencia carboxi-hemoglobina.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-103","topic":"Queimaduras","question":"Que sinal respiratório após fumaça preocupa mais que a área cutânea?","answer":"Estridor ou rouquidão progressiva.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-104","topic":"Queimaduras","question":"Como escolher centro de referência com pequena área mas mão profundamente queimada?","answer":"Considerar localização funcional e profundidade, não só porcentagem.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-105","topic":"Queimaduras","question":"Por que o gelo direto é uma má escolha para primeiros socorros?","answer":"Pode agravar dano tecidual por frio excessivo.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-106","topic":"Queimaduras","question":"O que fazer com anéis antes de edema importante de mão queimada?","answer":"Remover precocemente para evitar constrição.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-107","topic":"Queimaduras","question":"Que objetivo a cobertura limpa de uma queimadura aguda atende?","answer":"Proteger a lesão enquanto se organiza avaliação e curativo apropriados.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-108","topic":"Queimaduras","question":"Por que antibiótico sistêmico não é 'pomada obrigatória' para toda queimadura?","answer":"Não há indicação automática sem infecção ou outra razão específica.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-109","topic":"Queimaduras","question":"Que risco oculto diferencia alta tensão de escaldadura superficial?","answer":"Lesão muscular profunda, rabdomiólise e arritmias.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-110","topic":"Queimaduras","question":"Como retirar exposição química contínua?","answer":"Remover roupas contaminadas e irrigar conforme agente/protocolo.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-111","topic":"Queimaduras","question":"Qual é a principal vantagem de observar o enchimento capilar da queimadura?","answer":"Ajuda a inferir profundidade e perfusão local.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-112","topic":"Queimaduras","question":"Que sintoma exige investigar perfusão em queimadura circunferencial de perna?","answer":"Parestesia, dor progressiva ou pé frio.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-113","topic":"Queimaduras","question":"Qual é a função do exame por co-oximetria em exposição à fumaça?","answer":"Medir carboxi-hemoglobina quando indicado.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-114","topic":"Queimaduras","question":"Por que resfriar área extensa exige proteção térmica do paciente?","answer":"Prevenir hipotermia sistêmica.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-115","topic":"Queimaduras","question":"Que estruturas adicionais podem estar lesadas no chamado quarto grau?","answer":"Músculo, tendão ou osso além da pele.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-116","topic":"Queimaduras","question":"Qual é o problema de aplicar a mesma área palmar sem ajuste em pediatria?","answer":"As proporções corporais variam e a estimativa pode distorcer.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-117","topic":"Queimaduras","question":"Como explicar a necessidade de reavaliar diurese hora a hora?","answer":"Ela funciona como marcador simples de resposta ao volume.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-118","topic":"Queimaduras","question":"Por que pele endurecida em anel pode reduzir pulso distal?","answer":"A escara não se expande com edema e comprime estruturas.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-119","topic":"Queimaduras","question":"Qual componente do atendimento impede que curativos atrasem manejo vital?","answer":"ABCDE, com foco inicial na via aérea e na perfusão.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-120","topic":"Queimaduras","question":"Como diferenciar fórmula de prova clássica e protocolo atual?","answer":"O enunciado deve indicar Parkland 4 ou orientação ABA de 2 mL/kg/%SCQ.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-121","topic":"Politraumatismo","question":"Qual ideia resume toda a avaliação primária do trauma?","answer":"Reconhecer e tratar imediatamente cada ameaça vital encontrada.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-122","topic":"Politraumatismo","question":"Por que controlar hemorragia externa pode anteceder via aérea?","answer":"Perda sanguínea catastrófica pode matar em minutos.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-123","topic":"Politraumatismo","question":"Que problema o jaw thrust procura evitar no trauma cervical?","answer":"Extensão desnecessária do pescoço.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-124","topic":"Politraumatismo","question":"Por que Glasgow normal não exclui choque hemorrágico?","answer":"A consciência pode permanecer preservada durante compensação.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-125","topic":"Politraumatismo","question":"Que valor tem a taquicardia antes da queda pressórica?","answer":"Pode ser sinal precoce de perda circulatória.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-126","topic":"Politraumatismo","question":"Por que Hb inicial normal não tranquiliza em sangramento agudo?","answer":"A concentração pode demorar a refletir a perda de volume.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-127","topic":"Politraumatismo","question":"Que falha decorre de usar apenas vasopressor em choque hemorrágico?","answer":"Aumenta PA sem repor sangue nem controlar a fonte.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-128","topic":"Politraumatismo","question":"Onde procurar sangue oculto além das feridas externas?","answer":"Tórax, abdome, pelve, retroperitônio e ossos longos.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-129","topic":"Politraumatismo","question":"Que problema resolve uma cinta pélvica bem posicionada?","answer":"Reduz movimentação e volume da pelve instável.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-130","topic":"Politraumatismo","question":"Por que torniquete aplicado deve ter horário registrado?","answer":"Para orientar reavaliação e segurança do manejo.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-131","topic":"Politraumatismo","question":"Que objetivo inspira a transfusão balanceada?","answer":"Repor eritrócitos e componentes da coagulação em sangramento maciço.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-132","topic":"Politraumatismo","question":"Por que líquidos frios em excesso podem prejudicar o trauma grave?","answer":"Agravamento de hipotermia e coagulopatia.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-133","topic":"Politraumatismo","question":"Que condições compõem a chamada tríade letal?","answer":"Acidose, hipotermia e coagulopatia.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-134","topic":"Politraumatismo","question":"Como o ácido tranexâmico se encaixa no controle de sangramento?","answer":"É adjuvante precoce em casos elegíveis, não substitui hemostasia.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-135","topic":"Politraumatismo","question":"O que o XABCDE não permite adiar?","answer":"Tratamento de ameaças vitais até o fim da avaliação secundária.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-136","topic":"Politraumatismo","question":"Por que capnografia ajuda após intubação?","answer":"Confirma e acompanha ventilação traqueal pela onda de CO₂.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-137","topic":"Politraumatismo","question":"Que achado após IOT sugere tubo mal posicionado?","answer":"Ausência de onda capnográfica e ventilação gástrica.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-138","topic":"Politraumatismo","question":"Qual é a diferença entre avaliação primária e secundária?","answer":"Primária trata ameaças imediatas; secundária procura lesões adicionais.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-139","topic":"Politraumatismo","question":"Que dados costumam compor a etapa D?","answer":"Glasgow, pupilas e déficits neurológicos rápidos.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-140","topic":"Politraumatismo","question":"Por que a etapa E não significa deixar o paciente descoberto?","answer":"A exposição deve vir com prevenção da hipotermia.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-141","topic":"Politraumatismo","question":"Qual mnemônico ajuda a história após estabilização?","answer":"AMPLE.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-142","topic":"Politraumatismo","question":"Por que a pelve instável não deve ser testada várias vezes?","answer":"Manipulação excessiva pode agravar hemorragia.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-143","topic":"Politraumatismo","question":"Que lição clínica um FAST negativo em choque ensina?","answer":"É preciso procurar outras fontes, como pelve e retroperitônio.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-144","topic":"Politraumatismo","question":"Quando repetir o XABCDE durante o atendimento?","answer":"Sempre que a condição clínica mudar ou houver deterioração.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-145","topic":"Politraumatismo","question":"Que perigo a infusão maciça de citrato representa?","answer":"Hipocalcemia que pode prejudicar coagulação e contratilidade.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-146","topic":"Politraumatismo","question":"Por que hemorragia externa aparente exige ação antes da TC?","answer":"Controle da fonte é mais urgente que caracterização por imagem.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-147","topic":"Politraumatismo","question":"Como evitar atrasar cirurgia em sangramento abdominal grave?","answer":"Reanimar em paralelo à preparação de controle definitivo.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-148","topic":"Politraumatismo","question":"Qual é a prioridade diante de falência ventilatória após trauma?","answer":"Assegurar ventilação e tratar causa reversível no B.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-149","topic":"Politraumatismo","question":"Por que a pressão de chegada é informação insuficiente?","answer":"O choque pode ser compensado e mudar rapidamente.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-150","topic":"Politraumatismo","question":"Que princípio evita fixação em fratura vistosa enquanto outra lesão mata?","answer":"Priorizar fisiologia e ameaça vital, não a aparência da lesão.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-151","topic":"TCE","question":"Por que TCE grave é frequentemente uma emergência de oxigenação?","answer":"Hipóxia pode intensificar lesão cerebral secundária.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-152","topic":"TCE","question":"Como a PAM pode influenciar a perfusão do cérebro lesionado?","answer":"PPC é o gradiente PAM menos PIC.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-153","topic":"TCE","question":"O que acontece com a PPC quando a PIC aumenta e a PAM permanece fixa?","answer":"A PPC diminui.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-154","topic":"TCE","question":"Que risco explica evitar hipotensão permissiva em TCE grave?","answer":"Isquemia cerebral por perfusão inadequada.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-155","topic":"TCE","question":"Por que uma PaCO₂ muito baixa pode prejudicar o cérebro?","answer":"Vasoconstrição cerebral diminui fluxo e pode causar isquemia.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-156","topic":"TCE","question":"Que fenômeno é sugerido por midríase unilateral com piora da consciência?","answer":"Possível herniação uncal e compressão do III par.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-157","topic":"TCE","question":"Qual achado diferencia epidural típico de subdural típico na TC?","answer":"Epidural lentiforme; subdural em crescente.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-158","topic":"TCE","question":"Por que o intervalo lúcido após pancada temporal não autoriza alta?","answer":"Pode anteceder expansão de hematoma epidural.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-159","topic":"TCE","question":"Como o uso de anticoagulante altera avaliação de queda aparentemente banal?","answer":"Eleva suspeita de sangramento intracraniano.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-160","topic":"TCE","question":"Que estrutura pode estar lesada quando há equimose retroauricular?","answer":"Base do crânio.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-161","topic":"TCE","question":"Que consequência pode decorrer de rinorreia aquosa pós-trauma?","answer":"Fístula liquórica por possível fratura de base.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-162","topic":"TCE","question":"Por que manipulação nasal exige cautela em suspeita de fratura de base?","answer":"Pode criar risco adicional de instrumentação inadequada.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-163","topic":"TCE","question":"Que transformação motora reduz pontuação em relação à retirada normal?","answer":"Flexão estereotipada anormal ou extensão.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-164","topic":"TCE","question":"Qual a diferença entre localizar e retirar estímulo doloroso?","answer":"Localizar leva a mão até a fonte; retirar apenas afasta o membro.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-165","topic":"TCE","question":"Como avaliar pupilometria na Glasgow-P?","answer":"Subtrair 1 por pupila não reativa, até 2.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-166","topic":"TCE","question":"Que situação pode produzir coma profundo com TC inicialmente discreta?","answer":"Lesão axonal difusa.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-167","topic":"TCE","question":"O que o mecanismo de aceleração/desaceleração pode romper microscopicamente?","answer":"Axônios pela força de cisalhamento.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-168","topic":"TCE","question":"Por que vômitos repetidos após TCE leve não devem ser ignorados?","answer":"São fator de risco em critérios de decisão para TC.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-169","topic":"TCE","question":"Que conjunto sugere hipertensão intracraniana crítica?","answer":"Hipertensão, bradicardia e respiração irregular.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-170","topic":"TCE","question":"Por que uma pupila reativa não permite excluir hematoma?","answer":"Exame pupilar normal pode ocorrer em fases iniciais da lesão.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-171","topic":"TCE","question":"Qual cuidado de via aérea tem prioridade se Glasgow é muito baixo e há vômitos?","answer":"Aspirar e proteger via aérea conforme capacidade de ventilação/proteção.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-172","topic":"TCE","question":"O que significa uma queda de dois pontos do Glasgow ao longo do plantão?","answer":"Deterioração neurológica que exige reavaliação urgente.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-173","topic":"TCE","question":"Como identificar resposta verbal confusa em vez de palavras inadequadas?","answer":"O paciente conversa inteligivelmente, mas está desorientado.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-174","topic":"TCE","question":"Qual risco hemodinâmico acompanha aumento persistente da PIC?","answer":"Redução da PPC e isquemia.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-175","topic":"TCE","question":"Por que exame neurológico seriado tem valor mesmo após TC?","answer":"O estado pode mudar com expansão de lesões ou edema.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-176","topic":"TCE","question":"Que lesão focal costuma ser associada à artéria meníngea média?","answer":"Hematoma epidural temporal.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-177","topic":"TCE","question":"Como interpretar um Glasgow 14 no contexto de trauma com anticoagulação?","answer":"Não é garantia isolada de ausência de hemorragia.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-178","topic":"TCE","question":"Que tipo de fratura pode produzir olhos de guaxinim?","answer":"Fratura da base do crânio.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-179","topic":"TCE","question":"Por que corrigir hipoxemia antes de TC é uma prioridade?","answer":"Reduz risco de dano cerebral secundário durante transporte.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-180","topic":"TCE","question":"Qual é a pergunta-chave ao reconhecer anisocoria nova?","answer":"Há deterioração intracraniana ou herniação em evolução?","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-181","topic":"Trauma torácico","question":"Por que uma descompressão de emergência pode ser feita sem radiografia?","answer":"Pneumotórax hipertensivo instável é diagnóstico clínico tempo-dependente.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-182","topic":"Trauma torácico","question":"Que mecanismo transforma pneumotórax simples em tensão?","answer":"Ar sob pressão crescente que compromete ventilação e retorno venoso.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-183","topic":"Trauma torácico","question":"Por que o desvio traqueal não é requisito para tensão?","answer":"Pode surgir tarde ou não ser evidente.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-184","topic":"Trauma torácico","question":"Como a pressão positiva pode agravar um pneumotórax não tratado?","answer":"Aumenta a pressão intrapleural e pode precipitar choque.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-185","topic":"Trauma torácico","question":"Que achado percussivo favorece ar pleural em vez de sangue?","answer":"Hipersonoridade em vez de macicez.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-186","topic":"Trauma torácico","question":"Que mecanismo hemodinâmico está presente no tamponamento?","answer":"Compressão cardíaca que limita enchimento e débito.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-187","topic":"Trauma torácico","question":"Quais sons de ausculta são reduzidos na tríade clássica de Beck?","answer":"Bulhas cardíacas abafadas.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-188","topic":"Trauma torácico","question":"Que diferença importante existe entre tamponamento e hemotórax maciço?","answer":"Choque obstrutivo versus choque predominantemente hemorrágico.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-189","topic":"Trauma torácico","question":"Por que o primeiro volume do dreno não basta para decidir cirurgia?","answer":"Sangramento contínuo e fisiologia também importam.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-190","topic":"Trauma torácico","question":"Que risco há em fechar totalmente ferida aspirativa sem via de escape?","answer":"Pode gerar pneumotórax hipertensivo.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-191","topic":"Trauma torácico","question":"Qual movimento denuncia segmento de parede torácica instável?","answer":"Entrar na inspiração e sair na expiração.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-192","topic":"Trauma torácico","question":"Por que a analgesia modifica prognóstico em fraturas costais?","answer":"Permite respirar fundo, tossir e evitar atelectasias.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-193","topic":"Trauma torácico","question":"O que pode explicar hipoxemia piorando horas após contusão?","answer":"Edema e sangramento alveolar evolutivos.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-194","topic":"Trauma torácico","question":"Que indício após trauma sugere ruptura central das vias aéreas?","answer":"Fuga aérea persistente e enfisema subcutâneo extenso.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-195","topic":"Trauma torácico","question":"Quando buscar lesão de aorta após desaceleração?","answer":"Dor interescapular ou mediastino alargado, conforme mecanismo.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-196","topic":"Trauma torácico","question":"Qual exame ajuda a visualizar aorta em paciente estável?","answer":"Angiotomografia contrastada de tórax.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-197","topic":"Trauma torácico","question":"Por que posição do tubo merece checagem antes de culpar pleura?","answer":"Intubação seletiva pode causar assimetria ventilatória.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-198","topic":"Trauma torácico","question":"Que achado indica necessidade de reavaliar drenagem pleural imediatamente?","answer":"Choque, débito sanguíneo alto ou perda aérea persistente.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-199","topic":"Trauma torácico","question":"Como o choque pode coexistir com MV ausente e macicez unilateral?","answer":"Hemotórax maciço.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-200","topic":"Trauma torácico","question":"Que medida vem antes da investigação extensa em lesão torácica letal?","answer":"Tratamento da ameaça fisiológica imediata.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-201","topic":"Trauma torácico","question":"Por que tórax instável não é sinônimo de intubação mandatória?","answer":"A decisão depende de oxigenação, esforço, contusão e consciência.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-202","topic":"Trauma torácico","question":"Que combinação de sintomas sugere pneumotórax aberto?","answer":"Ferida torácica comunicante com sucção de ar e dispneia.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-203","topic":"Trauma torácico","question":"O que a hipersonoridade unilateral acrescenta à ausência de MV?","answer":"Favorece presença de ar pleural.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-204","topic":"Trauma torácico","question":"Por que não se deve insistir em TC com choque grave no tórax?","answer":"Intervenção vital não pode ser adiada por imagem.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-205","topic":"Trauma torácico","question":"Que sinal de trauma torácico pode coexistir com aorta lesionada e estabilidade inicial?","answer":"Mediastino alargado no RX.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-206","topic":"Trauma torácico","question":"Como a tosse fraca por dor favorece complicação pulmonar?","answer":"Retém secreção, favorecendo atelectasia/pneumonia.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-207","topic":"Trauma torácico","question":"Que dado não pode ser ignorado após drenagem de grande hemotórax?","answer":"Resposta hemodinâmica e necessidade de transfusões.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-208","topic":"Trauma torácico","question":"Por que ultrassom do pericárdio é útil no trauma torácico?","answer":"Pode revelar derrame associado a tamponamento.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-209","topic":"Trauma torácico","question":"O que significa enfisema subcutâneo que aumenta apesar de dreno funcional?","answer":"Possibilidade de fuga aérea persistente/lesão traqueobrônquica.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-210","topic":"Trauma torácico","question":"Que pergunta torna a avaliação do B mais segura?","answer":"Há alguma lesão torácica capaz de matar antes do próximo exame?","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-211","topic":"Trauma abdominal","question":"Por que FAST negativo não é certificado de abdome normal?","answer":"Pode não mostrar víscera oca, retroperitônio ou sangramento inicial discreto.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-212","topic":"Trauma abdominal","question":"Como a estabilidade hemodinâmica define a escolha de imagem abdominal?","answer":"TC detalha lesões em estáveis; instáveis exigem decisões rápidas.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-213","topic":"Trauma abdominal","question":"Que fenômeno explica dor de ombro esquerdo em trauma esplênico?","answer":"Irritação diafragmática com dor referida.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-214","topic":"Trauma abdominal","question":"Por que equimose de cinto merece acompanhamento seriado?","answer":"Pode revelar lesão intestinal/mesentérica inicialmente sutil.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-215","topic":"Trauma abdominal","question":"Que lesão considerar após golpe de guidão com FAST normal?","answer":"Pâncreas e duodeno, em parte retroperitoneais.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-216","topic":"Trauma abdominal","question":"Qual área abdominal abriga sangramento que pode escapar ao FAST?","answer":"Retroperitônio.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-217","topic":"Trauma abdominal","question":"Como lesão renal pode se anunciar em vítima hemodinamicamente estável?","answer":"Hematúria após trauma de flanco.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-218","topic":"Trauma abdominal","question":"Por que Hb normal de chegada não elimina hemorragia abdominal?","answer":"A concentração demora a refletir perda de sangue aguda.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-219","topic":"Trauma abdominal","question":"Quando sinais de peritonite mudam o plano de investigação?","answer":"Podem indicar necessidade de abordagem cirúrgica urgente.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-220","topic":"Trauma abdominal","question":"Que características favorecem vigilância não operatória do baço?","answer":"Estabilidade, ausência de peritonite e recursos para monitorização.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-221","topic":"Trauma abdominal","question":"O que pode indicar contraste vazando na TC de órgão sólido?","answer":"Sangramento ativo passível de intervenção.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-222","topic":"Trauma abdominal","question":"Que sinal de percussão aponta para ar livre intraperitoneal?","answer":"Jobert: desaparecimento da macicez hepática.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-223","topic":"Trauma abdominal","question":"Como distinguir Cullen de Grey Turner pela localização?","answer":"Cullen é periumbilical; Grey Turner, nos flancos.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-224","topic":"Trauma abdominal","question":"Por que dor crescente horas após trauma é mais relevante que dor inicial leve?","answer":"Pode indicar lesão intestinal evoluindo para peritonite.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-225","topic":"Trauma abdominal","question":"Que papel a reavaliação tem após TC aparentemente discreta?","answer":"Reconhecer piora clínica e lesões ocultas.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-226","topic":"Trauma abdominal","question":"Qual órgão é especialmente lembrado em trauma do hipocôndrio direito?","answer":"Fígado.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-227","topic":"Trauma abdominal","question":"Qual órgão é comum no trauma contuso do hipocôndrio esquerdo?","answer":"Baço.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-228","topic":"Trauma abdominal","question":"Por que trauma penetrante de flanco pode exigir investigação retroperitoneal?","answer":"A trajetória pode atingir rim, ureter ou cólon retroperitoneal.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-229","topic":"Trauma abdominal","question":"Que erro ocorre ao mandar instável para TC demorada?","answer":"Atrasa hemostasia definitiva e aumenta risco de morte.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-230","topic":"Trauma abdominal","question":"Como o exame perde sensibilidade em paciente sedado?","answer":"Defesa e dor voluntárias podem não ser avaliáveis.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-231","topic":"Trauma abdominal","question":"Que exame pode ajudar a identificar líquido livre na avaliação primária?","answer":"FAST/eFAST, com limitações.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-232","topic":"Trauma abdominal","question":"Por que lesão esplênica não exige automaticamente laparotomia?","answer":"Estáveis podem se beneficiar de manejo não operatório monitorizado.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-233","topic":"Trauma abdominal","question":"Quando pensar em angioembolização para órgão sólido?","answer":"Extravasamento ativo com estabilidade e disponibilidade especializada.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-234","topic":"Trauma abdominal","question":"Que achado físico preocupa em trauma abdominal penetrante?","answer":"Evisceração, rigidez, peritonismo ou choque.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-235","topic":"Trauma abdominal","question":"Que lesão associar a fraturas de costelas inferiores à esquerda?","answer":"Lesão esplênica.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-236","topic":"Trauma abdominal","question":"Que impacto abdominal pode acompanhar pequena marca externa e dano interno relevante?","answer":"Trauma contuso por desaceleração ou guidão.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-237","topic":"Trauma abdominal","question":"Por que insistir em exames repetidos sem mudar conduta pode ser perigoso?","answer":"A fisiologia pode deteriorar enquanto o sangramento progride.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-238","topic":"Trauma abdominal","question":"Que informação orienta investigação de ferimento penetrante estável?","answer":"Trajetória provável e exame físico seriado.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-239","topic":"Trauma abdominal","question":"Como diferenciar contusão superficial de possível lesão mesentérica?","answer":"Mecanismo, sinal do cinto, dor progressiva e achados de imagem.","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"},{"id":"F4-240","topic":"Trauma abdominal","question":"Qual pergunta fecha uma avaliação abdominal segura?","answer":"A estabilidade e o exame mudaram desde a última reavaliação?","source":"Flashcard conceitual autoral — associação, causalidade e aplicação clínica"}],"revision":"2026-11-23","meta":{"newQuestions":439,"flashcards":240,"topics":["Asma","DPOC","Sepse","Queimaduras","Politraumatismo","TCE","Trauma torácico","Trauma abdominal"]}};
